/* Mestrado em Epidemiologia (IMS/UERJ): question bank and chapter summaries.
 * Generated by scripts/build_mestrado.py from data/mestrado/*.txt. Do not edit by hand. */
window.MESTRADO = {"caps":{"1":{"n":1,"title":"Formação Histórica da Epidemiologia","authors":"Naomar de Almeida Filho, Roberto A. Medronho","from":3,"to":12},"2":{"n":2,"title":"Medidas de Frequência de Doença","authors":"Antonio José Leal Costa, Pauline Lorena Kale","from":13,"to":30},"3":{"n":3,"title":"Indicadores de Saúde","authors":"Antonio José Leal Costa, Pauline Lorena Kale, Mário Vermelho","from":31,"to":82},"4":{"n":4,"title":"Distribuição das Doenças no Espaço e no Tempo","authors":"Roberto A. Medronho, Guilherme L. Werneck, Maurício A. Perez","from":83,"to":102},"5":{"n":5,"title":"Vigilância Epidemiológica","authors":"José Ueleres Braga, Guilherme L. Werneck","from":103,"to":122},"6":{"n":6,"title":"Transição Demográfica e Epidemiológica","authors":"Pontes, Ramos Jr., Kerr, Bosi","from":123,"to":151},"8":{"n":8,"title":"Fundamentos da Pesquisa Epidemiológica","authors":"Katia Vergetti Bloch, Evandro da Silva Freire Coutinho","from":173,"to":179},"18":{"n":18,"title":"Análise Exploratória de Dados","authors":"Rejane Sobrino Pinheiro, Tânia Zdenka Guillen de Torres","from":323,"to":341}},"sections":[{"id":"s1-1","cap":1,"title":"Antiguidade ao século XVIII","from":3,"to":4,"pts":["Hipócrates (Ares, Águas e Lugares): doença ligada a clima, água e modo de vida; termos epidêmico e endêmico.","Asclépios e suas filhas: Panaceia (cura) e Higeia (prevenção, vida saudável).","Roma: censos e registro obrigatório de nascimentos e óbitos. Galeno; depois Avicena e Averróis.","Três eixos que formam a epidemiologia (Almeida Filho): clínica moderna, Estatística e Medicina Social.","Sydenham: constituição epidêmica e história natural das doenças. Petty (Aritmética Política), Graunt (tábuas de mortalidade), Conring (\"Statistik\" = assuntos de Estado).","Probabilidade: Pascal, Bernoulli (vacinação contra varíola), Laplace."],"n":4},{"id":"s1-2","cap":1,"title":"Século XIX: método numérico e medicina social","from":5,"to":6,"pts":["Pierre Louis (1825): estudo de 1.960 casos de tuberculose com o \"método numérico\", visto como início da epidemiologia.","William Farr (1839): registro geral de estatísticas vitais e classificação de causas de morte.","Medicina urbana (França), polícia médica do Estado (Alemanha), medicina da força de trabalho (Inglaterra).","Jules Guérin cunha \"Medicina Social\" (1838). Virchow e a epidemia de tifo.","Sociedade Epidemiológica de Londres (1850): Florence Nightingale (infecção na Crimeia) e John Snow (cólera e água).","Angelerio (séc. XVI) usou o termo \"epidemiologia\" pela primeira vez; Villalba publicou a \"Epidemiología Española\" (1802).","Era bacteriológica (Pasteur, Koch): fortalece o enfoque clínico, individual e curativo. Relatório Flexner (1910).","Johns Hopkins (1918, Rockefeller): Wade Hampton Frost, 1º professor de Epidemiologia. Major Greenwood em Londres (1928)."],"n":7},{"id":"s1-3","cap":1,"title":"Século XX: risco, preventivismo e métodos","from":7,"to":8,"pts":["O conceito de risco vira objeto central (Topley 1919; Howard 1921; Frost 1933).","Goldberger (1915): pelagra é carencial, não infecciosa. Ryle (1936): história natural e medicina preventiva.","Prevenção primária, secundária e terciária (preventivismo, muito retórico).","Anos 1950: grandes coortes (Framingham) e ensaios clínicos (Bradford Hill); IEA (1954); American Journal of Epidemiology (1964).","Cornfield: estimadores do risco relativo e regressão logística. Anos 1960: computação e análise multivariada (confundimento).","Anos 1970-80: bases matemáticas, epidemiologia clínica (Feinstein) e abordagens críticas e sociais (Cassel).","Hoje: epidemiologia molecular, genética, farmacoepidemiologia, etnoepidemiologia, epidemiologia de serviços."],"n":3},{"id":"s1-4","cap":1,"title":"Epidemiologia no Brasil","from":8,"to":11,"pts":["Medicina tropical e Escola Tropicalista Baiana (pré-pasteuriana).","Oswaldo Cruz (1903): febre amarela, peste, varíola. A vacinação obrigatória gera a Revolta da Vacina (1904).","Carlos Chagas: malária em Itatinga (1905) e o Trypanosoma cruzi (1909).","Rockefeller, Instituto/Faculdade de Higiene e Saúde Pública (SP), SESP (1942).","Erradicação da varíola e controle da poliomielite levam ao Sistema Nacional de Vigilância Epidemiológica (meados dos anos 1970).","ABRASCO (1979); VIII Conferência Nacional de Saúde (1986, marco do SUS); Planos Diretores da Epidemiologia; Congressos (Campinas 1990: \"Epidemiologia e desigualdade social\"); CENEPI (1990).","Grande crescimento da pós-graduação e da produção científica em Saúde Coletiva."],"n":6},{"id":"s2-1","cap":2,"title":"Conceitos: prevalência × incidência","from":13,"to":15,"pts":["Medir é estimar: os valores vêm de amostras.","Prevalência: casos existentes num momento (fotografia, medida estática, estudo transversal).","Incidência: casos novos num intervalo, entre quem estava sob risco (medida dinâmica, estudos longitudinais).","Definição de caso: critérios clínicos, laboratoriais e epidemiológicos. Erros de classificação dependem de sensibilidade e especificidade.","Incidência = 1º episódio; \"incidência total\" = todos os episódios (doenças agudas sem imunidade).","Toda medida deve ser referida a tempo, lugar e população. Para comparar, usam-se frequências relativas."],"n":8},{"id":"s2-2","cap":2,"title":"Taxa de incidência e pessoa-tempo","from":16,"to":21,"pts":["Taxa = variação de um fenômeno por unidade de tempo. Taxa relativa = por tempo e por população sob risco.","TI = casos novos / pessoa-tempo (densidade de incidência, força de morbidade).","Pessoa-tempo: soma do tempo de cada um sob risco (1 pessoa × 1 ano = 2 × 6 meses = 1 pessoa-ano).","População fechada (coorte fixa, sem entradas) × dinâmica (aberta) × estável (estacionária: saídas repostas).","Perdas (censura): migração, recusa, morte por outra causa, fim do estudo. Contribuem até a saída; assume-se o meio do intervalo.","População estável: PT ≈ N' × Δt. A população de 1º de julho aproxima as pessoas-ano do ano.","TI tem dimensão tempo⁻¹, vai de 0 a infinito e pode passar de 1. Não é exatamente risco: TI × Δt ≈ risco se a TI for constante e o Δt curto."],"n":25},{"id":"s2-3","cap":2,"title":"Incidência acumulada, sobrevida e odds","from":21,"to":24,"pts":["IA = casos novos / não-doentes no início (proporção, de 0 a 1, estima o risco médio do grupo).","Sinônimos: proporção de incidência, incidência cumulativa, taxa de ataque (surtos).","Com perdas (método atuarial): IA = I / (N'0 − W/2). IA de vários anos = 1 − Π(1 − IAano).","A IA sempre precisa da referência de tempo (0,4 em horas ≠ 0,4 em dias).","Sobrevida S = 1 − IA. Hazard (taxa de dano, força de mortalidade) = taxa instantânea.","Odds de incidência = IA/(1 − IA): pouco usada como frequência, mas a odds ratio é muito usada."],"n":21},{"id":"s2-4","cap":2,"title":"Mortalidade e letalidade","from":24,"to":25,"pts":["Mortalidade = incidência do evento óbito; denominador = toda a população (pessoa-tempo).","Mortalidade geral = todas as causas. \"Por x\" = causa básica; \"com x\" = causa associada.","Letalidade = óbitos entre os que têm a doença (proporção ou taxa), sempre com referência de tempo.","Mortalidade = f(incidência, letalidade): raiva tem letalidade ~100% mas mortalidade baixa."],"n":7},{"id":"s2-5","cap":2,"title":"Prevalência e seus determinantes","from":25,"to":30,"pts":["Prevalência pontual = casos existentes / população num instante. Proporção, não \"taxa\"; chance de prevalência = P/(1 − P).","Determinantes: incidência, duração e migração. Agudas (alta incidência, curta duração) têm prevalência baixa; crônicas, alta.","Modelo em população estável: P/(1 − P) = TI × D; se P é pequena, P ≈ TI × D (1%/ano × 15 anos ≈ 15%).","Prevalência de período = (casos no início + novos)/N, pouco usada. Prevalência de toda a vida: igual à pontual nas incuráveis.","Soroprevalência: anticorpos indicam infecção atual ou passada.","Usos: planejar serviços. Em geral é inadequada para etiologia (mistura risco com sobrevida e não dá a sequência temporal).","Malformações congênitas e baixo peso ao nascer: prevalência ao nascer. Prevalência também serve para doenças de início insidioso."],"n":45},{"id":"s3-1","cap":3,"title":"Conceito, histórico e requisitos","from":31,"to":35,"pts":["Indicador: mede o que não se observa diretamente (nível de saúde). Mede-se a saúde pelo \"lado negativo\".","Transição demográfica e epidemiológica deslocam o foco: mortalidade, depois morbidade, depois funcionalidade e qualidade de vida.","Requisitos: disponibilidade, uniformidade, simplicidade, sinteticidade, poder discriminatório, validade, relevância, ética.","Grupos da OMS (1957): saúde, meio ambiente, serviços (insumos, processo, resultado).","Indicador (um aspecto) × índice (várias dimensões: Apgar, IDH).","Proporção × coeficiente/taxa; população do meio do ano ≈ pessoa-tempo; residência (risco) × ocorrência (serviços); base arbitrária."],"n":8},{"id":"s3-2","cap":3,"title":"Fontes de mortalidade e CGM","from":35,"to":38,"pts":["DO obrigatória para sepultamento (Lei dos Registros Públicos, 1973). SIM (1975/76) e SINASC (1990, DNV).","CGM (taxa bruta) = óbitos / população do meio do período × 1.000. Só precisa do total de óbitos.","Erros: sub-registro (subestima), evasão (subestima) e invasão (superestima) de óbitos; erro no denominador. Valor esperado: 6 a 10 por 1.000.","O CGM é média ponderada das taxas por idade, então a estrutura etária confunde as comparações."],"n":14},{"id":"s3-3","cap":3,"title":"Padronização","from":38,"to":42,"pts":["Direta: taxas específicas da população estudada × população-padrão, dando os óbitos esperados.","Indireta: taxas do padrão × estrutura da população estudada. RMP (SMR) = observados/esperados (Brasil × Inglaterra = 1,51).","O padronizado é hipotético e só serve para comparar. Brasil: bruto 5,5 × padronizado 12,8 (Inglaterra 10,1).","Causas externas: padronizar por idade e sexo."],"n":15},{"id":"s3-4","cap":3,"title":"Mortalidade por causas","from":42,"to":46,"pts":["Causa básica (OMS); causas associadas; causas múltiplas. Graunt, Farr, CID (CID-10 no Brasil desde 1996).","Mortalidade proporcional = óbitos pela causa / total de óbitos (não usa população; mostra a importância relativa).","Cuidado: a MP pode cair com o número absoluto subindo.","Taxa por causa = óbitos pela causa / população × 100.000. No RJ, causas externas: homens 179,8 × mulheres 30,9.","DIP em queda (vacinas, TRO); a Aids entrou no cap. I da CID-10."],"n":17},{"id":"s3-5","cap":3,"title":"Mortalidade materna","from":46,"to":48,"pts":["Morte materna: na gestação ou até 42 dias após, por causa ligada à gravidez, exceto acidental. Tardia: de 42 dias a 1 ano.","Diretas (complicações obstétricas) × indiretas (doenças agravadas pela gravidez).","RMM = óbitos maternos / nascidos vivos × 100.000. Evento sentinela.","A DO tem baixa sensibilidade e VPP alto para morte materna; o sub-registro chega a cerca de 40-50%. Aceitável: 10-20 por 100 mil NV."],"n":9},{"id":"s3-6","cap":3,"title":"Mal definidas e qualidade dos dados","from":48,"to":50,"pts":["Cap. XVIII da CID (sintomas e sinais): indicador da qualidade do SIM; aceitável 4-6%. Brasil 2004: 12,4% (NE 23,7%).","Óbitos sem assistência (R98) e \"causas lixo\" (septicemia, insuficiências) espalhadas pela CID."],"n":3},{"id":"s3-7","cap":3,"title":"Mortalidade infantil, fetal e perinatal","from":50,"to":57,"pts":["TMI = óbitos < 1 ano / nascidos vivos × 1.000 (é uma proporção, aproximação do risco).","Neonatal (0-27 dias: precoce 0-6, tardia 7-27; causas endógenas) × pós-neonatal (28 dias a < 1 ano; exógenas).","TMI alta: predomina o pós-neonatal; TMI baixa: o neonatal. Classificação: < 20 baixa; 20-49 intermediária; ≥ 50 alta.","Brasil: queda forte, sobretudo pós-neonatal (saneamento, TRO, vacinas, menor fecundidade); desigualdades regionais.","Limitações: sub-registro, confusão natimorto × nascido vivo; intervenções pontuais.","Óbitos evitáveis (imunoprevenção, pré-natal, parto, diagnóstico e tratamento, intersetorial).","Óbito fetal declarado a partir de 20 semanas, 500 g ou 25 cm. Mortalidade perinatal: de 22 semanas a 7 dias. Não é afetada pela confusão natimorto × NV.","Mortalidade em menores de 5 anos (Unicef): óbitos < 5 / NV × 1.000."],"n":18},{"id":"s3-8","cap":3,"title":"Swaroop-Uemura e Nelson de Moraes","from":57,"to":60,"pts":["Swaroop-Uemura: % de óbitos com ≥ 50 anos. 1º nível ≥ 75%; 2º 50-74,9%; 3º 25-49,9%; 4º < 25%. Brasil: 48,9% (1980), 67,1% (2000).","O sub-registro de óbitos infantis superestima o indicador.","Curvas de Nelson de Moraes (faixas < 1, 1-4, 5-19, 20-49, 50+): \"N\" (muito baixo), \"L\" (baixo), \"U\" (regular), \"J\" (elevado)."],"n":8},{"id":"s3-9","cap":3,"title":"Esperança de vida e tábuas","from":60,"to":64,"pts":["Tábua de geração (coorte real) × de coorte sintética (taxas de um período aplicadas a uma coorte hipotética).","e0 não depende da estrutura etária. Ganha mais com a queda da mortalidade nas idades jovens.","Mortalidade infantil alta: e1 > e0. Brasil 2005: e0 ≈ 72 anos; as mulheres vivem mais.","Riscos competitivos (tábua de múltiplo decremento): ganho em e0 ao eliminar uma causa."],"n":12},{"id":"s3-10","cap":3,"title":"Anos potenciais de vida perdidos","from":64,"to":67,"pts":["APVP = Σ dx(L − x). Dempsey (tuberculose); magnitude × transcendência.","L arbitrário: L baixo destaca mortes prematuras. Romeder e McWhinnie: de 1 a 70 anos (sem óbitos infantis, sem consenso).","Taxas de APVP, APVP médio por óbito; APVP padronizado usa a esperança de vida (ex).","No ranking por APVP sobem acidentes, homicídios, causas perinatais e anomalias; descem neoplasias e AVC."],"n":6},{"id":"s3-11","cap":3,"title":"Morbidade, funcionalidade e qualidade de vida","from":67,"to":73,"pts":["Doença (disease, organismo), enfermidade (illness, percepção), anormalidade (sickness, social). Terris: gradiente de sanidade.","Fontes: notificação (Sinan), SIH (pagamento; depende da oferta), SIA, registros de câncer, inquéritos (PNAD).","Modelos: biomédico; OMS (CIDID: doença → deficiência → incapacidade → desvantagem; depois CIF 2001); utilitarista (QALY); qualidade de vida (WHOQOL, SF-36).","Escalas de AVD/AIVD; limitação × restrição de atividade; PNAD 2003."],"n":7},{"id":"s3-12","cap":3,"title":"Medidas-resumo: DALY","from":73,"to":77,"pts":["Esperança de vida livre de incapacidade (Sullivan: tábua de vida + prevalência de incapacidade).","DALY = YLL + YLD; pesos de 0 (saúde) a 1 (morte); só idade e sexo; taxa de desconto; tábua-modelo de Coale-Demeny.","Brasil 1998: condições neuropsiquiátricas em 1º lugar em DALY (por YLD); cardiovasculares em 1º em óbitos e YLL."],"n":5},{"id":"s3-13","cap":3,"title":"RIPSA e fontes de indicadores","from":78,"to":79,"pts":["RIPSA (1996): MS, OPAS, IBGE, ABRASCO, IPEA… Matriz de indicadores básicos (demográficos, socioeconômicos, mortalidade, morbidade, recursos, cobertura). IDB anual (DATASUS: Tabnet, Tabwin)."],"n":1},{"id":"s4-1","cap":4,"title":"Pessoa, lugar e tempo; geografia médica","from":83,"to":84,"pts":["Quem, onde e quando: gerar hipóteses, planejar, orientar a clínica. O espaço é social (Milton Santos).","Lind (1768), Seaman, Guerry, Berghaus (1º atlas de doenças). Snow e a cólera (1854). Pavlovsky: focos naturais.","Distribuições espaciais sugerem hipóteses, mas exposição e desfecho não são medidos no mesmo indivíduo (ecológico)."],"n":4},{"id":"s4-2","cap":4,"title":"Análise espacial","from":85,"to":87,"pts":["Visualização, exploração e modelagem (Gatrell e Bailey). Geoprocessamento e SIG.","Geoestatística (variação contínua; pontos próximos são parecidos); dados de área (vizinhança); padrões pontuais (agregação × aleatoriedade).","Estudos de migrantes: separam ambiente de genética."],"n":5},{"id":"s4-3","cap":4,"title":"Tempo: tendência e variações","from":87,"to":91,"pts":["Tipos: tendência secular, variações cíclicas (> 1 ano: sarampo a cada 2-3 anos), sazonais (estações) e irregulares.","Antes de interpretar uma tendência, descarte mudanças de diagnóstico, cobertura, classificação e letalidade.","TB e coqueluche (Inglaterra) já caíam antes dos agentes, vacinas e drogas: papel das condições de vida."],"n":22},{"id":"s4-4","cap":4,"title":"Endemia, epidemia e surtos","from":92,"to":94,"pts":["Epidemia: elevação brusca, temporária e acima do esperado. Endemia: presença habitual dentro do esperado.","Um caso autóctone de doença eliminada já é epidemia. Autóctone × alóctone (importado).","Pandemia: vários países/continentes. Surto: casos relacionados em área restrita ou instituição.","Fonte comum (pontual ou persistente: pico rápido; o pico corresponde à incubação média) × propagada (pessoa a pessoa, mais lenta)."],"n":15},{"id":"s4-5","cap":4,"title":"Diagrama de controle","from":95,"to":97,"pts":["Normal: média ± 1,96 DP por mês, com ~10 anos sem epidemias. Limite inferior negativo vira zero.","Quartis: acima do 3º quartil = epidêmico."],"n":13},{"id":"s4-6","cap":4,"title":"Idade, período e coorte","from":97,"to":102,"pts":["Efeito de idade (envelhecimento), de período (evento no calendário que afeta todos) e de coorte (geração).","Os três são linearmente dependentes. A análise transversal pode enganar quando há forte efeito de coorte."],"n":5},{"id":"s5-1","cap":5,"title":"Conceito e histórico","from":103,"to":104,"pts":["Coleta, análise, interpretação e disseminação sistemáticas e contínuas para ação (prevenção e controle).","Quarentena (séc. XIV); notificação nacional na Itália (1881) e nos EUA (1901); \"vigilância de pessoas\" → vigilância de doenças.","Raska (1964) e a OMS (1965). Lei 8.080/90: inclui qualquer mudança nos determinantes; não só transmissíveis.","Prioridade ao nível municipal. Vigilância ≠ monitoração."],"n":5},{"id":"s5-2","cap":5,"title":"Objetivos, atividades e dados","from":104,"to":106,"pts":["Objetivos: tendências e grupos de risco, detectar epidemias, magnitude, recomendar medidas, avaliar impacto e estratégias.","Atividades: coleta, processamento, análise, investigação, recomendação, avaliação, retroalimentação e divulgação.","Dados demográficos, ambientais, socioeconômicos, de morbidade e de mortalidade (melhores para doenças letais)."],"n":10},{"id":"s5-3","cap":5,"title":"Notificação compulsória","from":106,"to":111,"pts":["Base do sistema. Qualquer cidadão pode notificar; profissionais e estabelecimentos de saúde e de ensino são obrigados (Portaria 5/2006).","Notificar a suspeita, de forma sigilosa, e fazer a notificação negativa.","Critérios da lista: magnitude, potencial de disseminação, transcendência, vulnerabilidade, valor da notificação, compromissos internacionais, agravos inusitados.","Estados e municípios podem acrescentar doenças. Há uma lista de notificação imediata.","SINAN (FIN e FII), SIM (DO em 3 vias; residência), SINASC, SIH (pagamento), SIA (sem CID), SIAB, SISVAN, SI-PNI, SISÁGUA."],"n":23},{"id":"s5-4","cap":5,"title":"Investigação, laboratório e sentinela","from":112,"to":114,"pts":["Investigação: trabalho de campo para confirmar o diagnóstico, achar fonte, transmissão, expostos e casos secundários.","Laboratórios, imprensa e população (antraz de Sverdlovsk); estudos (seccionais; caso-controle em surtos).","Sentinela: subconjunto de fontes; mais detalhe, menos representatividade, não dá para calcular incidência; vigilância sindrômica."],"n":10},{"id":"s5-5","cap":5,"title":"Avaliação do sistema","from":114,"to":115,"pts":["Atributos: utilidade, oportunidade, aceitabilidade, simplicidade, flexibilidade, representatividade, sensibilidade, especificidade, VPP.","VPP cresce com a especificidade e com a prevalência. Problemas: subnotificação (sistemas passivos), baixa representatividade, baixa oportunidade."],"n":8},{"id":"s5-6","cap":5,"title":"Investigação de surtos e emergências","from":115,"to":120,"pts":["Surto: excesso em relação ao esperado (sem número mínimo). Por que surtos começam e por que acabam.","Etapas: confirmar o diagnóstico e o surto, caracterizar, levantar hipóteses, busca ativa, análise, controle, relatório e divulgação.","Definição de caso sensível no início e específica para o teste. Taxa de ataque dos expostos > não-expostos.","Emergentes no Brasil; Chagas por caldo de cana (SC, 2005). CIEVS (2005): notificação 24 h e Unidade de Respostas Rápidas."],"n":16},{"id":"s6-1","cap":6,"title":"Crescimento populacional e teorias","from":123,"to":125,"pts":["A população mundial acelera a partir do séc. XVIII (Revolução Industrial): 2,5 bilhões em 1950 e 6 bilhões em 2000.","Malthus (progressão geométrica × aritmética) × Marx e Engels (sem lei universal). Teoria da transição demográfica."],"n":5},{"id":"s6-2","cap":6,"title":"Fases da transição demográfica","from":126,"to":128,"pts":["1: natalidade e mortalidade altas. 2: a mortalidade cai (explosão). 3: a natalidade cai (envelhecimento). 4: ambas baixas.","Brasil: lento até 1900; explosão desde 1950; desaceleração desde 1970. Urbanização: 81% em 2000."],"n":9},{"id":"s6-3","cap":6,"title":"Indicadores demográficos","from":128,"to":133,"pts":["Fertilidade (fisiológica) × fecundidade (efetiva). Fecundidade: > 6 filhos (até 1960), 2,35 (2000), abaixo da reposição depois.","Natalidade de 44 para 21 por 1.000; mortalidade geral de 29 para 6. A queda da mortalidade precedeu a da natalidade.","TMI: 162 (1930), 27 (2000). e0: 33,7 (1900), 70,4 (2000). Idade mediana ~18 → 40 (2050).","O envelhecimento se deve sobretudo à queda da fecundidade; é feminino. Pirâmides de triângulo para retângulo."],"n":16},{"id":"s6-4","cap":6,"title":"Transição epidemiológica: Omran e críticas","from":132,"to":136,"pts":["Omran (1971): era da pestilência e fome; do declínio das pandemias; das doenças degenerativas e provocadas pelo homem.","Críticas: determinista, linear, baseada na Europa. Olshansky e Ault: 4ª era (doenças degenerativas adiadas).","Frenk: modelo tardio-polarizado (superposição, contratransição, polarização). Aids e doenças emergentes."],"n":13},{"id":"s6-5","cap":6,"title":"Brasil: mortalidade, internações e infecciosas","from":136,"to":145,"pts":["MP: DIP 45,7% (1930) → 4,6% (2003); circulatório 11,8 → 27,3%; neoplasias e externas ~12,6%.","Internações SUS: 1º respiratório, 2º circulatório, 3º DIP (polarização); neoplasias por último.","DIP decrescentes (imunopreveníveis; varíola erradicada em 1978; polio sem casos desde 1989), persistentes (malária, TB, leishmanioses) e emergentes (Aids, dengue, cólera, hantavirose)."],"n":12},{"id":"s6-6","cap":6,"title":"Transição nutricional e desigual","from":143,"to":149,"pts":["Desnutrição → obesidade; coexistência de fome e obesidade nas camadas pobres; não é sinônimo de melhoria.","Desigualdade regional: MP, TMI, Swaroop-Uemura e curvas de Nelson de Moraes por região (Norte/Nordeste atrás)."],"n":12},{"id":"s8-1","cap":8,"title":"Definição e objetivos","from":173,"to":174,"pts":["Distribuição e determinantes dos eventos de saúde em populações definidas, e a aplicação para controlá-los.","Objetivos: descrever, explicar, predizer, controlar. Procedimentos: mensuração, estimação (estimativa × parâmetro) e testes de hipótese (acaso)."],"n":4},{"id":"s8-2","cap":8,"title":"Causalidade e método científico","from":174,"to":176,"pts":["Modelo probabilístico: quantos adoecem, não quem. Fator de risco: associação, precedência temporal, sem erro (acaso, confusão, viés).","Teoria → hipótese conceitual → hipótese operacional (ex.: Barker e baixo peso ao nascer).","Inferência indutiva (problema de Hume; falácia de afirmar o consequente), por refutação (Popper), por consenso (Kuhn), bayesiana.","Rothman e Greenland: \"provar é impossível\"; experimentos não são prova definitiva."],"n":13},{"id":"s8-3","cap":8,"title":"Populações e desenhos","from":176,"to":179,"pts":["População do estudo (amostra), população-fonte (elegíveis), população-alvo (inferência), base populacional (de onde surgem os casos).","Experimental (alocação aleatória, exposição controlada), quase-experimental (sem aleatorização), observacional.","Dimensões: seccional × longitudinal; seleção completa × incompleta; individual × agregado.","Coorte (expostos × não expostos acompanhados), caso-controle (casos × controles), seccional (prevalências), ecológico (agregado).","Prospectivo (concorrente) × retrospectivo (histórico). O julgamento causal usa a totalidade das evidências."],"n":59},{"id":"s18-1","cap":18,"title":"Coleta e organização","from":323,"to":325,"pts":["Análise descritiva ou exploratória: tabelas, gráficos e medidas-resumo para achar padrões.","Matriz: elemento (linha), variável (coluna), observação (célula), caso (linha completa).","Escalas: nominal, ordinal (categóricas); intervalar (zero arbitrário), razão (zero absoluto). Discretas (contagem) × contínuas (medição)."],"n":8},{"id":"s18-2","cap":18,"title":"Tabelas e distribuições de frequência","from":325,"to":328,"pts":["Tabela autoexplicativa: título (o quê, onde, quando), fonte abaixo, sem bordas laterais. Quadro × tabela.","Frequência absoluta, percentual e percentual acumulada. Classes com \"|—\" (inclui o inferior, exclui o superior). Sem regra fixa de classes."],"n":9},{"id":"s18-3","cap":18,"title":"Medidas-resumo","from":328,"to":333,"pts":["Moda, média (centro de gravidade, sensível a extremos), mediana (robusta; preferível na assimetria).","Quartis, quintis, percentis. Amplitude total; distância interquartílica (Q3 − Q1).","Desvio médio absoluto; variância (n ou n − 1); desvio-padrão (mesma unidade; 68% e 95%); CV = DP/média (adimensional)."],"n":28},{"id":"s18-4","cap":18,"title":"Gráficos","from":334,"to":337,"pts":["Setores (poucas categorias), barras e colunas (categóricas, discretas, séries curtas), linhas (séries temporais).","Histograma (contínuas; com classes desiguais a área é proporcional à frequência); formatos: simétrico, assimétrico, truncado, multimodal.","Polígono de frequências (pontos médios). Box plot (Q1, mediana, Q3, bigodes de 1,5 DIQ, outliers)."],"n":12},{"id":"s18-5","cap":18,"title":"Análise bivariada","from":337,"to":341,"pts":["Duas categóricas: tabela de dupla entrada, totais marginais, barras agrupadas ou empilhadas.","Quantitativa × categórica: séries por grupo, classes por categoria, medidas-resumo por grupo, barras de erro (média ± DP), box plots lado a lado.","Duas quantitativas: diagrama de dispersão (relação direta ou inversa, pontos atípicos)."],"n":11}],"questions":[{"id":"p2023-q1","src":"prova","type":"choice","ctx":["Identifique o tipo de desenho de estudo de cada resumo."],"items":[{"id":"p2023-q1.1","t":"OBJETIVO: Analisar a eficácia e segurança de vacina recombinante contra hepatite B em recém-nascidos. MÉTODOS: O estudo foi conduzido em hospital geral do município de Guarulhos, SP, entre 2002 e 2005. A vacina recombinante contra hepatite B do Instituto Butantan (VrHB-IB) foi analisada em dois ensaios. Em ambos, os recém-nascidos foram alocados aleatoriamente ao grupo intervenção ou controle (vacina de referência). Os recém-nascidos receberam três doses das vacinas, uma em até 24 h após o nascimento e as subsequentes 30 e 180 dias após. No primeiro ensaio 538 recém-nascidos completaram o protocolo e no segundo ensaio, 486. Considerou-se critério de equivalência a diferença na soroproteção inferior a 5%. RESULTADOS: A soroproteção no primeiro ensaio (anti HBs > 10mUI/ml) foi de 92,5% (247/267) no grupo experimental, comparada a 98,5% (267/271) no grupo controle (p = 0,001). Com este resultado, a VrHB-IB não atingiu o critério de equivalência estabelecido. Após o aumento da concentração de antígeno na vacina para 25µg, a soroproteção no segundo ensaio foi de 100% no grupo experimental e 99,2% no grupo controle. Nenhum evento adverso grave foi registrado.","e":"O pesquisador controla a exposição (qual vacina cada um recebe) e a alocação é aleatória: é um ensaio clínico profilático, o tipo mais comum de estudo experimental.","refs":[{"c":8,"p":176,"p2":177,"s":"s8-3"}],"a":0},{"id":"p2023-q1.2","t":"Objetivo: Descrever a prevalência de indicadores do tabagismo entre escolares brasileiros segundo características sociodemográficas em 2019 e comparar as prevalências entre 2015 e 2019. Métodos: Utilizaram-se dados da Pesquisa Nacional de Saúde do Escolar de 2015 e 2019. Foram analisados os indicadores referentes ao uso do tabaco, que foram comparados entre as edições de 2015 e 2019. Foram calculadas as prevalências e os respectivos intervalos de confiança de 95% (IC95%) para a população total e segundo sexo, faixa etária e tipo de escola. Resultados: Dos escolares, 22,6% (IC95% 21,7–23,4) já experimentaram cigarro alguma vez, porcentagem mais elevada entre os de 16 a 17 anos de idade (32,6%; IC95% 31,4–33,8) e no sexo masculino (35,0%; IC95% 33,6–36,4). A experimentação de narguilé, cigarro eletrônico e outros produtos do tabaco também se mostra elevada, com 26,9%, 16,8% e 9,3%, respectivamente, sendo mais alta entre os escolares do sexo masculino de 16 a 17 anos. Destaca-se que não houve mudanças nos indicadores entre os anos indicados.","e":"Duas edições de um inquérito, cada uma uma \"fotografia\" de indivíduos diferentes num único momento, medindo prevalências. Comparar duas edições não torna o estudo longitudinal: são inquéritos transversais repetidos.","refs":[{"c":8,"p":177,"p2":178,"s":"s8-3"}],"a":3},{"id":"p2023-q1.3","t":"Objetivo: Identificar padrões espaciais em casos de lactentes com alterações de crescimento e desenvolvimento relacionadas à infecção pelo vírus Zika (síndrome congênita pelo vírus Zika), notificados no Maranhão de 2015 a 2018 e sua relação com variáveis socioeconômicas e demográficas. Métodos: Estudo com casos suspeitos notificados nos 217 municípios do Maranhão. Calculou-se a autocorrelação espacial pelos índices de Moran local e global (I) univariado e bivariado da taxa de detecção de casos suspeitos com índice de desenvolvimento humano municipal, densidade demográfica, índice de Gini e tempo de emancipação dos municípios. Resultados: Houve autocorrelação espacial da taxa municipal de detecção (I=0,494; p=0,001) e correlação positiva com IDH municipal, densidade demográfica e tempo de emancipação. Não houve correlação significativa com o índice de Gini. Cinco clusters de alta detecção foram encontrados.","e":"A unidade de análise é o município (taxas e indicadores agregados), não o indivíduo. Não se sabe se exposição e desfecho estão na mesma pessoa: estudo ecológico, aqui com análise espacial.","refs":[{"c":8,"p":177,"p2":178,"s":"s8-3"},{"c":4,"p":85,"p2":86,"s":"s4-2"}],"a":4},{"id":"p2023-q1.4","t":"Esse estudo teve como objetivo determinar os fatores associados à dependência para atividades instrumentais da vida diária em idosos. O estudo foi de base populacional, com 180 idosos de Passo Fundo-RS, 2014. Os casos foram representados por 60 indivíduos com idade ≥ 60 anos, dependentes para as atividades instrumentais de vida diária. Os controles foram representados por 120 idosos não dependentes, residentes nos domicílios urbanos do município. Foram estimadas razões de chance (OR) brutas e ajustadas. Permaneceram significativos: ter 80 anos ou mais (OR = 1,76), ter estudado de 1 a 4 anos (OR = 2,36), ser analfabeto (OR = 2,98), ter Parkinson (OR = 2,44) e comprometimento cognitivo (OR = 1,88).","e":"Os participantes foram selecionados pelo desfecho (dependentes = casos; não dependentes = controles) e comparou-se a exposição entre os grupos: caso-controle (esquema de seleção incompleto da base populacional). A medida é a odds ratio.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":2},{"id":"p2023-q1.5","t":"O uso de medicação é parte importante do processo de saúde, e a prevalência de uso entre lactentes pode chegar a 65% nos primeiros meses de vida. O estudo buscou descrever o uso de medicação em crianças aos 3, 12, 24 e 48 meses. Foram aplicados questionários padronizados. O uso de medicação foi definido como ter recebido qualquer medicação nos 15 dias anteriores à entrevista. A prevalência do uso de medicação foi de 67,2%, 68,2%, 52,4% e 47,2% aos 3, 12, 24 e 48 meses, respectivamente. Ao longo dos anos, foram observados uma diminuição na proporção de medicamentos com prescrição médica e um aumento na automedicação.","e":"As mesmas crianças foram acompanhadas e entrevistadas em várias idades (3, 12, 24 e 48 meses): observação longitudinal de uma coorte de nascimentos. Por isso a resposta mais provável é coorte, mesmo que o objetivo seja descritivo. (Gabarito não oficial.)","refs":[{"c":8,"p":177,"p2":178,"s":"s8-3"}],"a":1}],"prova":2023,"num":1,"cap":8,"title":"Identificação de desenhos de estudo","opts":["Estudo experimental","Estudo de coorte","Estudo caso-controle","Estudo transversal","Estudo ecológico","Nenhum dos anteriores"]},{"id":"p2023-q2","src":"prova","type":"vf","ctx":["Figura 1: taxas de incidência mensal de meningite viral (por 100 mil habitantes) no Recife-PE, 1998 a 2008. Figura 2: número mensal de casos de dengue e precipitação pluviométrica acumulada em Barreiras, Bahia, janeiro de 2007 a março de 2013."],"imgs":[{"f":"2023-q2-meningite-recife.png","cap":"Figura 1 · meningite viral, Recife"},{"f":"2023-q2-dengue-barreiras.png","cap":"Figura 2 · dengue e chuva, Barreiras-BA"}],"items":[{"id":"p2023-q2.1","t":"As figuras se referem à análise de séries temporais de duas doenças distintas, meningite viral e dengue, respectivamente. Estudos deste tipo têm como objetivo avaliar a evolução das taxas de adoecimento ou de mortalidade de acordo com o período ou tempo calendário.","e":"Ambas mostram uma medida de ocorrência (taxa ou nº de casos) ao longo do tempo calendário. É isso que define uma série temporal.","refs":[{"c":4,"p":88,"p2":88,"s":"s4-3"},{"c":18,"p":334,"p2":334,"s":"s18-4"}],"a":"V"},{"id":"p2023-q2.2","t":"Analisando as figuras, podemos concluir que a meningite viral não apresentou uma variação sazonal, enquanto a ocorrência de dengue apresentou sazonalidade, principalmente a partir do final de 2008.","e":"Na dengue os picos se repetem na mesma época do ano (verão/chuvas: início de 2009, 2011 e 2013), o que caracteriza a sazonalidade. Na meningite viral o que chama atenção é o grande pico isolado de 2007-2008, sem um padrão anual claro. A assertiva é ambígua, porque há pequenas oscilações.","refs":[{"c":4,"p":90,"p2":91,"s":"s4-3"}],"a":"V","disc":1},{"id":"p2023-q2.3","t":"Analisando somente a Figura 2, podemos observar que a ocorrência dos casos de dengue não apresentou variação cíclica.","e":"Variação cíclica é a flutuação com período maior que um ano. Os picos de dengue se alternam a cada dois anos, com grandes epidemias em 2009, 2011 e 2013, sugerindo um ciclo, típico de doenças em que suscetíveis se acumulam entre as epidemias.","refs":[{"c":4,"p":90,"p2":90,"s":"s4-3"}],"a":"F"},{"id":"p2023-q2.4","t":"Analisando mais detalhadamente a Figura 1 e levando em consideração a definição de epidemia, podemos concluir que em janeiro de 2008 não houve uma epidemia de meningite viral em Recife, PE.","e":"Entre o fim de 2007 e o início de 2008 a taxa saltou de cerca de 2 para mais de 25/100 mil. Uma elevação brusca, temporária e muito acima do esperado é a definição de epidemia.","refs":[{"c":4,"p":92,"p2":92,"s":"s4-4"}],"a":"F"},{"id":"p2023-q2.5","t":"Nos estudos de séries temporais é possível avaliar apenas o efeito de idade e período na ocorrência dos casos e óbitos observados.","e":"Séries temporais permitem estudar tendência secular, variações cíclicas, sazonais e irregulares, além dos efeitos de idade, período e coorte.","refs":[{"c":4,"p":88,"p2":88,"s":"s4-3"},{"c":4,"p":97,"p2":102,"s":"s4-6"}],"a":"F"}],"prova":2023,"num":2,"cap":4,"title":"Séries temporais: meningite viral e dengue"},{"id":"p2023-q3","src":"prova","type":"vf","ctx":["Considere uma população com uma dada prevalência e incidência de doença crônica não transmissível."],"items":[{"id":"p2023-q3.1","t":"A incidência, quando expressa na forma de taxa de incidência, representa a real medida de risco de surgimento da doença em um dado intervalo de tempo na população.","e":"A taxa de incidência (casos/pessoa-tempo) mede a velocidade de surgimento de casos: tem dimensão de tempo⁻¹ e pode passar de 1. Quem estima o risco num intervalo é a incidência acumulada (uma proporção). TI × Δt só se aproxima do risco quando a TI é constante e o intervalo é curto.","refs":[{"c":2,"p":21,"p2":22,"s":"s2-3"}],"a":"F"},{"id":"p2023-q3.2","t":"A introdução de um tratamento eficaz leva a uma redução na incidência.","e":"Tratamento atua sobre quem já está doente: reduz a duração (cura) ou a letalidade, e com isso a prevalência ou a mortalidade. Não impede casos novos. Quem reduz a incidência é a prevenção primária.","refs":[{"c":2,"p":27,"p2":28,"s":"s2-5"}],"a":"F"},{"id":"p2023-q3.3","t":"O aumento da sobrevida leva a um aumento na prevalência.","e":"P ≈ I × D: se os doentes vivem mais (maior duração), acumulam-se mais casos existentes, mesmo com incidência igual.","refs":[{"c":2,"p":27,"p2":28,"s":"s2-5"}],"a":"V"},{"id":"p2023-q3.4","t":"Uma vez estabilizada a incidência (constante no tempo), a prevalência também será constante no tempo.","e":"A prevalência depende da incidência, da duração (cura, sobrevida) e da migração. Com incidência constante, a prevalência ainda muda se a duração ou a migração mudarem.","refs":[{"c":2,"p":27,"p2":28,"s":"s2-5"}],"a":"F"},{"id":"p2023-q3.5","t":"Para expressar a frequência de nascimentos de crianças com malformação congênita, utilizamos a medida de prevalência.","e":"A proporção de RN com malformação é prevalência ao nascer: não se conhecem os casos perdidos como abortos e perdas fetais, então não é incidência.","refs":[{"c":2,"p":29,"p2":30,"s":"s2-5"}],"a":"V"}],"prova":2023,"num":3,"cap":2,"title":"Prevalência e incidência de doença crônica"},{"id":"p2023-q4","src":"prova","type":"vf","items":[{"id":"p2023-q4.1","t":"A padronização dos coeficientes de mortalidade é necessária quando comparamos populações de tamanhos diferentes.","e":"O tamanho já é corrigido pelo próprio coeficiente (óbitos/população). Padroniza-se quando as populações têm estrutura etária (ou por sexo) diferente, que confunde a comparação.","refs":[{"c":3,"p":38,"p2":38,"s":"s3-3"}],"a":"F"},{"id":"p2023-q4.2","t":"O coeficiente geral de mortalidade não padronizado é a expressão da intensidade com que ocorrem óbitos em uma população.","e":"O CGM bruto mede o risco real de morrer naquela população, com a estrutura etária que ela tem. O padronizado é um número hipotético, só para comparação.","refs":[{"c":3,"p":36,"p2":37,"s":"s3-2"},{"c":3,"p":40,"p2":40,"s":"s3-3"}],"a":"V"},{"id":"p2023-q4.3","t":"A taxa de mortalidade por causa de óbito representa o número de mortes por uma causa específica pelo número total de mortes no período.","e":"Óbitos por uma causa / total de óbitos é a mortalidade proporcional. A taxa de mortalidade por causa usa a população (meio do período) no denominador.","refs":[{"c":3,"p":43,"p2":45,"s":"s3-4"}],"a":"F"},{"id":"p2023-q4.4","t":"Na prática, a taxa de mortalidade infantil é uma aproximação da medida de risco ou probabilidade de morte antes de completar um ano de vida.","e":"Óbitos de menores de 1 ano / nascidos vivos é uma proporção que estima o risco. É aproximação porque numerador e denominador misturam coortes de anos calendário vizinhos.","refs":[{"c":3,"p":51,"p2":51,"s":"s3-7"}],"a":"V"},{"id":"p2023-q4.5","t":"O coeficiente de mortalidade pode ser expresso de 3 formas: geral, bruto, e padronizado.","e":"\"Geral\" e \"bruto\" são a mesma coisa (CGM = taxa bruta de mortalidade). As formas são: geral/bruto, específico (por idade, sexo, causa) e padronizado.","refs":[{"c":3,"p":36,"p2":41,"s":"s3-2"}],"a":"F"}],"prova":2023,"num":4,"cap":3,"title":"Coeficientes de mortalidade"},{"id":"p2023-q5","src":"prova","type":"vf","items":[{"id":"p2023-q5.1","t":"A notificação compulsória de casos deve ser feita por profissionais de saúde ligados ao sistema único de saúde.","e":"São obrigados todos os profissionais de saúde e os responsáveis por estabelecimentos de saúde e de ensino, públicos e privados. Qualquer cidadão pode notificar.","refs":[{"c":5,"p":106,"p2":106,"s":"s5-3"}],"a":"F"},{"id":"p2023-q5.2","t":"A notificação das doenças constantes na Lista Nacional de Doenças e Agravos de Notificação Compulsória deve ser feita mesmo na ausência de casos.","e":"É a notificação negativa: informar que não houve casos distingue \"sistema alerta, sem casos\" de \"casos não notificados\". Também é um indicador de eficiência do sistema.","refs":[{"c":5,"p":107,"p2":108,"s":"s5-3"}],"a":"V"},{"id":"p2023-q5.3","t":"As notificações devem, idealmente, ser feitas em períodos de epidemias.","e":"A vigilância é contínua e sistemática: notifica-se sempre, inclusive a notificação negativa. É assim que se detecta o que excede o esperado.","refs":[{"c":5,"p":103,"p2":103,"s":"s5-1"},{"c":5,"p":107,"p2":107,"s":"s5-3"}],"a":"F"},{"id":"p2023-q5.4","t":"Os critérios que norteiam a escolha de doenças que fazem parte da Lista Nacional de Doenças e Agravos de Notificação Compulsória não se restringem a aspectos epidemiológicos.","e":"Além de magnitude e potencial de disseminação, entram transcendência (relevância social e econômica), vulnerabilidade, valor da notificação e compromissos internacionais (RSI).","refs":[{"c":5,"p":107,"p2":107,"s":"s5-3"}],"a":"V"},{"id":"p2023-q5.5","t":"Epidemia é a ocorrência de muitos casos de uma doença em um determinado período.","e":"Epidemia é a ocorrência acima do esperado, não \"muitos casos\". Um único caso autóctone de uma doença eliminada já é uma epidemia.","refs":[{"c":4,"p":92,"p2":92,"s":"s4-4"},{"c":5,"p":115,"p2":115,"s":"s5-6"}],"a":"F"}],"prova":2023,"num":5,"cap":5,"title":"Notificação compulsória"},{"id":"p2023-q6","src":"prova","type":"vf","items":[{"id":"p2023-q6.1","t":"Um problema do coeficiente geral de mortalidade é que os óbitos sem causas conhecidas não podem ser computados no seu cálculo, levando à redução deste coeficiente.","e":"O CGM usa todos os óbitos, com ou sem causa definida. A vantagem dele é justamente não precisar de idade, sexo ou causa.","refs":[{"c":3,"p":36,"p2":37,"s":"s3-2"}],"a":"F"},{"id":"p2023-q6.2","t":"A taxa de mortalidade infantil neonatal é mais difícil de ser reduzida do que a taxa de mortalidade infantil pós-neonatal, por ser mais influenciada por anomalias congênitas e afecções perinatais.","e":"O componente neonatal tem causas endógenas, ligadas à gestação e ao parto, que exigem intervenções complexas e caras. O pós-neonatal cai com medidas simples (TRO, vacinação, saneamento).","refs":[{"c":3,"p":51,"p2":52,"s":"s3-7"}],"a":"V"},{"id":"p2023-q6.3","t":"O coeficiente de mortalidade por causas externas (que inclui as mortes violentas) é calculado com base no local onde houve a morte, e não o local de residência, para poder dimensionar o impacto da violência sobre a saúde em uma dada região.","e":"O livro diz que o local de residência é o de maior interesse, exceto para causas externas, em que o local de ocorrência importa para dimensionar a violência na área. Nos indicadores de risco (ex. RIPSA) usa-se a residência, por isso a assertiva é discutível.","refs":[{"c":5,"p":111,"p2":111,"s":"s5-3"},{"c":3,"p":35,"p2":35,"s":"s3-2"}],"a":"V","disc":1},{"id":"p2023-q6.4","t":"O indicador Anos Potenciais de Vida Perdidos exclui de seu cálculo os óbitos infantis, pois muitas mortes nesse período são decorrentes de causas específicas do primeiro ano de vida.","e":"É a proposta de Romeder e McWhinnie (APVP entre 1 e 70 anos): os óbitos infantis têm causas próprias e superdimensionariam o indicador. O livro avisa que isso não é consenso. Muitos cálculos usam de 0 a L.","refs":[{"c":3,"p":65,"p2":66,"s":"s3-10"}],"a":"V","disc":1},{"id":"p2023-q6.5","t":"O coeficiente geral de mortalidade de um município é calculado pela razão entre o número de óbitos no município e a população no meio do período do Estado ao qual pertence o município.","e":"Numerador e denominador devem se referir à mesma área e período: óbitos de residentes no município / população do município no meio do período × 1000.","refs":[{"c":3,"p":36,"p2":36,"s":"s3-2"}],"a":"F"}],"prova":2023,"num":6,"cap":3,"title":"Indicadores de mortalidade"},{"id":"p2023-q7","src":"prova","type":"vf","ctx":["Figura 1: distribuição proporcional (%) da população por sexo e idade, Brasil, 1980, 1991 e 2000. Figura 2: transição demográfica, número de nascimentos e óbitos no Brasil, 1950-2100 (ONU, World Population Prospects 2019)."],"imgs":[{"f":"2023-q7-piramides.png","cap":"Figura 1 · pirâmides 1980, 1991 e 2000"},{"f":"2023-q7-nascimentos-obitos.png","cap":"Figura 2 · nascimentos e óbitos (ONU)"}],"items":[{"id":"p2023-q7.1","t":"A pirâmide etária do Brasil caracteriza o processo de envelhecimento da população brasileira, que está se concretizando na atualidade devido ao aumento das taxas de natalidade e de fecundidade da população.","e":"É o contrário: o envelhecimento se deve sobretudo à queda da fecundidade e da natalidade, que estreita a base da pirâmide.","refs":[{"c":6,"p":129,"p2":131,"s":"s6-3"}],"a":"F"},{"id":"p2023-q7.2","t":"A pirâmide também nos permite observar a feminização do processo de envelhecimento da população brasileira, uma vez que a população masculina apresentou padrão mais jovem que a feminina.","e":"Nas idades mais altas as barras femininas são maiores: as mulheres têm menor mortalidade e maior esperança de vida, e o envelhecimento é \"feminino\".","refs":[{"c":6,"p":126,"p2":126,"s":"s6-2"},{"c":6,"p":132,"p2":132,"s":"s6-4"}],"a":"V"},{"id":"p2023-q7.3","t":"Um dos fatores mais importantes envolvidos no processo de envelhecimento populacional é a redução da mortalidade geral e infantil.","e":"O fator mais importante é a queda da fecundidade. A queda da mortalidade infantil, sozinha, tenderia a rejuvenescer a população, porque mais crianças sobrevivem.","refs":[{"c":6,"p":131,"p2":131,"s":"s6-3"}],"a":"F"},{"id":"p2023-q7.4","t":"Pela projeção da ONU, as curvas de nascimentos e óbitos no Brasil vão se encontrar em 2045 e a partir desta data se inicia a fase de decrescimento populacional no país.","e":"No gráfico as curvas se cruzam por volta de 2045. Depois disso os óbitos superam os nascimentos e o crescimento vegetativo fica negativo (desconsiderando migração).","refs":[{"c":6,"p":128,"p2":128,"s":"s6-3"},{"c":6,"p":130,"p2":130,"s":"s6-3"}],"a":"V"},{"id":"p2023-q7.5","t":"A queda da natalidade observada na Figura 2 foi ainda mais acentuada com a pandemia do novo coronavírus. Considerando esse fator, associado ao aumento da mortalidade observado na pandemia, podemos concluir que houve menor crescimento vegetativo.","e":"Crescimento vegetativo = natalidade − mortalidade. Menos nascimentos e mais óbitos reduzem esse saldo.","refs":[{"c":6,"p":128,"p2":128,"s":"s6-3"}],"a":"V"}],"prova":2023,"num":7,"cap":6,"title":"Pirâmides etárias e transição demográfica"},{"id":"p2023-q8","src":"prova","type":"open","ctx":["O gráfico apresenta a variação relativa do número de óbitos registrados (%) entre 2018-2019 e 2019-2020 no Brasil, por sexo e grupo etário. Com base nos dados apresentados e no seu conhecimento sobre o perfil de morbimortalidade do Brasil, descreva o padrão de mortalidade observado no período em ambos os sexos e faixas etárias, buscando relacioná-lo à chegada da pandemia da Covid-19 ao país, em 2020."],"imgs":[{"f":"2023-q8-obitos-2020.png","cap":"Variação relativa do nº de óbitos registrados (IBGE, Registro Civil 2020)"}],"keys":["Entre 2018 e 2019 as variações foram pequenas (de −2,3% a +4,7%), o padrão \"esperado\" de uma população que envelhece devagar.","Em 2019-2020 os óbitos aumentaram muito entre adultos de 15 a 59 anos (+14,7% homens; +15,4% mulheres) e idosos de 60+ (+19,4% homens; +13,1% mulheres): excesso de mortalidade compatível com a Covid-19, que mata mais idosos e pessoas com DCNT.","Nos homens idosos o aumento foi maior: sobremortalidade masculina (maior letalidade da Covid, mais comorbidades, menor procura por serviços).","Entre 0 e 14 anos houve queda (cerca de −15%), provavelmente pelo distanciamento social e escolas fechadas, que reduziram outras infecções respiratórias, diarreias e acidentes. Pode ter havido também sub-registro.","Relacionar com a transição epidemiológica e a dupla carga: uma doença infecciosa emergente atingiu mais os grupos com doenças crônicas, e a pandemia reduziu a esperança de vida e o crescimento vegetativo.","Lembrar das limitações: dados de registro civil (cobertura, atraso de registro) e números absolutos, não taxas."],"prova":2023,"num":8,"cap":6,"pts":1.5,"title":"Óbitos em 2020 por sexo e idade (Covid-19)","ans":"Quem responde bem descreve os números por sexo e idade, aponta o excesso de óbitos em adultos e idosos em 2020 como efeito direto (e indireto) da Covid-19, explica a queda nas crianças e liga o padrão ao perfil de morbimortalidade do país (envelhecimento, DCNT como comorbidade, desigualdade).","refs":[{"c":6,"p":132,"p2":137,"s":"s6-4"},{"c":3,"p":43,"p2":45,"s":"s3-4"},{"c":4,"p":92,"p2":92,"s":"s4-4"}]},{"id":"p2023-q9","src":"prova","type":"open","ctx":["O processo de investigação epidemiológica busca conectar observações e teorias. Existe um caminho para que a teoria possa ser confrontada com os dados da investigação, no qual as hipóteses são trabalhadas. Descreva as fases desse caminho, indicando o que cabe a cada uma delas: a) Teoria; b) Hipótese conceitual; c) Hipótese operacional."],"keys":["Teoria: explicação ampla de um fenômeno, que dá origem às hipóteses. Exemplo do livro, a teoria de Barker: o ambiente nutricional, hormonal e metabólico materno \"programa\" de forma permanente a estrutura e a fisiologia do bebê.","Hipótese conceitual: afirmação ampla, derivada da teoria, sobre a relação entre fenômenos, mas ainda não mensurável. Exemplo: a subnutrição intrauterina é fator de risco para doença cardiovascular.","Hipótese operacional: a hipótese conceitual reescrita em termos de variáveis mensuráveis, para ser testada com dados. Exemplo: crianças com baixo peso ao nascer (< 2.500 g) têm maior probabilidade de doença coronariana na vida adulta do que as com peso normal.","Os dados coletados aceitam ou rejeitam a hipótese operacional. Daí se fazem inferências causais e a teoria é mantida, reformulada ou gera novas hipóteses.","Os desenhos de estudo fazem a ponte entre a hipótese conceitual e a operacional."],"prova":2023,"num":9,"cap":8,"pts":1.5,"title":"Teoria, hipótese conceitual e hipótese operacional","refs":[{"c":8,"p":174,"p2":176,"s":"s8-2"}]},{"id":"p2024-q1","src":"prova","type":"vf","items":[{"id":"p2024-q1.1","t":"A prevalência é definida como a frequência de casos novos de uma doença, em uma determinada população, em um período de tempo.","e":"Essa é a definição de incidência. Prevalência são os casos existentes (novos e antigos) num dado momento.","refs":[{"c":2,"p":14,"p2":14,"s":"s2-1"},{"c":2,"p":25,"p2":26,"s":"s2-5"}],"a":"F"},{"id":"p2024-q1.2","t":"O que determina a prevalência de uma doença é a sua incidência e duração, além dos movimentos migratórios.","e":"São os três determinantes da prevalência. Emigração de doentes ou imigração de sadios reduz a prevalência; o contrário a aumenta.","refs":[{"c":2,"p":27,"p2":27,"s":"s2-5"}],"a":"V"},{"id":"p2024-q1.3","t":"A taxa de incidência reflete a velocidade com que surgem novos casos de uma doença ou problema de saúde na população e pode ser calculada como a razão entre o número de casos novos e o total de pessoa-tempo obtido num determinado período de tempo, a partir do acompanhamento da população estudada.","e":"TI = I / pessoa-tempo, também chamada densidade de incidência ou força de morbidade.","refs":[{"c":2,"p":17,"p2":17,"s":"s2-2"}],"a":"V"},{"id":"p2024-q1.4","t":"Letalidade é a razão entre o número de óbitos por uma doença X e o número de indivíduos que apresentam a doença X.","e":"É a mortalidade restrita a quem tem a doença. Como proporção, o denominador são os casos diagnosticados no período.","refs":[{"c":2,"p":24,"p2":25,"s":"s2-4"}],"a":"V"},{"id":"p2024-q1.5","t":"Incidência acumulada é uma proporção e representa uma estimativa de risco de desenvolver uma doença, durante um intervalo de tempo determinado.","e":"IA = casos novos / não-doentes no início (t0). O numerador está contido no denominador, vai de 0 a 1 e precisa da referência de tempo.","refs":[{"c":2,"p":21,"p2":22,"s":"s2-3"}],"a":"V"}],"prova":2024,"num":1,"cap":2,"title":"Medidas de frequência"},{"id":"p2024-q2","src":"prova","type":"vf","items":[{"id":"p2024-q2.1","t":"O denominador da taxa de mortalidade materna na área A e período P é o número de mulheres em idade reprodutiva na área A e período P.","e":"A razão de mortalidade materna usa os nascidos vivos (× 100.000) como aproximação do número de gestantes expostas.","refs":[{"c":3,"p":47,"p2":47,"s":"s3-5"}],"a":"F"},{"id":"p2024-q2.2","t":"A redução do componente neonatal da mortalidade infantil pode ser atingida por medidas simples, como o uso de sais de hidratação oral nos casos de diarreia infantil.","e":"A TRO reduz o componente pós-neonatal (causas exógenas, como a diarreia). O neonatal depende de pré-natal, parto e cuidados perinatais, que são mais complexos.","refs":[{"c":3,"p":51,"p2":52,"s":"s3-7"}],"a":"F"},{"id":"p2024-q2.3","t":"A queda da taxa de mortalidade infantil no Brasil entre 1960 e 2000 pode ser atribuída fundamentalmente à melhoria de fatores ambientais e sociais.","e":"A queda veio sobretudo do componente pós-neonatal: saneamento, infraestrutura urbana, ações de saúde coletiva (vacinação, TRO) e queda da fecundidade.","refs":[{"c":3,"p":52,"p2":53,"s":"s3-7"},{"c":6,"p":130,"p2":130,"s":"s6-3"}],"a":"V"},{"id":"p2024-q2.4","t":"A padronização dos coeficientes gerais de mortalidade tem como objetivo aumentar a comparabilidade entre locais com composição etária distintas, podendo ser feita por meio do método direto ou indireto.","e":"Direto: aplica as taxas específicas a uma população-padrão. Indireto: aplica as taxas do padrão à população estudada, dando a RMP (SMR).","refs":[{"c":3,"p":38,"p2":41,"s":"s3-3"}],"a":"V"},{"id":"p2024-q2.5","t":"Um dos indicadores baseados em medidas do tempo de vida é os anos potenciais de vida perdidos. Expressa o efeito das mortes ocorridas precocemente em relação à duração esperada da vida. Ele é calculado por meio da técnica denominada tábua de sobrevivência ou tábua de vida.","e":"O começo está certo, mas o APVP é calculado como a soma de dx × (L − x), com uma idade-limite L. A tábua de vida é a técnica da esperança de vida.","refs":[{"c":3,"p":61,"p2":61,"s":"s3-9"},{"c":3,"p":64,"p2":65,"s":"s3-10"}],"a":"F"}],"prova":2024,"num":2,"cap":3,"title":"Mortalidade materna, infantil e padronização"},{"id":"p2024-q3","src":"prova","type":"vf","ctx":["Mortalidade por doenças do aparelho circulatório (DCV) no Brasil por faixa etária e sexo, 2009. TME = taxa de mortalidade específica (óbitos por 100.000 hab.); MP = mortalidade proporcional (%). Fonte: SIM/IBGE."],"table":[["Faixa etária","Homens TME","Homens MP","Mulheres TME","Mulheres MP","Total TME"],["0 a 29","0,8","15,0","0,3","25,3","0,6"],["30 a 39","9,8","10,2","3,7","16,9","6,7"],["40 a 49","40,7","21,1","17,8","27,3","28,8"],["50 a 59","126,1","31,5","51,2","32,0","86,7"],["60 a 69","281,0","37,5","136,5","37,0","203,3"],["70 a 79","550,1","39,7","323,5","40,5","422,2"],["80 e mais","960,8","40,2","822,1","42,9","878,2"],["Total","59,7","28,7","41,2","34,8","50,3"]],"items":[{"id":"p2024-q3.1","t":"O risco de morrer por DCV é maior em homens do que em mulheres.","e":"Risco = taxa: em todas as faixas etárias a TME masculina é maior que a feminina (no total, 59,7 contra 41,2/100 mil).","refs":[{"c":3,"p":44,"p2":45,"s":"s3-4"}],"a":"V"},{"id":"p2024-q3.2","t":"O aumento do número de casos de DCV em um determinado período T e área A aumenta, necessariamente, a Mortalidade Proporcional por DCV no mesmo período e área.","e":"A MP depende também dos óbitos por outras causas (o denominador é o total de óbitos), e casos não são óbitos. No livro, a MP por DAC no Sul caiu enquanto o número absoluto subiu.","refs":[{"c":3,"p":44,"p2":44,"s":"s3-4"}],"a":"F"},{"id":"p2024-q3.3","t":"O principal motivo de a Mortalidade Proporcional por DCV entre indivíduos menores de 49 anos ser menor no sexo masculino é o fato das Taxas de Mortalidade por Causas Externas serem muito mais elevadas entre adolescentes e jovens do sexo masculino do que entre adolescentes e jovens do sexo feminino.","e":"Entre homens jovens as causas externas \"ocupam\" grande parte do total de óbitos, então a fatia das DCV fica menor, mesmo com taxa de DCV maior que a das mulheres.","refs":[{"c":3,"p":45,"p2":45,"s":"s3-4"},{"c":6,"p":137,"p2":138,"s":"s6-5"}],"a":"V"},{"id":"p2024-q3.4","t":"De acordo com a tabela acima, cerca de 28% e 34% dos óbitos entre homens e mulheres, respectivamente, são devidos às DCV.","e":"A MP total é 28,7% nos homens e 34,8% nas mulheres.","refs":[{"c":3,"p":43,"p2":43,"s":"s3-4"}],"a":"V"},{"id":"p2024-q3.5","t":"A Taxa de Mortalidade Específica por DCV é calculada dividindo-se o número de óbitos por DCV em um determinado período P e área A pela população com DCV, residente naquela mesma área A e período P.","e":"Dividir pelos doentes dá a letalidade. A taxa de mortalidade por causa usa toda a população residente (meio do período).","refs":[{"c":3,"p":45,"p2":45,"s":"s3-4"},{"c":2,"p":25,"p2":25,"s":"s2-5"}],"a":"F"}],"prova":2024,"num":3,"cap":3,"title":"Mortalidade por doenças do aparelho circulatório"},{"id":"p2024-q4","src":"prova","type":"vf","ctx":["Diagrama de controle da doença meningocócica no período 1983-1993, Brasil, 1994 (Guia de Vigilância Epidemiológica, MS). Linhas: média, limite máximo esperado e incidência de 1994 (casos/100 mil hab.)."],"imgs":[{"f":"2024-q4-meningococica.png","cap":"Diagrama de controle (média, limite máximo esperado, 1994)"}],"items":[{"id":"p2024-q4.1","t":"O Limite Máximo Esperado para cada mês do calendário foi calculado a partir das médias e desvios-padrão mensais das taxas de incidência de doença meningocócica em anos anteriores naquele mesmo mês.","e":"No método da distribuição normal, para cada mês o limite superior é a média + 1,96 desvio-padrão das incidências daquele mês nos anos anteriores (geralmente 10, sem os anos epidêmicos).","refs":[{"c":4,"p":95,"p2":96,"s":"s4-5"}],"a":"V"},{"id":"p2024-q4.2","t":"A incidência da doença meningocócica apresenta um padrão sazonal.","e":"A média histórica (e 1994) sobe no inverno (junho a agosto) e cai no verão: variação que se repete nas estações do ano.","refs":[{"c":4,"p":90,"p2":90,"s":"s4-3"},{"c":4,"p":95,"p2":95,"s":"s4-5"}],"a":"V"},{"id":"p2024-q4.3","t":"Constata-se que houve uma epidemia de doença meningocócica apenas no mês de julho de 1994 porque a Taxa de Incidência da doença ultrapassou o valor de 0,45 casos para 100.000 habitantes.","e":"O critério é ultrapassar o limite máximo esperado de cada mês, não um valor fixo. Em 1994 a incidência ficou acima do limite em vários meses (jan, jun-set, nov).","refs":[{"c":4,"p":95,"p2":96,"s":"s4-5"}],"a":"F"},{"id":"p2024-q4.4","t":"Há uma tendência de aumento na taxa de incidência de doença meningocócica.","e":"O diagrama compara um ano com o padrão histórico mensal; não mostra uma série de vários anos, então não permite avaliar tendência secular.","refs":[{"c":4,"p":88,"p2":88,"s":"s4-3"},{"c":4,"p":95,"p2":95,"s":"s4-5"}],"a":"F"},{"id":"p2024-q4.5","t":"Epidemia pode ser definida como uma elevação temporária e lenta da Taxa de Incidência de uma determinada doença.","e":"Epidemia é uma elevação brusca, temporária e significativamente acima do esperado.","refs":[{"c":4,"p":92,"p2":92,"s":"s4-4"}],"a":"F"}],"prova":2024,"num":4,"cap":4,"title":"Diagrama de controle da doença meningocócica"},{"id":"p2024-q5","src":"prova","type":"vf","ctx":["O diagrama representa o acompanhamento de uma população em estudo epidemiológico realizado entre o início de 2000 e o final de 2014 para estudar fatores de risco para uma doença X. As entradas ocorreram no início do ano e os eventos (óbito ou adoecimento) no meio do ano. Todos os participantes foram acompanhados até a ocorrência do evento. Legenda: * início do seguimento; – seguimento; + perda; ! adoecimento."],"imgs":[{"f":"2024-q5-diagrama.png","cap":"Diagrama de seguimento dos 12 participantes"}],"items":[{"id":"p2024-q5.1","t":"O diagrama acima representa uma população dinâmica.","e":"Os participantes entram em momentos diferentes (2000, 2002, 2004) e saem por adoecimento ou perda: população dinâmica (aberta).","refs":[{"c":2,"p":17,"p2":18,"s":"s2-2"}],"a":"V"},{"id":"p2024-q5.2","t":"A quantidade de pessoa-tempo é 12.","e":"12 é o número de pessoas. Somando o tempo de cada uma (anos completos + 0,5 no ano do evento ou perda): 2,5 + 11,5 + 13,5 + 15 + 8,5 + 5,5 + 13 + 10,5 + 4,5 + 6,5 + 2,5 + 6,5 = 100 pessoas-ano.","refs":[{"c":2,"p":17,"p2":19,"s":"s2-2"}],"a":"F"},{"id":"p2024-q5.3","t":"A taxa de incidência da doença é 0,08 caso por pessoa/ano.","e":"São 8 adoecimentos (IDs 02, 03, 05, 08, 09, 10, 11, 12) em 100 pessoas-ano: TI = 8/100 = 0,08.","refs":[{"c":2,"p":17,"p2":19,"s":"s2-2"}],"a":"V"},{"id":"p2024-q5.4","t":"A letalidade da doença é 0,2.","e":"O diagrama não informa óbitos entre os doentes, então não é possível calcular a letalidade.","refs":[{"c":2,"p":25,"p2":25,"s":"s2-5"}],"a":"F"},{"id":"p2024-q5.5","t":"A prevalência de período da doença considerando os 15 anos de acompanhamento é 0,67.","e":"Prevalência de período = (casos no início + casos novos) / população = (0 + 8)/12 ≈ 0,67.","refs":[{"c":2,"p":28,"p2":29,"s":"s2-5"}],"a":"V"}],"prova":2024,"num":5,"cap":2,"title":"Diagrama de seguimento: pessoa-tempo"},{"id":"p2024-q6","src":"prova","type":"vf","items":[{"id":"p2024-q6.1","t":"Detectar epidemias, recomendar adoções de medidas de prevenção e avaliar o impacto de intervenções são alguns dos seus objetivos.","e":"Estão entre os objetivos listados, junto com descrever tendências e grupos de risco, estimar magnitude e avaliar as estratégias.","refs":[{"c":5,"p":104,"p2":104,"s":"s5-2"}],"a":"V"},{"id":"p2024-q6.2","t":"Coleta, processamento e análise de dados, investigação epidemiológica e divulgação de informações são atividades de competência exclusiva do nível federal.","e":"As atividades são feitas em todos os níveis, com prioridade para o municipal (descentralização no SUS). O nível federal e o estadual têm papel estratégico, normativo e avaliativo.","refs":[{"c":5,"p":104,"p2":105,"s":"s5-2"}],"a":"F"},{"id":"p2024-q6.3","t":"Apenas médicos podem notificar doenças, agravos e eventos de saúde de notificação compulsória.","e":"Todos os profissionais de saúde e os responsáveis por estabelecimentos de saúde e ensino são obrigados; qualquer cidadão pode notificar.","refs":[{"c":5,"p":106,"p2":106,"s":"s5-3"}],"a":"F"},{"id":"p2024-q6.4","t":"Oportunidade caracteriza a capacidade que um sistema tem para rapidamente promover atividades que possam interromper a propagação da doença.","e":"Oportunidade é a agilidade do sistema: o intervalo entre a ocorrência, a notificação, a investigação e as medidas de controle.","refs":[{"c":5,"p":114,"p2":114,"s":"s5-5"}],"a":"V"},{"id":"p2024-q6.5","t":"Uma característica desejável de um sistema de vigilância epidemiológica é a sua capacidade de detectar todos os casos de doença, ou seja, sua especificidade.","e":"Detectar todos os casos é sensibilidade. Especificidade é a capacidade de excluir os não-casos.","refs":[{"c":5,"p":114,"p2":114,"s":"s5-5"}],"a":"F"}],"prova":2024,"num":6,"cap":5,"title":"Sistema de vigilância epidemiológica"},{"id":"p2024-q7","src":"prova","type":"vf","ctx":["Um inquérito populacional censitário foi realizado na primeira semana de janeiro de 2009 e contemplou 10.000 moradores da cidade C. Este inquérito identificou 500 casos da doença D. Esta população dinâmica encontra-se em estado estacionário (estável) em termos demográficos e sanitários. Ao longo do ano (2009), mais 200 indivíduos foram diagnosticados com a doença D. De todos os casos identificados nesse período, 10 morreram."],"items":[{"id":"p2024-q7.1","t":"A prevalência da doença D no início de 2009 é 5%.","e":"500 casos existentes / 10.000 moradores = 0,05 = 5%.","refs":[{"c":2,"p":26,"p2":26,"s":"s2-5"}],"a":"V"},{"id":"p2024-q7.2","t":"A taxa de incidência da doença D no ano de 2009 é 0,05 caso por pessoa/ano.","e":"Só quem não tinha a doença está sob risco: cerca de 9.500 pessoas-ano (população estável, 1 ano). TI ≈ 200/9.500 ≈ 0,021 caso/pessoa-ano. 0,05 é a prevalência.","refs":[{"c":2,"p":17,"p2":20,"s":"s2-2"}],"a":"F"},{"id":"p2024-q7.3","t":"A incidência acumulada da doença D em um período de um ano (2009) é 2/95 (i.e., 0,02).","e":"IA = casos novos / não-doentes no início = 200 / 9.500 = 2/95 ≈ 0,021.","refs":[{"c":2,"p":21,"p2":21,"s":"s2-3"}],"a":"V"},{"id":"p2024-q7.4","t":"A prevalência da doença D em 31 de dezembro de 2009 é 7%.","e":"Somar 500 + 200 ignora os 10 óbitos e possíveis curas. Além disso, em estado estacionário a prevalência tende a se manter. 7% não decorre dos dados.","refs":[{"c":2,"p":26,"p2":28,"s":"s2-5"}],"a":"F"},{"id":"p2024-q7.5","t":"A letalidade da doença é 1/20 (5%).","e":"Letalidade = óbitos / casos da doença no período = 10 / 700 = 1/70 ≈ 1,4%. 1/20 só seria correto se o denominador fosse 200.","refs":[{"c":2,"p":25,"p2":25,"s":"s2-5"}],"a":"F"}],"prova":2024,"num":7,"cap":2,"title":"Inquérito na cidade C"},{"id":"p2024-q8","src":"prova","type":"choice","ctx":["Identifique a que tipo concerne cada um dos estudos descritos. (Na prova de 2024 a numeração era: 1 experimental, 2 ecológico, 3 coorte, 4 caso-controle, 5 transversal, 6 nenhum.)"],"items":[{"id":"p2024-q8.1","t":"Objetivo: Analisar a distribuição espacial e a tendência temporal da taxa de incidência de AIDS no Brasil no período de 2005 a 2020. Métodos: Dados do SINAN/DATASUS foram estratificados por ano do diagnóstico, região do país/municípios de residência e faixa etária. Foram calculadas as taxas de incidência para a estimativa temporal por meio do modelo de joinpoint, bem como taxas bayesianas empíricas espaciais para a distribuição espacial pelo estimador de densidade de Kernel. Resultados: A TI no Brasil em 2020 foi de 17,69 casos por 100 mil habitantes. A tendência geral (2005–2020) foi de diminuição no Brasil, Sudeste e Sul; o Norte demonstrou aumento.","e":"Taxas por ano, região e município (dados agregados), com análise de tendência e espacial: estudo ecológico.","refs":[{"c":8,"p":177,"p2":178,"s":"s8-3"},{"c":4,"p":85,"p2":85,"s":"s4-2"}],"a":4},{"id":"p2024-q8.2","t":"Objetivo: analisar a prevalência de saúde cardiovascular (SCV) ideal na população adulta brasileira. Métodos: estudo com base na Pesquisa Nacional de Saúde de 2019 (n = 77.494); foram estimadas as prevalências e IC95% de SCV ideal (sete metas alcançadas simultaneamente) e por metas individuais. Resultados: apenas 0,5% da população apresentou SCV ideal, com maior prevalência entre os de maior escolaridade e os residentes em áreas urbanas.","e":"Inquérito de base populacional, dados individuais num único momento, medindo prevalência: transversal.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":3},{"id":"p2024-q8.3","t":"Estudo com o objetivo de verificar a associação entre ocupações e cânceres linfohematopoiéticos em um hospital público de referência no Ceará, 2019-2021. O grupo caso foi constituído por pacientes com mieloma múltiplo, leucemias ou linfomas não Hodgkin (n = 114), enquanto indivíduos comparáveis de unidade hospitalar distinta constituíram o grupo controle (n = 114), formando pares 1:1. Comparamos os grupos em regressão logística condicional. Tipo de ocupação, zona de residência, tipo de abastecimento de água e Superintendência Regional de residência se mostraram associados ao desfecho.","e":"Seleção por desfecho (com câncer = casos; sem = controles pareados) e comparação das exposições (ocupação): caso-controle pareado.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":2},{"id":"p2024-q8.4","t":"O objetivo foi avaliar a associação das condições de nascimento, do estado nutricional e do crescimento infantil com fatores de risco cardiometabólicos aos 30 anos de idade. O estudo incluiu todos os nascidos vivos em 1982 em hospitais de Pelotas, RS, residentes da área urbana. As mães foram entrevistadas no parto e os participantes foram acompanhados em diferentes idades. Foram usados dados de peso e altura ao nascer e aos 2 e 4 anos e fatores de risco cardiovascular aos 30 anos.","e":"Um grupo definido (nascidos em 1982) foi acompanhado ao longo do tempo, com exposições medidas antes do desfecho: coorte (de nascimentos).","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":1},{"id":"p2024-q8.5","t":"Objetivo: Avaliar o efeito da modificação do ambiente escolar sobre a atividade física em estudantes adolescentes. Métodos: Sete escolas públicas em Duque de Caxias foram aleatorizadas em grupos controle e intervenção. O grupo de intervenção sofreu modificações no ambiente escolar (pintura de quadra, amarelinhas, equipamentos esportivos, personagem Super Ativa). Foram utilizados modelos lineares generalizados. Resultados: 975 adolescentes; o tempo de atividade física aumentou em ambos os grupos, sem diferença entre intervenção e controle (p=0,52).","e":"O pesquisador controlou a intervenção e as escolas foram aleatorizadas: estudo experimental (ensaio comunitário, randomizado por conglomerado).","refs":[{"c":8,"p":176,"p2":177,"s":"s8-3"}],"a":0}],"prova":2024,"num":8,"cap":8,"title":"Identificação de desenhos de estudo","opts":["Estudo experimental","Estudo de coorte","Estudo caso-controle","Estudo transversal","Estudo ecológico","Nenhum dos anteriores"]},{"id":"p2024-q9","src":"prova","type":"open","ctx":["Figuras: estimativas de distribuição populacional por idade e sexo (Brasil 1980, 2000 e 2050); crescimento natural, taxa de mortalidade e crescimento populacional (Brasil 2000-2060); evolução da proporção de mortalidade por grupos de causas (Brasil 1930-2005). Com base no seu conhecimento sobre as mudanças do perfil epidemiológico brasileiro nos últimos 50-70 anos, analise e justifique as alterações visualizadas nas figuras."],"imgs":[{"f":"2024-q9-piramide-1980.png","cap":"Pirâmide 1980"},{"f":"2024-q9-piramide-2000.png","cap":"Pirâmide 2000"},{"f":"2024-q9-piramide-2050.png","cap":"Pirâmide 2050 (projeção)"},{"f":"2024-q9-crescimento.png","cap":"Natalidade, mortalidade e população, 2000-2060"},{"f":"2024-q9-mortalidade-causas.png","cap":"Mortalidade proporcional por grupos de causas, 1930-2005"}],"keys":["Pirâmides: em 1980 a base é larga (alta fecundidade). Em 2000 a base se estreita. Em 2050 o formato é quase retangular, com topo largo: envelhecimento demográfico.","Causa principal do envelhecimento: queda da fecundidade (de ~6 filhos por mulher até 1960 para ~2,35 em 2000 e abaixo da reposição), somada à queda da mortalidade e ao aumento da esperança de vida (de 45,9 anos em 1950 para 70,4 em 2000).","Feminização do envelhecimento: mais mulheres nas idades avançadas (menor mortalidade feminina).","Natalidade e mortalidade: a taxa bruta de natalidade cai e a de mortalidade sobe a partir de ~2020 por causa do envelhecimento. As curvas se cruzam por volta de 2040-2045, o crescimento natural fica negativo e a população atinge o pico e depois diminui. É a fase final da transição demográfica.","Mortalidade por causas: as DIP caem de ~45% dos óbitos em 1930 para ~5% em 2005; aparelho circulatório, neoplasias e causas externas crescem. É a transição epidemiológica (Omran: era das doenças degenerativas e provocadas pelo homem).","Explicações: urbanização e industrialização, saneamento, vacinação (PNI, 1973), antibióticos, TRO, escolaridade e queda da mortalidade infantil.","Particularidades do Brasil: transição \"prolongada\" ou polarizada (Frenk), com superposição de DIP e DCNT (dupla carga), reemergência (dengue, cólera), desigualdades regionais e sociais, e peso das causas externas entre homens jovens."],"prova":2024,"num":9,"cap":6,"pts":2.0,"title":"Mudanças do perfil epidemiológico brasileiro","refs":[{"c":6,"p":126,"p2":132,"s":"s6-2"},{"c":6,"p":134,"p2":139,"s":"s6-4"},{"c":3,"p":32,"p2":32,"s":"s3-1"}]},{"id":"p2025-q1","src":"prova","type":"vf","ctx":["Incidência mensal de sarampo na cidade de São Paulo, 1960 a 1993 (Waldman & Rosa)."],"imgs":[{"f":"2025-q1-sarampo.png","cap":"Incidência mensal de sarampo, São Paulo, 1960-1993"}],"items":[{"id":"p2025-q1.1","t":"As flutuações na incidência de sarampo mostradas no gráfico acima indicam a existência de uma variação sazonal da doença no estado de São Paulo, principalmente entre as semanas 67 e 69.","e":"O eixo mostra anos (60 a 93), não semanas. Os grandes picos de 1967-1969 se repetem a cada 2-3 anos: são variações cíclicas, não sazonais. E os dados são da cidade, não do estado.","refs":[{"c":4,"p":90,"p2":90,"s":"s4-3"}],"a":"F"},{"id":"p2025-q1.2","t":"A figura apresenta tendência crescente na incidência de sarampo em São Paulo-SP, nos anos 1960, com declínio posterior. Essa redução pode ter sido ocasionada pelas melhorias gerais das condições de vida na cidade e à introdução e aumento de cobertura da vacinação a posteriori.","e":"Os picos crescem até ~1970 e depois a incidência despenca, coincidindo com a vacinação e a melhora das condições de vida.","refs":[{"c":4,"p":88,"p2":90,"s":"s4-3"}],"a":"V"},{"id":"p2025-q1.3","t":"Analisando a figura, observa-se que a ocorrência de um surto tende a reduzir o risco de incidência no curto prazo de sarampo. Os sobreviventes da doença adquirem imunidade e, com menos crianças suscetíveis, a transmissão torna-se menos provável.","e":"É o mecanismo dos ciclos do sarampo: depois da epidemia sobram poucos suscetíveis; com os nascimentos eles se acumulam de novo e vem outro pico.","refs":[{"c":4,"p":90,"p2":90,"s":"s4-3"}],"a":"V"},{"id":"p2025-q1.4","t":"Mesmo nos períodos quando não houve surtos epidêmicos (entre 1975 e 1983) com grande aumento do número de casos da doença, observa-se um aumento não cíclico da incidência mensal.","e":"Entre 1975 e 1983 a incidência fica baixa, com pequenas oscilações e tendência de queda. Não há aumento.","refs":[{"c":4,"p":88,"p2":88,"s":"s4-3"}],"a":"F"},{"id":"p2025-q1.5","t":"Sobre os diferentes tipos de variação na incidência de uma doença, alterações diferentes do esperado são denominadas variações irregulares. Neste caso, a análise da evolução temporal utilizando dados históricos é essencial para avaliar se a incidência da doença está dentro do esperado ou não.","e":"Variações irregulares são alterações inusitadas. Para saber se algo está fora do esperado é preciso comparar com a série histórica (padrão endêmico, diagrama de controle).","refs":[{"c":4,"p":91,"p2":91,"s":"s4-3"},{"c":4,"p":95,"p2":95,"s":"s4-5"}],"a":"V"}],"prova":2025,"num":1,"cap":4,"title":"Incidência de sarampo em São Paulo, 1960-1993"},{"id":"p2025-q2","src":"prova","type":"vf","items":[{"id":"p2025-q2.1","t":"A vigilância epidemiológica é definida como um conjunto de ações que proporciona o conhecimento, detecção ou prevenção de qualquer mudança nos fatores determinantes e condicionantes de saúde coletiva, com a finalidade de recomendar e adotar as medidas de prevenção e controle de doenças. Este conceito é restrito às doenças transmissíveis.","e":"A definição (Lei 8.080/90) está certa, mas não se restringe às transmissíveis: inclui DCNT, agravos, acidentes, violências e fatores de risco.","refs":[{"c":5,"p":103,"p2":104,"s":"s5-1"}],"a":"F"},{"id":"p2025-q2.2","t":"Coleta, processamento e análise de dados, investigação epidemiológica e divulgação de informações são atividades de competência do nível federal e estadual.","e":"Essas atividades acontecem em todos os níveis, e o SUS prioriza o municipal (local).","refs":[{"c":5,"p":104,"p2":105,"s":"s5-2"}],"a":"F"},{"id":"p2025-q2.3","t":"Dados de morbidade podem ser obtidos a partir da notificação de casos e surtos, da investigação epidemiológica, da busca ativa de casos, levantamento da produção de serviços laboratoriais e de atenção ambulatorial e hospitalar, inquéritos e sistemas de informação, como o SINAN e SIH.","e":"O livro lista exatamente essas fontes para os dados de morbidade.","refs":[{"c":5,"p":105,"p2":105,"s":"s5-2"}],"a":"V"},{"id":"p2025-q2.4","t":"A base do sistema de vigilância epidemiológica é formada pela notificação compulsória de doenças e agravos. Entretanto, fontes complementares são fundamentais para garantir maior qualidade e abrangência da informação.","e":"A notificação compulsória é a principal fonte. Investigações, laboratórios, sistemas de informação, sentinelas, imprensa e comunidade a complementam.","refs":[{"c":5,"p":106,"p2":106,"s":"s5-3"}],"a":"V"},{"id":"p2025-q2.5","t":"A lista de doenças de notificação é atualizada sistematicamente. Entretanto, alguns aspectos devem ser considerados ao realizar a notificação, um deles é notificar apenas casos confirmados da doença.","e":"Deve-se notificar já a simples suspeita, o que dá sensibilidade e oportunidade, sem esperar a confirmação laboratorial.","refs":[{"c":5,"p":106,"p2":107,"s":"s5-3"}],"a":"F"}],"prova":2025,"num":2,"cap":5,"title":"Conceitos de vigilância epidemiológica"},{"id":"p2025-q3","src":"prova","type":"vf","items":[{"id":"p2025-q3.1","t":"Os sistemas de informação em saúde têm como um de seus principais objetivos possibilitar a análise da situação de saúde no nível local, tendo como referências regiões heterogêneas.","e":"O objetivo é analisar a situação de saúde no nível local tomando como referência microrregiões homogêneas. A palavra \"heterogêneas\" invalida a assertiva.","refs":[{"c":5,"p":107,"p2":107,"s":"s5-3"}],"a":"F"},{"id":"p2025-q3.2","t":"A investigação epidemiológica é um trabalho de campo, realizado a partir de dados notificados e seus contatos que tem como propósito final orientar a recomendação e adoção oportuna de medidas de controle para impedir a ocorrência de novos casos.","e":"É a definição do livro: confirmar o diagnóstico, achar a fonte e o modo de transmissão, os expostos e os casos secundários, para controlar.","refs":[{"c":5,"p":112,"p2":112,"s":"s5-4"}],"a":"V"},{"id":"p2025-q3.3","t":"Sistemas de vigilância sentinela utilizam apenas um subconjunto das fontes de dados possíveis, aumentando a capacidade de obter informações detalhadas e válidas. Tais dados são suficientes para o cálculo de taxas de incidência para uma determinada população.","e":"A primeira parte está certa, mas a perda de representatividade faz os dados de sentinela serem insuficientes para calcular incidências e pouco generalizáveis.","refs":[{"c":5,"p":113,"p2":113,"s":"s5-4"}],"a":"F"},{"id":"p2025-q3.4","t":"Algumas medidas quantitativas podem ser utilizadas para a avaliação de um sistema de vigilância epidemiológica. Dentre elas, destaca-se o valor preditivo positivo (VPP), que consiste na proporção dos casos identificados pelo sistema que não o são. O VPP diminui com a especificidade do critério utilizado para a definição do caso e com a incidência do agravo.","e":"O VPP é a proporção dos identificados que de fato são casos, e aumenta com a especificidade da definição de caso e com a frequência (prevalência) do agravo.","refs":[{"c":5,"p":114,"p2":114,"s":"s5-5"}],"a":"F"},{"id":"p2025-q3.5","t":"Define-se como surto ou epidemia a ocorrência de um evento relacionado à saúde/doença que excede a expectativa normal. Este ano, por exemplo, observou-se uma epidemia de dengue no Brasil devido ao número de casos de dengue maior do que o esperado desta doença no país.","e":"A definição está correta e o exemplo também: em 2024 os casos de dengue superaram muito o esperado.","refs":[{"c":5,"p":115,"p2":115,"s":"s5-6"}],"a":"V"}],"prova":2025,"num":3,"cap":5,"title":"Sistemas de informação, investigação e sentinela"},{"id":"p2025-q4","src":"prova","type":"choice","ctx":["Identifique o tipo de desenho de estudo de cada resumo."],"items":[{"id":"p2025-q4.1","t":"Objetivo: Identificar os padrões alimentares de adolescentes brasileiros para cada uma das cinco regiões do país, e verificar se há diferença na adesão dos padrões alimentares de acordo com idade, sexo e tipo de escola. Métodos: Foram analisados dados de 71.298 adolescentes de 12 a 17 anos que participaram do Estudo de Riscos Cardiovasculares em Adolescentes (ERICA). Os dados de consumo alimentar foram obtidos por recordatório de 24h e os padrões identificados por análise fatorial; usou-se regressão linear. Resultados: três padrões comuns às regiões (tradicional, pão e café, não saudável) e um quarto na Região Norte.","e":"Dados individuais coletados num único momento (inquérito escolar), sem seguimento: transversal.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":3},{"id":"p2025-q4.2","t":"Objetivo: Atualizar o conhecimento sobre o aborto inseguro no país. Métodos: Foi realizada busca e seleção de estudos via MEDLINE e LILACS, no período 2008 a 2018, com avaliação da qualidade dos artigos (Instituto Joanna Briggs). Resultados: Foram avaliados 50 artigos. A prevalência de aborto induzido foi estimada em 15% em 2010 e 13% em 2016; a razão de aborto induzido por 1.000 mulheres em idade fértil reduziu de 1995 a 2013. Há provável sub-registro de óbitos maternos por aborto.","e":"É uma revisão da literatura (sistemática): a unidade de análise são artigos, não pessoas ou populações. Não é nenhum dos cinco desenhos.","refs":[{"c":8,"p":176,"p2":179,"s":"s8-3"}],"a":5},{"id":"p2025-q4.3","t":"Objetivo: Avaliar a influência da variação da implantação do Sistema de Informações sobre Mortalidade (SIM) nos resultados antes e depois da intervenção para aprimoramento do sistema em Pernambuco. Métodos: Foram explicitados o modelo lógico e a matriz de indicadores e julgamento do SIM. Coletaram-se dados nos 184 municípios. Obteve-se o grau de implantação a partir de indicadores de estrutura e processo, relacionado aos de resultado. Resultados: o SIM foi classificado como parcialmente implantado antes (70,6%) e depois (73,1%) da intervenção.","e":"É uma pesquisa avaliativa (avaliação de implantação de um sistema de informação), não um estudo epidemiológico de exposição e desfecho em pessoas. A melhor opção é \"nenhum dos anteriores\". (Gabarito não oficial.)","refs":[{"c":8,"p":179,"p2":179,"s":"s8-3"}],"a":5},{"id":"p2025-q4.4","t":"Objetivo: Avaliar se as trajetórias do nível de educação e de renda influenciam na mudança do consumo de vegetais ao longo de 13 anos entre funcionários públicos de uma universidade do Rio de Janeiro. Métodos: consumo de vegetais, renda e educação foram avaliados no início (1999) e na quarta onda (2011–12) do estudo Pró-Saúde; 2.381 participantes; modelos lineares generalizados. Resultados: homens e mulheres em mobilidade educacional ascendente aumentaram o consumo; mulheres que reduziram a renda tiveram menor probabilidade de consumir vegetais.","e":"Os mesmos indivíduos foram medidos em ondas sucessivas ao longo de 13 anos: coorte (Estudo Pró-Saúde).","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":1},{"id":"p2025-q4.5","t":"Objetivo: Identificar aglomerados espaciais para ocorrência da COVID-19 na população privada de liberdade (PPL) e analisar a tendência temporal dos casos confirmados no sistema penitenciário do Brasil. Métodos: unidades de análise: as cinco macrorregiões, os 26 estados e o Distrito Federal; todos os casos confirmados de 14/04 a 31/08/2020, do Painel do Departamento Penitenciário Nacional; estatística de varredura e análise de tendência. Resultados: 18.767 casos; 14 clusters espaciais de risco, o maior no Distrito Federal.","e":"Unidades de análise são estados e regiões (dados agregados): estudo ecológico, com análise espacial e temporal.","refs":[{"c":8,"p":177,"p2":178,"s":"s8-3"}],"a":4}],"prova":2025,"num":4,"cap":8,"title":"Identificação de desenhos de estudo","opts":["Estudo experimental","Estudo de coorte","Estudo caso-controle","Estudo transversal","Estudo ecológico","Nenhum dos anteriores"]},{"id":"p2025-q5","src":"prova","type":"vf","ctx":["Entre 1990 e 2019, o Brasil passou por uma série de mudanças e avanços na estruturação de seu sistema de saúde pública e de proteção social básica. As figuras apresentam a mortalidade proporcional e os DALY (anos de vida perdidos ajustados por incapacidade) por grupos de causa (infecciosas, DCNT, externas), segundo sexo e grupos etários, em 1990 e em 2019 (GBD, 2021)."],"imgs":[{"f":"2025-q5-daly-1990.png","cap":"1990: DALY e mortalidade proporcional por grupo de causas"},{"f":"2025-q5-daly-2019.png","cap":"2019: DALY e mortalidade proporcional por grupo de causas"}],"items":[{"id":"p2025-q5.1","t":"A carga de doenças infecciosas e parasitárias, tanto no DALY quanto na mortalidade ajustada, se destacam nas faixas etárias de crianças menores que 10 anos e, principalmente, entre as menores de 1 ano.","e":"As barras escuras (infecciosas) são maiores em < 1 ano e vão diminuindo até os 10 anos, nos dois anos e nos dois indicadores.","refs":[{"c":3,"p":76,"p2":77,"s":"s3-12"},{"c":6,"p":137,"p2":137,"s":"s6-5"}],"a":"V"},{"id":"p2025-q5.2","t":"Observa-se um aumento na participação da carga de doenças infecciosas e parasitárias entre as crianças menores de 1 ano, de 1990 a 2019.","e":"Em menores de 1 ano a fatia das infecciosas cai (de ~80% para ~65%) entre 1990 e 2019.","refs":[{"c":6,"p":137,"p2":139,"s":"s6-5"}],"a":"F"},{"id":"p2025-q5.3","t":"A partir dos 40 anos a contribuição das doenças crônicas passa a ser mais destacada e aumenta conforme a idade.","e":"Nas faixas a partir de 40-44 a DCNT domina e chega a mais de 90% nos idosos.","refs":[{"c":6,"p":134,"p2":134,"s":"s6-4"},{"c":3,"p":77,"p2":77,"s":"s3-12"}],"a":"V"},{"id":"p2025-q5.4","t":"A mortalidade por causas externas aumentou de forma exponencial no Brasil, no período investigado.","e":"As figuras mostram proporções por faixa etária, não taxas ao longo do tempo, e não há crescimento exponencial. As causas externas pesam muito nos homens jovens (15-39) nos dois anos.","refs":[{"c":6,"p":137,"p2":138,"s":"s6-5"}],"a":"F"},{"id":"p2025-q5.5","t":"Nota-se que o país se encontra em avançado estágio no seu processo de transição epidemiológica, tendo reduzido progressivamente o peso da mortalidade por doenças infecto-parasitárias, de uma forma geral, e aumentado o peso da morbimortalidade por doenças crônicas não transmissíveis (DCNT), especialmente nos grupos etários mais idosos.","e":"É a leitura geral das figuras. Ressalva do livro: no Brasil a transição é prolongada ou polarizada, com DIP ainda relevantes em alguns grupos e regiões.","refs":[{"c":6,"p":134,"p2":137,"s":"s6-4"}],"a":"V"}],"prova":2025,"num":5,"cap":6,"title":"DALY e mortalidade por grupos de causa, 1990-2019"},{"id":"p2025-q6","src":"prova","type":"vf","ctx":["Tabela 2: distribuição proporcional (%) dos indivíduos de 18 anos ou mais segundo indicadores de condições de saúde e médias de peso e altura, Brasil, PNS 2013 e 2019. Tabela 3: prevalências de obesidade segundo características sociodemográficas por sexo, PNS 2013 e 2019."],"imgs":[{"f":"2025-q6-tabela2.png","cap":"Tabela 2 · condições de saúde, peso e altura"},{"f":"2025-q6-tabela3.png","cap":"Tabela 3 · obesidade por características sociodemográficas"}],"items":[{"id":"p2025-q6.1","t":"O aumento das prevalências de obesidade e excesso de peso na população total entre os anos de 2013 e 2019 reflete o declínio do processo de transição nutricional no Brasil.","e":"O aumento da obesidade (20,8% → 25,9%) e do excesso de peso mostra que a transição nutricional avança: o país vai da desnutrição para a obesidade.","refs":[{"c":6,"p":143,"p2":143,"s":"s6-6"},{"c":6,"p":146,"p2":146,"s":"s6-6"}],"a":"F"},{"id":"p2025-q6.2","t":"O aumento significativo da estatura pode ser atribuído às melhorias nas condições socioeconômicas e de saúde e ao aumento da desnutrição em crianças ao longo dos anos.","e":"A melhora das condições explica o aumento da estatura; o aumento da desnutrição infantil, ao contrário, reduziria a altura.","refs":[{"c":6,"p":146,"p2":146,"s":"s6-6"}],"a":"F"},{"id":"p2025-q6.3","t":"O aumento das prevalências de obesidade reflete a melhoria geral das condições de vida da população, devido à redução das doenças infecciosas.","e":"O livro adverte que a transição nutricional não deve ser lida mecanicamente como melhoria de vida: a obesidade cresce justamente nas camadas desfavorecidas (má alimentação, alimentos baratos e calóricos, sedentarismo).","refs":[{"c":6,"p":146,"p2":146,"s":"s6-6"}],"a":"F"},{"id":"p2025-q6.4","t":"O aumento dos indivíduos que relataram ter colesterol alto, diagnóstico de doença do coração, hipertensão arterial, diabetes ou pelo menos uma DCNT pode refletir o processo de envelhecimento populacional, caracterizado pelo aumento da expectativa de vida da população.","e":"Com a população mais velha, as DCNT ficam mais frequentes. É a transição demográfica alimentando a epidemiológica.","refs":[{"c":6,"p":131,"p2":134,"s":"s6-3"}],"a":"V"},{"id":"p2025-q6.5","t":"Os maiores acréscimos na prevalência de obesidade ocorreram entre os homens com faixa de renda mediana (≥1 e < 2 SM), e nas mulheres com renda domiciliar per capita menor que 1 SM, indicando o papel da desigualdade social e de gênero no processo de transição nutricional no Brasil.","e":"Homens com 1-2 SM: 18,0% → 26,3% (+8,3 p.p., o maior entre eles); mulheres com < 1 SM: 24,5% → 30,1% (+5,6 p.p., o maior entre elas).","refs":[{"c":6,"p":146,"p2":146,"s":"s6-6"}],"a":"V"}],"prova":2025,"num":6,"cap":6,"title":"Transição nutricional (PNS 2013 e 2019)"},{"id":"p2025-q7","src":"prova","type":"vf","ctx":["A) Assinale V ou F. B) Considere a incidência acumulada IA = I / (N'0 − W/2), em que I é o número de casos incidentes entre t0 e t; N'0 é a população de não-doentes no instante t0; W é o número de perdas de seguimento entre t0 e t. Calcule a incidência acumulada do primeiro ano de um estudo no qual inicialmente 21 indivíduos participaram, 2 adoeceram e 2 não completaram o acompanhamento no primeiro ano (perda de seguimento)."],"items":[{"id":"p2025-q7.1","t":"Para o cálculo da prevalência e da incidência de uma dada doença é necessário saber quantas pessoas adoeceram em um determinado período.","e":"Isso vale para a incidência (casos novos no período). A prevalência conta os casos existentes num momento, novos ou antigos.","refs":[{"c":2,"p":14,"p2":14,"s":"s2-1"},{"c":2,"p":26,"p2":26,"s":"s2-5"}],"a":"F"},{"id":"p2025-q7.2","t":"Considere um estudo no qual 100 pessoas foram acompanhadas durante um ano e 2 pessoas foram acompanhadas durante 6 meses. No cálculo de pessoa-tempo de exposição, as duas pessoas que não completaram um ano são excluídas da conta pois não completaram um ano de acompanhamento.","e":"Pessoa-tempo soma o tempo de cada um: 100 × 1 + 2 × 0,5 = 101 pessoas-ano. Quem foi seguido por menos tempo contribui com o tempo que teve.","refs":[{"c":2,"p":17,"p2":18,"s":"s2-2"}],"a":"F"},{"id":"p2025-q7.3","t":"Em um estudo foram observadas 10 pessoas durante 6 meses, em outro estudo foram observadas 5 pessoas durante um ano. Pode-se concluir que a quantidade pessoa-tempo é exatamente igual nos dois estudos.","e":"10 × 0,5 = 5 pessoas-ano e 5 × 1 = 5 pessoas-ano.","refs":[{"c":2,"p":17,"p2":17,"s":"s2-2"}],"a":"V"},{"id":"p2025-q7.4","t":"(Parte B) A incidência acumulada calculada é 0,1.","e":"IA = 2 / (21 − 2/2) = 2/20 = 0,1. É o método atuarial: as perdas contam como metade do período.","refs":[{"c":2,"p":22,"p2":22,"s":"s2-3"}],"a":"V"},{"id":"p2025-q7.5","t":"(Parte B) A incidência acumulada calculada é 1,0.","e":"O valor correto é 0,1. Uma IA de 1,0 significaria que todos os não-doentes adoeceram.","refs":[{"c":2,"p":22,"p2":22,"s":"s2-3"}],"a":"F"}],"prova":2025,"num":7,"cap":2,"title":"Pessoa-tempo e incidência acumulada"},{"id":"p2025-q8","src":"prova","type":"vf","ctx":["Considere a mortalidade proporcional segundo a causa de óbito. A Tabela 3.5 do livro mostra taxas médias de mortalidade (por 100.000 habitantes) por grandes grupos de causas segundo sexo, Estado do Rio de Janeiro, 2003-2004."],"imgs":[{"f":"2025-q8-tabela35.png","cap":"Tabela 3.5 · taxas de mortalidade por causa e sexo, RJ 2003-2004"}],"items":[{"id":"p2025-q8.1","t":"Se na cidade A o número de óbitos por Covid-19 foi 1000 vezes maior do que o número de óbitos por Covid-19 na cidade B, podemos dizer que a mortalidade proporcional segundo a causa de óbito por Covid-19 na cidade A é maior do que na cidade B.","e":"A MP divide pelo total de óbitos de cada cidade. Sem conhecer esse total não dá para comparar; uma cidade muito maior pode ter MP igual ou menor.","refs":[{"c":3,"p":43,"p2":44,"s":"s3-4"}],"a":"F"},{"id":"p2025-q8.2","t":"O cálculo da mortalidade proporcional segundo a causa de óbito pode ser afetado quando não se tem estimativas populacionais precisas.","e":"A MP não usa população: são óbitos por causa / total de óbitos. É uma das vantagens dela.","refs":[{"c":3,"p":43,"p2":43,"s":"s3-4"}],"a":"F"},{"id":"p2025-q8.3","t":"A mortalidade proporcional segundo a causa de óbito indica a importância de uma causa ou um grupo de causas de morte em uma determinada população e pode ser utilizada no delineamento de prioridades na área da saúde.","e":"Ela mede a importância relativa das causas e serve para definir prioridades.","refs":[{"c":3,"p":43,"p2":43,"s":"s3-4"}],"a":"V"},{"id":"p2025-q8.4","t":"Existe uma uniformidade no conceito de morte, entretanto os indicadores de saúde baseados em dados de mortalidade não são isentos de erro.","e":"O conceito de morte é uniforme, mas sub-registro, causas mal definidas, erros de declaração e problemas no denominador afetam os indicadores.","refs":[{"c":3,"p":35,"p2":35,"s":"s3-2"},{"c":3,"p":37,"p2":38,"s":"s3-2"},{"c":3,"p":48,"p2":50,"s":"s3-6"}],"a":"V"},{"id":"p2025-q8.5","t":"Pela análise da tabela 3.5, não podemos fazer análises comparativas por sexo, pois não sabemos o total de homens e de mulheres.","e":"A tabela traz taxas (por 100 mil habitantes de cada sexo): já estão relativizadas pela população e podem ser comparadas, por exemplo causas externas 179,8 nos homens contra 30,9 nas mulheres.","refs":[{"c":3,"p":45,"p2":45,"s":"s3-4"}],"a":"F"}],"prova":2025,"num":8,"cap":3,"title":"Mortalidade proporcional por causa"},{"id":"p2025-q9","src":"prova","type":"open","ctx":["O termo hesitação vacinal foi proposto pela OMS, referindo-se ao atraso na aceitação ou recusa da vacinação, apesar da disponibilidade dos imunizantes nos serviços de saúde. A queda da cobertura vacinal desde 2016, as políticas de austeridade fiscal e o cenário político da pandemia deram ao tema maior relevância. Pela primeira vez na história do PNI, órgãos públicos de comunicação foram responsáveis pela disseminação de desinformação e desincentivo a uma vacina. (Texto adaptado de notícia da Fiocruz, 2024, sobre estudo de Ester Paiva Souto.) Considerando os conceitos básicos de epidemiologia e vigilância epidemiológica: qual o papel da epidemiologia na compreensão e controle da hesitação vacinal?"],"keys":["Descrever: medir coberturas vacinais e taxas de abandono (SI-PNI) por pessoa, lugar e tempo, e identificar grupos, regiões e períodos com queda de cobertura (tendências, mapas, clusters). É o objetivo descritivo da epidemiologia.","Explicar: estudar os determinantes da hesitação (escolaridade, renda, confiança nos serviços, desinformação, acesso, religião, política) com estudos transversais (inquéritos), caso-controle e coortes. É o objetivo analítico, para identificar fatores associados.","Vigilância: monitorar continuamente as coberturas e os eventos adversos pós-vacinação (de notificação compulsória), detectar a reemergência de doenças imunopreveníveis (sarampo, polio) e investigar surtos. É \"informação para ação\".","Predizer e controlar: estimar o risco de epidemias quando suscetíveis se acumulam (ex. ciclos do sarampo), avaliar o impacto de campanhas e intervenções de comunicação e orientar as prioridades.","Ação e comunicação: retroalimentar e divulgar informações confiáveis (controle social), apoiar a atenção básica e os ACS, e fortalecer o combate à desinformação.","Lembrar a história: o PNI (1973) erradicou a varíola, eliminou a poliomielite (último caso em 1989) e o sarampo. A hesitação ameaça esses ganhos (contratransição)."],"prova":2025,"num":9,"cap":5,"pts":2.0,"title":"O papel da epidemiologia na hesitação vacinal","refs":[{"c":8,"p":173,"p2":173,"s":"s8-1"},{"c":5,"p":103,"p2":104,"s":"s5-1"},{"c":5,"p":114,"p2":114,"s":"s5-5"},{"c":4,"p":90,"p2":90,"s":"s4-3"},{"c":6,"p":139,"p2":139,"s":"s6-5"}]},{"id":"c1-01","src":"livro","type":"vf","items":[{"id":"c1-01.1","t":"Na mitologia grega, Panaceia simbolizava a medicina curativa, enquanto Higeia representava a ideia de prevenção e de condições de vida saudáveis.","e":"As duas filhas de Asclépios representam as duas vertentes da medicina: a cura (Panaceia) e a saúde/prevenção (Higeia).","refs":[{"c":1,"p":3,"p2":3,"s":"s1-1"}],"a":"V"},{"id":"c1-01.2","t":"Hipócrates atribuía a ocorrência das doenças a causas sobrenaturais, sem relação com o ambiente.","e":"Em \"Ares, Águas e Lugares\" Hipócrates relaciona as doenças ao clima, à água e ao modo de vida: uma visão naturalista e ambiental.","refs":[{"c":1,"p":3,"p2":3,"s":"s1-1"},{"c":4,"p":83,"p2":83,"s":"s4-1"}],"a":"F"},{"id":"c1-01.3","t":"Thomas Sydenham contribuiu com as noções de constituição epidêmica e de história natural das doenças.","e":"Sydenham observava as doenças na população e no tempo. É um dos marcos do eixo da clínica moderna na formação da epidemiologia.","refs":[{"c":1,"p":4,"p2":4,"s":"s1-1"}],"a":"V"},{"id":"c1-01.4","t":"A Aritmética Política de William Petty e as tábuas de mortalidade de John Graunt estão entre as raízes estatísticas da epidemiologia.","e":"Graunt analisou os registros de óbitos (Bills of Mortality) de Londres no século XVII, um marco da estatística vital.","refs":[{"c":1,"p":4,"p2":4,"s":"s1-1"},{"c":3,"p":43,"p2":43,"s":"s3-4"}],"a":"V"},{"id":"c1-01.5","t":"O termo \"Medicina Social\" foi cunhado por Rudolf Virchow em 1900, no contexto da bacteriologia.","e":"O termo foi cunhado por Jules Guérin em 1838. Virchow é lembrado pelo estudo da epidemia de tifo e pela defesa da medicina como ciência social.","refs":[{"c":1,"p":5,"p2":5,"s":"s1-2"}],"a":"F"}],"cap":1,"title":"Origens da epidemiologia"},{"id":"c1-02","src":"livro","type":"vf","items":[{"id":"c1-02.1","t":"Pierre Louis, com seu estudo de 1825 sobre a tuberculose usando o \"método numérico\", é considerado por muitos um marco inaugural da epidemiologia.","e":"Louis aplicou contagem e comparação sistemática a 1.960 casos de tuberculose.","refs":[{"c":1,"p":5,"p2":5,"s":"s1-2"}],"a":"V"},{"id":"c1-02.2","t":"John Snow demonstrou a transmissão hídrica da cólera em Londres antes da identificação do agente causal.","e":"Em 1854, ao mapear as mortes em torno das bombas de água (Soho), Snow associou a cólera à água contaminada, quando a teoria dominante era a dos miasmas.","refs":[{"c":1,"p":6,"p2":6,"s":"s1-2"},{"c":4,"p":84,"p2":84,"s":"s4-1"}],"a":"V"},{"id":"c1-02.3","t":"William Farr ficou conhecido por organizar o primeiro sistema de vigilância de doenças crônicas nos Estados Unidos.","e":"Farr organizou o registro geral de estatísticas vitais na Inglaterra (1839) e uma classificação de causas de morte, precursora da CID.","refs":[{"c":1,"p":5,"p2":5,"s":"s1-2"},{"c":3,"p":43,"p2":43,"s":"s3-4"}],"a":"F"},{"id":"c1-02.4","t":"Florence Nightingale usou dados para mostrar a mortalidade por infecção entre os feridos na Guerra da Crimeia.","e":"Ela integrava a Sociedade Epidemiológica de Londres (1850), junto com John Snow.","refs":[{"c":1,"p":6,"p2":6,"s":"s1-2"}],"a":"V"},{"id":"c1-02.5","t":"Com a era bacteriológica (Pasteur e Koch), a ênfase da saúde passou do indivíduo para o coletivo, fortalecendo a Medicina Social.","e":"Foi o contrário: entre 1860 e 1900 a bacteriologia fortaleceu o enfoque clínico, curativo e individual, que suplantou o coletivo.","refs":[{"c":1,"p":6,"p2":6,"s":"s1-2"}],"a":"F"}],"cap":1,"title":"Século XIX: método numérico e saneamento"},{"id":"c1-03","src":"livro","type":"vf","items":[{"id":"c1-03.1","t":"O conceito de risco tornou-se objeto central da epidemiologia com a incorporação do raciocínio estatístico no início do século XX.","e":"Topley (1919), Howard (1921) e Frost (1933) usaram o \"risco\" como instrumento científico.","refs":[{"c":1,"p":7,"p2":7,"s":"s1-3"}],"a":"V"},{"id":"c1-03.2","t":"Wade Hampton Frost foi o primeiro professor de Epidemiologia, na Escola de Higiene e Saúde Pública da Johns Hopkins, criada em 1918 com apoio da Fundação Rockefeller.","e":"Na Inglaterra, Major Greenwood ocupou cargo equivalente na London School em 1928.","refs":[{"c":1,"p":6,"p2":6,"s":"s1-2"}],"a":"V"},{"id":"c1-03.3","t":"Goldberger demonstrou que a pelagra era uma doença infecciosa transmitida por insetos.","e":"Goldberger (1915) demonstrou a natureza carencial (nutricional) da pelagra, contra a teoria infecciosa.","refs":[{"c":1,"p":7,"p2":7,"s":"s1-3"}],"a":"F"},{"id":"c1-03.4","t":"Nos anos 1950 consolidaram-se os grandes estudos de coorte, como o de Framingham, e os ensaios clínicos controlados de Bradford Hill.","e":"Também nessa época Cornfield propôs estimadores do risco relativo, e a epidemiologia das doenças crônicas ganhou força.","refs":[{"c":1,"p":8,"p2":8,"s":"s1-4"}],"a":"V"},{"id":"c1-03.5","t":"O preventivismo dos anos 1930-40 levou à efetiva integração entre prevenção primária, secundária e terciária nos serviços de saúde americanos.","e":"Os níveis de prevenção foram formulados, mas o livro observa que o preventivismo ficou em grande parte na retórica.","refs":[{"c":1,"p":7,"p2":7,"s":"s1-3"}],"a":"F"}],"cap":1,"title":"Século XX: risco, preventivismo e métodos"},{"id":"c1-04","src":"livro","type":"vf","items":[{"id":"c1-04.1","t":"Oswaldo Cruz comandou campanhas contra a febre amarela, a peste bubônica e a varíola no início do século XX, e a vacinação obrigatória contra a varíola deflagrou a Revolta da Vacina (1904).","e":"As campanhas tinham moldes militares e se somaram às reformas urbanas de Pereira Passos, o que gerou forte resistência popular.","refs":[{"c":1,"p":9,"p2":9,"s":"s1-4"}],"a":"V"},{"id":"c1-04.2","t":"Carlos Chagas descreveu em 1909 o Trypanosoma cruzi, agente da doença que leva seu nome.","e":"Antes disso, em 1905, ele controlou a malária em Itatinga (SP).","refs":[{"c":1,"p":9,"p2":9,"s":"s1-4"},{"c":6,"p":137,"p2":137,"s":"s6-5"}],"a":"V"},{"id":"c1-04.3","t":"O Sistema Nacional de Vigilância Epidemiológica foi criado no Brasil logo após a Revolta da Vacina, em 1905.","e":"O SNVE surgiu em meados dos anos 1970, após as experiências da erradicação da varíola, do controle da poliomielite e da epidemia de doença meningocócica.","refs":[{"c":1,"p":9,"p2":9,"s":"s1-4"}],"a":"F"},{"id":"c1-04.4","t":"A ABRASCO foi criada em 1979, e o I Congresso Brasileiro de Epidemiologia (Campinas, 1990) teve como tema \"Epidemiologia e desigualdade social\".","e":"A VIII Conferência Nacional de Saúde (1986) é considerada o marco do SUS.","refs":[{"c":1,"p":10,"p2":10,"s":"s1-4"}],"a":"V"},{"id":"c1-04.5","t":"O Serviço Especial de Saúde Pública (SESP), criado em 1942, foi um programa exclusivamente nacional voltado às doenças crônicas nas capitais.","e":"O SESP nasceu de acordo com os EUA durante a 2ª Guerra, com foco em doenças como a malária na Amazônia.","refs":[{"c":1,"p":9,"p2":9,"s":"s1-4"}],"a":"F"}],"cap":1,"title":"Epidemiologia no Brasil"},{"id":"c2-01","src":"livro","type":"vf","items":[{"id":"c2-01.1","t":"Prevalência refere-se aos casos existentes num momento, enquanto incidência refere-se aos casos novos surgidos num intervalo de tempo.","e":"Prevalência é uma \"fotografia\" (medida estática). Incidência é dinâmica e exige observar a população em pelo menos dois momentos.","refs":[{"c":2,"p":14,"p2":15,"s":"s2-1"},{"c":2,"p":26,"p2":26,"s":"s2-5"}],"a":"V"},{"id":"c2-01.2","t":"Mortalidade, letalidade e sobrevida podem ser vistas como variações do conceito de incidência.","e":"Todas contam eventos novos (óbitos, por exemplo) num período, numa população sob risco.","refs":[{"c":2,"p":14,"p2":14,"s":"s2-1"},{"c":2,"p":24,"p2":24,"s":"s2-4"}],"a":"V"},{"id":"c2-01.3","t":"Para medir incidência basta um estudo transversal, pois ele identifica todos os casos existentes.","e":"O transversal mede prevalência. Para incidência é preciso saber quem não estava doente no início e acompanhar: estudos longitudinais (coorte, intervenção).","refs":[{"c":2,"p":15,"p2":15,"s":"s2-1"}],"a":"F"},{"id":"c2-01.4","t":"Em doenças agudas sem imunidade duradoura, pode-se contar todos os episódios de um mesmo indivíduo, o que o livro chama de \"incidência total\".","e":"Para doenças com imunidade permanente ou crônicas (diabetes), conta-se apenas o primeiro episódio.","refs":[{"c":2,"p":15,"p2":15,"s":"s2-1"}],"a":"V"},{"id":"c2-01.5","t":"Comparar o número absoluto de casos entre duas cidades é suficiente para dizer onde o risco é maior.","e":"Comparações exigem frequências relativas (taxas, proporções) referidas a tempo, lugar e população.","refs":[{"c":2,"p":14,"p2":14,"s":"s2-1"},{"c":2,"p":16,"p2":16,"s":"s2-2"}],"a":"F"}],"cap":2,"title":"Incidência e prevalência: conceitos"},{"id":"c2-02","src":"livro","type":"vf","items":[{"id":"c2-02.1","t":"A taxa de incidência (densidade de incidência) é o número de casos novos dividido pela soma do tempo em que cada pessoa esteve sob risco (pessoa-tempo).","e":"TI = I / PT. Também é chamada força de morbidade ou taxa por pessoa-tempo.","refs":[{"c":2,"p":17,"p2":17,"s":"s2-2"}],"a":"V"},{"id":"c2-02.2","t":"Uma pessoa acompanhada por 1 ano e duas pessoas acompanhadas por 6 meses cada contribuem, ambas, com 1 pessoa-ano.","e":"Pessoa-tempo soma as experiências individuais de exposição ao risco.","refs":[{"c":2,"p":17,"p2":17,"s":"s2-2"}],"a":"V"},{"id":"c2-02.3","t":"A taxa de incidência é adimensional e varia de 0 a 1.","e":"Ela tem dimensão de tempo⁻¹ e varia de 0 a infinito: o numerador não está contido no denominador. Ex.: 100 casos/pessoa-ano = 8,33 casos/pessoa-mês.","refs":[{"c":2,"p":21,"p2":21,"s":"s2-3"}],"a":"F"},{"id":"c2-02.4","t":"Quando não se conhece o tempo individual de cada participante, numa população dinâmica estável pode-se estimar a pessoa-tempo multiplicando o número de pessoas sob risco pela duração do período.","e":"PT = N' × Δt. Por isso a população estimada para 1º de julho é usada como aproximação das pessoas-ano de um ano.","refs":[{"c":2,"p":19,"p2":21,"s":"s2-2"}],"a":"V"},{"id":"c2-02.5","t":"Perdas de seguimento (mudança, recusa, morte por outra causa) devem ser excluídas do cálculo de pessoa-tempo.","e":"Quem é perdido contribui com o tempo observado até a perda (censura). Na falta da data exata, assume-se o meio do intervalo.","refs":[{"c":2,"p":18,"p2":18,"s":"s2-2"}],"a":"F"}],"cap":2,"title":"Taxa de incidência e pessoa-tempo"},{"id":"c2-03","src":"livro","type":"vf","items":[{"id":"c2-03.1","t":"Uma população fechada (coorte fixa) não admite novos membros após o início, embora possa perder membros.","e":"Exemplo do livro: os sobreviventes de um acidente nuclear.","refs":[{"c":2,"p":17,"p2":18,"s":"s2-2"}],"a":"V"},{"id":"c2-03.2","t":"Numa população dinâmica (aberta) há entradas (nascimentos, imigração, admissões) e saídas ao longo do período.","e":"Ela pode ser analisada como coorte fixa referindo todas as entradas a um t0 comum.","refs":[{"c":2,"p":18,"p2":18,"s":"s2-2"}],"a":"V"},{"id":"c2-03.3","t":"População estável (estacionária) é aquela em que cada indivíduo que sai é reposto, mantendo o tamanho e a estrutura.","e":"Esse pressuposto permite usar PT = N × Δt e o modelo P/(1−P) = TI × D.","refs":[{"c":2,"p":17,"p2":17,"s":"s2-2"},{"c":2,"p":27,"p2":28,"s":"s2-5"}],"a":"V"},{"id":"c2-03.4","t":"Em estudos de coorte, a perda de seguimento por histerectomia num estudo sobre câncer de útero não é considerada censura, pois a mulher continua viva.","e":"É censura: a mulher deixa de estar sob risco do evento estudado, mesmo viva.","refs":[{"c":2,"p":18,"p2":18,"s":"s2-2"}],"a":"F"},{"id":"c2-03.5","t":"Pessoas-tempo de 200 pessoas-ano só podem ser obtidas acompanhando 200 pessoas por exatamente um ano.","e":"200 pessoas-ano = 200 × 1 ano = 100 × 2 anos = 20 × 10 anos.","refs":[{"c":2,"p":20,"p2":20,"s":"s2-2"}],"a":"F"}],"cap":2,"title":"Populações fechadas, dinâmicas e estáveis"},{"id":"c2-04","src":"livro","type":"vf","items":[{"id":"c2-04.1","t":"A incidência acumulada é uma proporção: os casos novos no período divididos pelos não-doentes sob risco no início.","e":"IA = I / N'0. O numerador está incluído no denominador, varia de 0 a 1 e estima o risco médio do grupo.","refs":[{"c":2,"p":21,"p2":22,"s":"s2-3"}],"a":"V"},{"id":"c2-04.2","t":"Taxa de ataque, usada em surtos, é na verdade uma incidência acumulada (uma proporção), não uma taxa.","e":"Também é chamada proporção de incidência ou incidência cumulativa.","refs":[{"c":2,"p":22,"p2":22,"s":"s2-3"}],"a":"V"},{"id":"c2-04.3","t":"Uma IA não faz sentido sem a referência ao tempo: IA de 0,4 em 2-4 horas sugere intoxicação estafilocócica; em 7 dias, Salmonella typhi.","e":"O valor só se interpreta junto com o intervalo a que se refere.","refs":[{"c":2,"p":22,"p2":22,"s":"s2-3"}],"a":"V"},{"id":"c2-04.4","t":"Pelo método atuarial, as perdas de seguimento são somadas aos casos no numerador.","e":"No método atuarial, as perdas saem do denominador como metade: IA = I / (N'0 − W/2).","refs":[{"c":2,"p":22,"p2":22,"s":"s2-3"}],"a":"F"},{"id":"c2-04.5","t":"A IA de 3 anos pode ser obtida das IA anuais por 1 − (1 − IA1)(1 − IA2)(1 − IA3).","e":"Multiplicam-se as probabilidades de \"sobreviver\" sem adoecer em cada ano; o complemento é o risco acumulado.","refs":[{"c":2,"p":22,"p2":23,"s":"s2-3"}],"a":"V"}],"cap":2,"title":"Incidência acumulada (risco)"},{"id":"c2-05","src":"livro","type":"vf","items":[{"id":"c2-05.1","t":"A sobrevida é o complemento da incidência acumulada: S = 1 − IA.","e":"Se a IA de um período é 0,11, a probabilidade de terminar o período sem o evento é 0,89.","refs":[{"c":2,"p":23,"p2":23,"s":"s2-3"}],"a":"V"},{"id":"c2-05.2","t":"A taxa de dano (hazard rate), ou força de mortalidade, é a taxa instantânea de ocorrência do evento entre os que ainda não o tiveram.","e":"É a base das tábuas de vida e da análise de sobrevida.","refs":[{"c":2,"p":24,"p2":24,"s":"s2-4"}],"a":"V"},{"id":"c2-05.3","t":"A odds de incidência é calculada como IA dividida por (1 + IA).","e":"A odds de incidência é IA/(1 − IA). Com IA = 0,11, a odds é 0,12 (cerca de 1 caso para 8 sadios).","refs":[{"c":2,"p":24,"p2":24,"s":"s2-4"}],"a":"F"},{"id":"c2-05.4","t":"A odds (chance) é a medida de frequência mais usada nos estudos epidemiológicos.","e":"Como medida de frequência a odds é pouco usada. Muito usada é a razão de chances (odds ratio), uma medida de associação.","refs":[{"c":2,"p":24,"p2":24,"s":"s2-4"},{"c":2,"p":27,"p2":27,"s":"s2-5"}],"a":"F"},{"id":"c2-05.5","t":"A chance de prevalência é P/(1 − P). Para diabetes com prevalência de 2,7% (30-39 anos), ela é cerca de 0,028, ou 1 diabético para cada 36 não-diabéticos.","e":"0,027/0,973 ≈ 0,028.","refs":[{"c":2,"p":26,"p2":27,"s":"s2-5"}],"a":"V"}],"cap":2,"title":"Sobrevida, hazard e odds"},{"id":"c2-06","src":"livro","type":"vf","items":[{"id":"c2-06.1","t":"A mortalidade por uma causa é uma forma de incidência em que o evento é o óbito, e o denominador inclui toda a população (doentes e não-doentes).","e":"Todos estão sob risco de morrer, inclusive os já doentes.","refs":[{"c":2,"p":25,"p2":25,"s":"s2-5"}],"a":"V"},{"id":"c2-06.2","t":"Letalidade é a mortalidade restrita a quem tem a doença; pode ser expressa como proporção ou como taxa por pessoa-tempo desde o diagnóstico.","e":"Também precisa de referência temporal: 50% no primeiro ano é diferente de 50% na primeira semana.","refs":[{"c":2,"p":25,"p2":25,"s":"s2-5"}],"a":"V"},{"id":"c2-06.3","t":"Uma doença muito letal sempre produz alta mortalidade na população.","e":"Mortalidade depende de incidência e letalidade. Doença rara e letal (raiva humana, letalidade ~100%) tem mortalidade baixa.","refs":[{"c":2,"p":25,"p2":25,"s":"s2-5"}],"a":"F"},{"id":"c2-06.4","t":"\"Mortalidade por x\" refere-se a x como causa básica do óbito; \"mortalidade com x\" inclui x como causa associada ou contribuinte.","e":"Causa básica (OMS) é a doença ou lesão que iniciou a cadeia de eventos, ou as circunstâncias do acidente ou violência.","refs":[{"c":2,"p":24,"p2":24,"s":"s2-4"},{"c":3,"p":43,"p2":43,"s":"s3-4"}],"a":"V"},{"id":"c2-06.5","t":"A mortalidade geral se refere apenas aos óbitos por causas naturais, excluindo as causas externas.","e":"Mortalidade geral inclui óbitos por todas as causas.","refs":[{"c":2,"p":24,"p2":25,"s":"s2-4"}],"a":"F"}],"cap":2,"title":"Mortalidade e letalidade"},{"id":"c2-07","src":"livro","type":"vf","items":[{"id":"c2-07.1","t":"Chamar a prevalência de \"taxa de prevalência\" é tecnicamente incorreto, pois se trata de uma proporção.","e":"Prevalência pontual = casos existentes / população, num dado momento. É adimensional, de 0 a 1.","refs":[{"c":2,"p":26,"p2":26,"s":"s2-5"}],"a":"V"},{"id":"c2-07.2","t":"A prevalência de período soma os casos existentes no início com os casos novos do período. Por ter significado pouco claro, é pouco usada.","e":"PP = (C0 + I)/N. No exemplo de TB, 90 casos em 1º de janeiro + 70 novos dão 160.","refs":[{"c":2,"p":28,"p2":29,"s":"s2-5"}],"a":"V"},{"id":"c2-07.3","t":"Para doenças crônicas incuráveis, a prevalência \"de toda a vida\" é igual à prevalência pontual.","e":"Já em doenças remitentes ou curáveis sem imunidade, a de toda a vida inclui os curados e é maior.","refs":[{"c":2,"p":29,"p2":29,"s":"s2-5"}],"a":"V"},{"id":"c2-07.4","t":"A soroprevalência indica apenas infecções atuais.","e":"Anticorpos indicam infecção atual ou passada (ou vacinação). Ex.: 98,9% de soropositividade para sarampo em Niterói após vacinação em massa.","refs":[{"c":2,"p":29,"p2":29,"s":"s2-5"}],"a":"F"},{"id":"c2-07.5","t":"Estudos de prevalência são úteis para planejar serviços (recursos, leitos), mas em geral são inadequados para estudar etiologia.","e":"A prevalência mistura fatores de risco com fatores de sobrevida (duração) e não estabelece precedência temporal.","refs":[{"c":2,"p":29,"p2":29,"s":"s2-5"}],"a":"V"}],"cap":2,"title":"Prevalência: tipos e interpretação"},{"id":"c2-08","src":"livro","type":"vf","items":[{"id":"c2-08.1","t":"Doenças agudas com alta incidência e curta duração, como a dengue, tendem a ter prevalência baixa.","e":"Os casos se resolvem rápido (cura ou óbito) e não se acumulam.","refs":[{"c":2,"p":27,"p2":27,"s":"s2-5"}],"a":"V"},{"id":"c2-08.2","t":"Doenças crônicas com baixa incidência e longa duração, como a hipertensão, tendem a ter prevalência alta.","e":"Os casos se acumulam ao longo dos anos.","refs":[{"c":2,"p":27,"p2":27,"s":"s2-5"}],"a":"V"},{"id":"c2-08.3","t":"A emigração de pessoas doentes aumenta a prevalência na área de origem.","e":"Saída de doentes (ou entrada de sadios) reduz a prevalência; entrada de doentes (ou saída de sadios) a aumenta.","refs":[{"c":2,"p":27,"p2":27,"s":"s2-5"}],"a":"F"},{"id":"c2-08.4","t":"Em população estável e prevalência baixa, P ≈ TI × D. Com incidência de 1% ao ano e duração de 15 anos, a prevalência esperada é de cerca de 15%.","e":"De forma exata, a chance de prevalência P/(1 − P) = TI × D.","refs":[{"c":2,"p":28,"p2":28,"s":"s2-5"}],"a":"V"},{"id":"c2-08.5","t":"Em doença incurável, a taxa de \"saída\" do estado doente é dada pela letalidade, e 1/(taxa de saída) corresponde à duração média.","e":"Sem migração, TI' (taxa de cura ou óbito) = 1/D.","refs":[{"c":2,"p":27,"p2":28,"s":"s2-5"}],"a":"V"}],"cap":2,"title":"Determinantes da prevalência"},{"id":"c2-09","src":"livro","type":"choice","ctx":["Uma coorte começa com 20 homens sem a doença. No 1º ano não há casos nem perdas. No 2º ano ocorrem 2 casos e 2 perdas de seguimento. No 3º ano, dos 13 que restaram em observação, 1 adoece e não há perdas."],"items":[{"id":"c2-09.1","t":"Pelo método atuarial, qual é a incidência acumulada do 2º ano (arredondada)?","e":"No início do 2º ano havia 20 sob risco. IA2 = 2 / (20 − 2/2) = 2/19 ≈ 0,11.","refs":[{"c":2,"p":22,"p2":22,"s":"s2-3"}],"a":1},{"id":"c2-09.2","t":"Qual é a incidência acumulada dos 3 anos, sabendo que IA1 = 0, IA2 ≈ 0,11 e IA3 ≈ 0,08?","e":"IA(3 anos) = 1 − (1 − 0)(1 − 0,11)(1 − 0,08) = 1 − 0,89 × 0,92 ≈ 0,18.","refs":[{"c":2,"p":22,"p2":23,"s":"s2-3"}],"a":2}],"cap":2,"title":"Cálculo: coorte com perdas","opts":["0,10","0,11","0,18","0,25","0,08"]},{"id":"c2-10","src":"livro","type":"choice","ctx":["Num estudo, 4 infartos ocorreram em 95,5 pessoas-ano de observação de homens de 50-59 anos."],"items":[{"id":"c2-10.1","t":"Qual é a taxa de incidência aproximada?","e":"TI = 4 / 95,5 ≈ 0,042 caso por pessoa-ano (cerca de 4 casos por 100 pessoas-ano).","refs":[{"c":2,"p":19,"p2":19,"s":"s2-2"}],"a":0}],"cap":2,"title":"Cálculo: TI e IA","opts":["0,04 caso por pessoa-ano","4 casos por pessoa-ano","0,4 caso por pessoa-ano","0,02 caso por pessoa-ano","0,24 caso por pessoa-ano"]},{"id":"c3-01","src":"livro","type":"vf","items":[{"id":"c3-01.1","t":"Um indicador de saúde busca medir uma característica que não pode ser observada diretamente, como o nível de saúde de uma população.","e":"Exemplos: a esperança de vida ao nascer e a mortalidade infantil, para populações; a pressão arterial e o Apgar, para indivíduos.","refs":[{"c":3,"p":31,"p2":31,"s":"s3-1"}],"a":"V"},{"id":"c3-01.2","t":"Paradoxalmente, a maioria dos indicadores de saúde mede a ausência de saúde (doença, morte).","e":"A definição da OMS (completo bem-estar) é ampla e difícil de medir, então mede-se pelo \"lado negativo\" por facilidade operacional.","refs":[{"c":3,"p":31,"p2":32,"s":"s3-1"},{"c":3,"p":79,"p2":79,"s":"s3-13"}],"a":"V"},{"id":"c3-01.3","t":"Disponibilidade de dados, uniformidade, simplicidade, sinteticidade e poder discriminatório estão entre os requisitos de um bom indicador.","e":"Também importam a validade (medir o que se propõe), relevância, custo-efetividade e ética.","refs":[{"c":3,"p":33,"p2":33,"s":"s3-1"}],"a":"V"},{"id":"c3-01.4","t":"Índice e indicador são sinônimos: ambos medem uma única dimensão.","e":"O indicador mede um aspecto (ex. coeficiente de mortalidade). O índice sintetiza várias dimensões (ex. IDH, Apgar).","refs":[{"c":3,"p":33,"p2":34,"s":"s3-1"}],"a":"F"},{"id":"c3-01.5","t":"O IDH combina educação, longevidade (esperança de vida ao nascer) e renda (PIB per capita ajustado), variando de 0 a 1.","e":"Abaixo de 0,5 é baixo; de 0,5 a 0,8, médio; acima de 0,8, alto.","refs":[{"c":3,"p":34,"p2":34,"s":"s3-1"}],"a":"V"}],"cap":3,"title":"Indicadores: conceito e requisitos"},{"id":"c3-02","src":"livro","type":"vf","items":[{"id":"c3-02.1","t":"Na proporção, o numerador é um subconjunto do denominador, como na mortalidade proporcional.","e":"A prevalência também é uma proporção.","refs":[{"c":3,"p":34,"p2":34,"s":"s3-1"}],"a":"V"},{"id":"c3-02.2","t":"Nos coeficientes (taxas) populacionais, a população no meio do período aproxima o total de pessoas-tempo, supondo distribuição homogênea de nascimentos, mortes e migrações.","e":"Por isso a população de 1º de julho é usada no denominador.","refs":[{"c":3,"p":34,"p2":34,"s":"s3-1"}],"a":"V"},{"id":"c3-02.3","t":"Os dados por local de residência estimam o risco da população; os por local de ocorrência servem para avaliar serviços.","e":"A análise por ocorrência mistura pacientes de fora atendidos na cidade (\"invasão\" de óbitos).","refs":[{"c":3,"p":35,"p2":35,"s":"s3-2"},{"c":3,"p":37,"p2":38,"s":"s3-2"}],"a":"V"},{"id":"c3-02.4","t":"A base de multiplicação (100, 1.000, 100.000) é definida por lei e não pode ser alterada.","e":"A base é arbitrária e deve ser explicitada.","refs":[{"c":3,"p":35,"p2":35,"s":"s3-2"}],"a":"F"},{"id":"c3-02.5","t":"Numa transição demográfica com queda da mortalidade e da fecundidade, o foco dos indicadores passou da mortalidade para a morbidade, a capacidade funcional e a qualidade de vida.","e":"É a evolução histórica dos indicadores descrita no capítulo.","refs":[{"c":3,"p":32,"p2":32,"s":"s3-1"}],"a":"V"}],"cap":3,"title":"Proporções, coeficientes e local de referência"},{"id":"c3-03","src":"livro","type":"vf","items":[{"id":"c3-03.1","t":"O SIM, implantado pelo Ministério da Saúde em 1975/76, usa diretamente a Declaração de Óbito, inclusive dos óbitos fetais.","e":"A causa básica é codificada pela CID (CID-10 desde 1996).","refs":[{"c":3,"p":35,"p2":36,"s":"s3-2"},{"c":5,"p":111,"p2":111,"s":"s5-3"}],"a":"V"},{"id":"c3-03.2","t":"O SINASC, criado em 1990, usa a Declaração de Nascido Vivo, com dados como peso ao nascer, Apgar, idade gestacional e tipo de parto.","e":"A DNV é preenchida pelo estabelecimento de saúde (partos domiciliares, no cartório).","refs":[{"c":3,"p":36,"p2":36,"s":"s3-2"}],"a":"V"},{"id":"c3-03.3","t":"A Declaração de Óbito pode ser emitida por qualquer servidor público municipal.","e":"A DO deve ser assinada por médico, ou, na falta dele, por duas testemunhas qualificadas. É impressa e distribuída pelo Ministério da Saúde.","refs":[{"c":3,"p":35,"p2":35,"s":"s3-2"},{"c":5,"p":111,"p2":111,"s":"s5-3"}],"a":"F"},{"id":"c3-03.4","t":"No Brasil, o sepultamento só pode ocorrer com a certidão de óbito, que exige a DO (Lei dos Registros Públicos, 1973).","e":"Mesmo assim existem sepultamentos clandestinos, que causam sub-registro.","refs":[{"c":3,"p":35,"p2":35,"s":"s3-2"},{"c":3,"p":54,"p2":54,"s":"s3-7"}],"a":"V"},{"id":"c3-03.5","t":"O SIH/SUS foi concebido com lógica epidemiológica para medir a morbidade de toda a população.","e":"O SIH foi criado para pagar internações. Cobre apenas hospitais públicos e conveniados (~70%) e é influenciado pela oferta de leitos.","refs":[{"c":3,"p":69,"p2":69,"s":"s3-11"},{"c":5,"p":111,"p2":112,"s":"s5-3"}],"a":"F"}],"cap":3,"title":"Fontes: SIM, SINASC e registro civil"},{"id":"c3-04","src":"livro","type":"vf","items":[{"id":"c3-04.1","t":"O CGM é o número de óbitos da área no período dividido pela população no meio do período, multiplicado por 1.000.","e":"Brasil 2000: 946.686 / 169.799.170 ≈ 5,6 por 1.000.","refs":[{"c":3,"p":36,"p2":37,"s":"s3-2"}],"a":"V"},{"id":"c3-04.2","t":"O sub-registro de óbitos subestima o CGM; a \"invasão\" de óbitos (residentes de outras áreas) o superestima.","e":"Analisar por residência reduz os problemas de evasão e invasão.","refs":[{"c":3,"p":37,"p2":38,"s":"s3-2"}],"a":"V"},{"id":"c3-04.3","t":"Uma subestimação da população (denominador) leva a subestimar o CGM.","e":"Com o denominador menor, o CGM fica superestimado.","refs":[{"c":3,"p":38,"p2":38,"s":"s3-3"}],"a":"F"},{"id":"c3-04.4","t":"Valores de CGM abaixo de 6 por 1.000 sugerem, em geral, problemas de sub-registro.","e":"Espera-se algo entre 6 e 10 por 1.000.","refs":[{"c":3,"p":38,"p2":38,"s":"s3-3"}],"a":"V"},{"id":"c3-04.5","t":"O CGM é uma média ponderada dos coeficientes específicos por idade, com pesos dados pela proporção da população em cada faixa etária.","e":"Por isso depende da estrutura etária: um país jovem pode ter CGM menor sem ter melhor saúde.","refs":[{"c":3,"p":38,"p2":38,"s":"s3-3"}],"a":"V"}],"cap":3,"title":"Coeficiente geral de mortalidade"},{"id":"c3-05","src":"livro","type":"vf","items":[{"id":"c3-05.1","t":"No método direto, aplicam-se os coeficientes específicos por idade da população estudada a uma população-padrão, obtendo óbitos esperados.","e":"A soma dos óbitos esperados dividida pela população-padrão dá o coeficiente padronizado.","refs":[{"c":3,"p":38,"p2":39,"s":"s3-3"}],"a":"V"},{"id":"c3-05.2","t":"O método indireto é indicado quando não se conhece a distribuição dos óbitos por idade, ou quando os contingentes são pequenos e os coeficientes específicos, instáveis.","e":"Aplicam-se os coeficientes do padrão à estrutura da população estudada.","refs":[{"c":3,"p":41,"p2":41,"s":"s3-3"}],"a":"V"},{"id":"c3-05.3","t":"A razão de mortalidade padronizada (RMP/SMR) divide os óbitos observados pelos esperados. Brasil × Inglaterra deu 1,51: 151 óbitos para cada 100 esperados.","e":"A RMP também é usada como medida de associação.","refs":[{"c":3,"p":41,"p2":41,"s":"s3-3"}],"a":"V"},{"id":"c3-05.4","t":"O coeficiente padronizado corrige o valor verdadeiro da mortalidade da população.","e":"Ele é hipotético e serve só para comparar. Não \"corrige\", apenas controla a interferência da estrutura etária.","refs":[{"c":3,"p":40,"p2":40,"s":"s3-3"}],"a":"F"},{"id":"c3-05.5","t":"O Brasil tinha CGM bruto menor que o da Inglaterra e Gales, mas, padronizado pela estrutura inglesa, o seu passou a ser maior (12,8 contra 10,1 por 1.000).","e":"Os coeficientes específicos do Brasil eram maiores em todas as idades; a população jovem \"escondia\" isso no bruto.","refs":[{"c":3,"p":39,"p2":40,"s":"s3-3"}],"a":"V"}],"cap":3,"title":"Padronização direta e indireta"},{"id":"c3-06","src":"livro","type":"vf","items":[{"id":"c3-06.1","t":"A causa básica de morte é a doença ou lesão que iniciou a cadeia de acontecimentos que levou à morte, ou as circunstâncias do acidente ou violência.","e":"É a causa usada nas estatísticas oficiais (OMS). As demais são causas associadas.","refs":[{"c":3,"p":43,"p2":43,"s":"s3-4"}],"a":"V"},{"id":"c3-06.2","t":"A mortalidade proporcional por causa não precisa de estimativas populacionais.","e":"MP = óbitos por uma causa / total de óbitos × 100.","refs":[{"c":3,"p":43,"p2":43,"s":"s3-4"}],"a":"V"},{"id":"c3-06.3","t":"Uma queda da mortalidade proporcional por uma causa implica, necessariamente, queda do número de óbitos por essa causa.","e":"No Sul do Brasil a MP por doenças do aparelho circulatório caiu (34,7% → 33,1%) enquanto os óbitos aumentaram (47.184 → 50.612), porque outras causas cresceram mais.","refs":[{"c":3,"p":44,"p2":44,"s":"s3-4"}],"a":"F"},{"id":"c3-06.4","t":"A Aids passou a ser classificada no capítulo de doenças infecciosas e parasitárias (cap. I) na CID-10, o que aumentou a mortalidade registrada por DIP a partir de 1996.","e":"Na CID-9 ela ficava entre os transtornos imunitários.","refs":[{"c":3,"p":44,"p2":44,"s":"s3-4"},{"c":3,"p":46,"p2":46,"s":"s3-5"}],"a":"V"},{"id":"c3-06.5","t":"Causas externas (agressões, acidentes) exigem padronização por idade e por sexo, pois afetam sobretudo homens jovens.","e":"No RJ, 2003-04, a taxa por causas externas foi 179,8/100 mil nos homens contra 30,9 nas mulheres.","refs":[{"c":3,"p":42,"p2":42,"s":"s3-4"},{"c":3,"p":45,"p2":45,"s":"s3-4"}],"a":"V"}],"cap":3,"title":"Mortalidade por causas e CID"},{"id":"c3-07","src":"livro","type":"vf","items":[{"id":"c3-07.1","t":"Morte materna é a que ocorre durante a gestação ou até 42 dias após o seu término, por causa relacionada ou agravada pela gravidez, excluídas as causas acidentais ou incidentais.","e":"A morte materna tardia ocorre depois de 42 dias e antes de 1 ano (O96).","refs":[{"c":3,"p":46,"p2":46,"s":"s3-5"}],"a":"V"},{"id":"c3-07.2","t":"A razão de mortalidade materna usa os nascidos vivos no denominador (× 100.000).","e":"Os nascidos vivos aproximam o número de gestantes expostas.","refs":[{"c":3,"p":47,"p2":47,"s":"s3-5"}],"a":"V"},{"id":"c3-07.3","t":"Causas obstétricas diretas (ex.: toxemia, descolamento de placenta) predominam onde a mortalidade materna é alta; com sua queda, ganham peso as indiretas.","e":"Indiretas são doenças preexistentes agravadas pela gravidez (diabetes, cardiopatias).","refs":[{"c":3,"p":46,"p2":47,"s":"s3-5"}],"a":"V"},{"id":"c3-07.4","t":"A Declaração de Óbito tem alta sensibilidade para identificar mortes maternas.","e":"A DO tem baixa sensibilidade (há muito sub-registro), embora seu valor preditivo positivo seja alto. Por isso existe a investigação de óbitos de mulheres em idade fértil.","refs":[{"c":3,"p":47,"p2":48,"s":"s3-5"}],"a":"F"},{"id":"c3-07.5","t":"A morte materna é um evento sentinela, pois a maioria é evitável e reflete a qualidade da atenção à saúde da mulher.","e":"O nível aceitável (OMS/Unicef) seria de 10 a 20 por 100.000 nascidos vivos.","refs":[{"c":3,"p":47,"p2":48,"s":"s3-5"}],"a":"V"}],"cap":3,"title":"Mortalidade materna"},{"id":"c3-08","src":"livro","type":"vf","items":[{"id":"c3-08.1","t":"O componente neonatal (0-27 dias) reflete sobretudo as condições da gestação, do parto e da assistência perinatal (causas endógenas).","e":"O neonatal se divide em precoce (0-6 dias) e tardio (7-27 dias).","refs":[{"c":3,"p":51,"p2":51,"s":"s3-7"}],"a":"V"},{"id":"c3-08.2","t":"O componente pós-neonatal (28 dias a menos de 1 ano) está mais ligado a fatores ambientais e sociais: diarreias, infecções respiratórias e imunopreveníveis.","e":"São causas exógenas, sensíveis a saneamento, TRO e vacinação.","refs":[{"c":3,"p":51,"p2":51,"s":"s3-7"}],"a":"V"},{"id":"c3-08.3","t":"Quando a mortalidade infantil é alta, predomina o componente pós-neonatal; com a queda, o neonatal passa a predominar.","e":"No Brasil o pós-neonatal era 57% dos óbitos infantis em 1979-81 e 47,1% em 1993-95.","refs":[{"c":3,"p":52,"p2":53,"s":"s3-7"}],"a":"V"},{"id":"c3-08.4","t":"Pela classificação citada no livro, uma TMI de 25 por 1.000 nascidos vivos é considerada baixa.","e":"Menos de 20 é baixa, de 20 a 49 é intermediária e 50 ou mais é elevada. O Brasil tinha 25,9 em 2004 (intermediária).","refs":[{"c":3,"p":52,"p2":52,"s":"s3-7"}],"a":"F"},{"id":"c3-08.5","t":"A taxa de mortalidade infantil é imune a intervenções pontuais; ela só cai com mudanças estruturais das condições de vida.","e":"Uma limitação apontada é que intervenções pontuais (ex.: TRO) podem reduzi-la mesmo sem melhora geral das condições de vida.","refs":[{"c":3,"p":54,"p2":54,"s":"s3-7"}],"a":"F"}],"cap":3,"title":"Mortalidade infantil e seus componentes"},{"id":"c3-09","src":"livro","type":"vf","items":[{"id":"c3-09.1","t":"Desde a CID-10 é obrigatório declarar os óbitos fetais com 20 semanas ou mais de gestação, ou peso igual ou superior a 500 g, ou estatura de 25 cm ou mais.","e":"Abaixo desses limites a declaração é facultativa.","refs":[{"c":3,"p":55,"p2":55,"s":"s3-7"}],"a":"V"},{"id":"c3-09.2","t":"O período perinatal vai de 22 semanas completas de gestação até 7 dias completos após o nascimento.","e":"TMP = (natimortos + óbitos neonatais precoces) / (natimortos + nascidos vivos) × 1.000.","refs":[{"c":3,"p":56,"p2":56,"s":"s3-7"}],"a":"V"},{"id":"c3-09.3","t":"A mortalidade perinatal não é afetada por erros de classificação entre natimorto e nascido vivo que morre logo após o parto.","e":"As duas categorias entram no numerador.","refs":[{"c":3,"p":56,"p2":56,"s":"s3-7"}],"a":"V"},{"id":"c3-09.4","t":"Mortalidade perinatal e mortalidade por afecções perinatais (cap. XVI da CID-10) são a mesma coisa.","e":"São conceitos diferentes. Uma parte dos óbitos por afecções perinatais ocorre depois da primeira semana.","refs":[{"c":3,"p":56,"p2":56,"s":"s3-7"}],"a":"F"},{"id":"c3-09.5","t":"A razão de mortalidade fetal (óbitos fetais / nascidos vivos) é, na verdade, uma medida de chance (odds).","e":"O coeficiente de mortalidade fetal usa natimortos + nascidos vivos no denominador.","refs":[{"c":3,"p":55,"p2":56,"s":"s3-7"}],"a":"V"}],"cap":3,"title":"Mortalidade fetal e perinatal"},{"id":"c3-10","src":"livro","type":"vf","items":[{"id":"c3-10.1","t":"O indicador de Swaroop-Uemura é a proporção de óbitos de pessoas com 50 anos ou mais no total de óbitos. Valores altos indicam melhores condições de saúde.","e":"Ele é o contrário da proporção de óbitos de menores de 1 ano.","refs":[{"c":3,"p":57,"p2":57,"s":"s3-8"}],"a":"V"},{"id":"c3-10.2","t":"Pela classificação do indicador de Swaroop-Uemura, 75% ou mais corresponde ao 1º nível (países desenvolvidos).","e":"2º nível: 50-74,9%; 3º nível: 25-49,9%; 4º nível: menos de 25%.","refs":[{"c":3,"p":57,"p2":58,"s":"s3-8"}],"a":"V"},{"id":"c3-10.3","t":"O sub-registro de óbitos infantis tende a subestimar o indicador de Swaroop-Uemura.","e":"Faltando óbitos infantis no total, a proporção de 50+ fica maior: o indicador é superestimado.","refs":[{"c":3,"p":59,"p2":59,"s":"s3-8"}],"a":"F"},{"id":"c3-10.4","t":"As curvas de mortalidade proporcional de Nelson de Moraes usam as faixas: menores de 1 ano, 1-4, 5-19, 20-49 e 50 anos ou mais.","e":"O formato da curva (\"N\", \"L\", \"U\", \"J\") classifica o nível de saúde.","refs":[{"c":3,"p":59,"p2":60,"s":"s3-8"}],"a":"V"},{"id":"c3-10.5","t":"Uma curva em \"J\", com quase todos os óbitos em idades avançadas, indica nível de saúde elevado.","e":"A curva em \"L\", com predomínio de óbitos infantis e pré-escolares, indica nível baixo.","refs":[{"c":3,"p":60,"p2":60,"s":"s3-9"}],"a":"V"}],"cap":3,"title":"Swaroop-Uemura e curvas de Nelson de Moraes"},{"id":"c3-11","src":"livro","type":"vf","items":[{"id":"c3-11.1","t":"Em populações humanas, a esperança de vida é calculada por tábua de vida de coorte sintética: aplicam-se as probabilidades de morte por idade de um período a uma coorte hipotética.","e":"Seguir uma geração real exigiria mais de 100 anos de dados.","refs":[{"c":3,"p":61,"p2":61,"s":"s3-9"}],"a":"V"},{"id":"c3-11.2","t":"A esperança de vida ao nascer não é influenciada pela estrutura etária da população, e por isso pode ser comparada diretamente.","e":"Não precisa de padronização.","refs":[{"c":3,"p":62,"p2":62,"s":"s3-9"}],"a":"V"},{"id":"c3-11.3","t":"Em contextos de alta mortalidade infantil, a esperança de vida aos 1 ano (e1) pode ser maior do que ao nascer (e0).","e":"Quem sobrevive ao primeiro ano escapa do maior risco.","refs":[{"c":3,"p":62,"p2":62,"s":"s3-9"}],"a":"V"},{"id":"c3-11.4","t":"Reduções da mortalidade em idades avançadas produzem os maiores ganhos de esperança de vida ao nascer.","e":"Os maiores ganhos vêm da redução de óbitos precoces, sobretudo no 1º ano de vida.","refs":[{"c":3,"p":62,"p2":63,"s":"s3-9"}],"a":"F"},{"id":"c3-11.5","t":"Tábuas de vida de múltiplo decremento permitem estimar o ganho de esperança de vida se uma causa de morte fosse eliminada.","e":"No RJ (1996), eliminar as doenças cardiovasculares daria os maiores ganhos; nos homens, eliminar as agressões daria mais que eliminar as neoplasias.","refs":[{"c":3,"p":63,"p2":64,"s":"s3-9"}],"a":"V"}],"cap":3,"title":"Esperança de vida e tábuas de vida"},{"id":"c3-12","src":"livro","type":"vf","items":[{"id":"c3-12.1","t":"O APVP é a soma, para cada óbito antes da idade-limite L, da diferença entre L e a idade do óbito.","e":"APVP = Σ dx(L − x). Óbitos com idade de L ou mais têm peso zero.","refs":[{"c":3,"p":65,"p2":65,"s":"s3-10"}],"a":"V"},{"id":"c3-12.2","t":"O APVP valoriza a transcendência das mortes precoces. Dempsey o criou para mostrar a importância da tuberculose, subestimada pelos coeficientes de mortalidade.","e":"Critérios de prioridade: magnitude (quantidade) e transcendência (valor social).","refs":[{"c":3,"p":64,"p2":64,"s":"s3-10"}],"a":"V"},{"id":"c3-12.3","t":"Com L = 70, a morte de uma criança de 2 anos equivale em APVP à de dois adultos de 36 anos.","e":"70 − 2 = 68 = 2 × (70 − 36).","refs":[{"c":3,"p":65,"p2":65,"s":"s3-10"}],"a":"V"},{"id":"c3-12.4","t":"Quanto maior a idade-limite L escolhida, mais destaque o APVP dá às mortes prematuras.","e":"É o contrário: um L baixo destaca as mortes prematuras; um L alto inclui mais óbitos.","refs":[{"c":3,"p":65,"p2":65,"s":"s3-10"}],"a":"F"},{"id":"c3-12.5","t":"No exemplo de Santa Catarina, os acidentes de trânsito ficaram em 1º lugar em APVP, embora fossem a 2ª causa em número de óbitos.","e":"Causas de jovens (acidentes, homicídios, anomalias, perinatais) sobem no ranking; neoplasias e AVC descem.","refs":[{"c":3,"p":65,"p2":67,"s":"s3-10"}],"a":"V"}],"cap":3,"title":"Anos potenciais de vida perdidos"},{"id":"c3-13","src":"livro","type":"vf","items":[{"id":"c3-13.1","t":"Na terminologia do livro, doença (disease) é o plano do organismo, enfermidade (illness) é a percepção do indivíduo e anormalidade (sickness) é o plano social.","e":"As três dimensões não coincidem: alguém pode ter doença pré-clínica sem se sentir enfermo.","refs":[{"c":3,"p":67,"p2":68,"s":"s3-11"}],"a":"V"},{"id":"c3-13.2","t":"A CIDID (OMS) seguia a sequência linear doença → deficiência → incapacidade → desvantagem.","e":"Ela foi revista e substituída pela CIF (2001).","refs":[{"c":3,"p":70,"p2":70,"s":"s3-11"}],"a":"V"},{"id":"c3-13.3","t":"A CIF (Classificação Internacional de Funcionalidade) é complementar à CID-10 e inclui fatores ambientais como facilitadores ou barreiras.","e":"Funcionalidade abrange estruturas e funções do corpo, atividade e participação.","refs":[{"c":3,"p":70,"p2":70,"s":"s3-11"}],"a":"V"},{"id":"c3-13.4","t":"O WHOQOL-Bref e o SF-36 são instrumentos específicos para pacientes com câncer.","e":"O WHOQOL-Bref (domínios físico, psicológico, relações sociais e meio ambiente) e o SF-36 são instrumentos genéricos de qualidade de vida.","refs":[{"c":3,"p":71,"p2":71,"s":"s3-11"}],"a":"F"},{"id":"c3-13.5","t":"As atividades instrumentais da vida diária (AIVD), como fazer compras e controlar finanças, captam incapacidades menos graves que as atividades básicas (banhar-se, alimentar-se).","e":"Por isso as escalas AIVD servem melhor para a população geral.","refs":[{"c":3,"p":72,"p2":72,"s":"s3-11"}],"a":"V"}],"cap":3,"title":"Morbidade, CIF e qualidade de vida"},{"id":"c3-14","src":"livro","type":"vf","items":[{"id":"c3-14.1","t":"O DALY soma os anos de vida perdidos por morte prematura (YLL) e os anos vividos com incapacidade (YLD).","e":"DALY = YLL + YLD. Ele é usado nos estudos de carga de doença (Banco Mundial/OMS).","refs":[{"c":3,"p":75,"p2":76,"s":"s3-12"}],"a":"V"},{"id":"c3-14.2","t":"O QALY expressa ganhos de vida com qualidade; o DALY expressa perdas.","e":"O QALY vem da tradição utilitarista (custo-utilidade).","refs":[{"c":3,"p":70,"p2":70,"s":"s3-11"},{"c":3,"p":75,"p2":75,"s":"s3-12"}],"a":"V"},{"id":"c3-14.3","t":"No estudo de carga de doença do Brasil (1998), as condições neuropsiquiátricas ficaram em 1º lugar em DALY, principalmente pelos anos vividos com incapacidade.","e":"Em mortalidade (YLL) elas eram apenas a 12ª causa. Só os dados de óbito subestimariam essa carga.","refs":[{"c":3,"p":77,"p2":77,"s":"s3-12"}],"a":"V"},{"id":"c3-14.4","t":"O DALY considera características socioeconômicas, de modo que a mesma doença tem pesos diferentes para ricos e pobres.","e":"Por pressuposto, só sexo e idade entram, para garantir comparabilidade: a mesma condição tem o mesmo peso em qualquer população.","refs":[{"c":3,"p":75,"p2":75,"s":"s3-12"}],"a":"F"},{"id":"c3-14.5","t":"O método de Sullivan combina a tábua de vida com a prevalência de incapacidade (de inquéritos) para estimar a esperança de vida livre de incapacidade.","e":"No Brasil, as mulheres vivem mais e mais anos sem incapacidade, mas os homens passam proporcionalmente mais tempo sem incapacidade.","refs":[{"c":3,"p":74,"p2":74,"s":"s3-12"}],"a":"V"}],"cap":3,"title":"Medidas-resumo: DALY e esperança de vida livre de incapacidade"},{"id":"c4-01","src":"livro","type":"vf","items":[{"id":"c4-01.1","t":"A epidemiologia descritiva organiza a ocorrência das doenças segundo pessoa (quem), lugar (onde) e tempo (quando).","e":"Essas três perguntas ajudam a gerar hipóteses, planejar e orientar a clínica.","refs":[{"c":4,"p":83,"p2":83,"s":"s4-1"}],"a":"V"},{"id":"c4-01.2","t":"O mapa de John Snow (1854) mostrou associação espacial entre mortes por cólera e uma bomba de água, sem que o agente fosse conhecido.","e":"A distribuição espacial dá pistas etiológicas, mas nem sempre prova nexo causal.","refs":[{"c":4,"p":84,"p2":84,"s":"s4-1"}],"a":"V"},{"id":"c4-01.3","t":"Os estudos de migrantes mostram que eles tendem a adquirir as taxas de câncer do novo local, sugerindo que fatores genéticos não são os principais responsáveis pelas diferenças entre países.","e":"Esses estudos ajudam a separar efeitos do lugar (ambiente) dos efeitos do indivíduo.","refs":[{"c":4,"p":87,"p2":87,"s":"s4-3"}],"a":"V"},{"id":"c4-01.4","t":"Estudos de distribuição espacial de taxas agregadas costumam testar hipóteses causais, porque medem exposição e desfecho no mesmo indivíduo.","e":"Em geral eles formulam hipóteses (são ecológicos): exposição e desfecho não são medidos no mesmo indivíduo.","refs":[{"c":4,"p":84,"p2":84,"s":"s4-1"}],"a":"F"},{"id":"c4-01.5","t":"A teoria dos focos naturais das doenças, ligada a Pavlovsky, destaca o papel do ambiente na transmissão de doenças como a peste e a leishmaniose.","e":"É um marco da geografia médica do século XX.","refs":[{"c":4,"p":84,"p2":84,"s":"s4-1"}],"a":"V"}],"cap":4,"title":"Pessoa, lugar e tempo"},{"id":"c4-02","src":"livro","type":"vf","items":[{"id":"c4-02.1","t":"Gatrell e Bailey agrupam as técnicas de análise espacial em visualização, análise exploratória e modelagem.","e":"Visualizar (mapas), explorar (padrões, relações) e modelar (testar hipóteses, estimar relações).","refs":[{"c":4,"p":85,"p2":85,"s":"s4-2"}],"a":"V"},{"id":"c4-02.2","t":"A geoestatística trata de fenômenos que variam continuamente no espaço, partindo da ideia de que pontos próximos têm valores mais parecidos que pontos distantes.","e":"Exemplo do livro: soropositividade para hepatite A em Duque de Caxias.","refs":[{"c":4,"p":85,"p2":86,"s":"s4-2"}],"a":"V"},{"id":"c4-02.3","t":"Na análise de dados de área, as observações estão ligadas a regiões (bairros, municípios), e a noção de vizinhança é central.","e":"A vizinhança pode ser definida por fronteira comum, distância ou pesos.","refs":[{"c":4,"p":86,"p2":86,"s":"s4-2"}],"a":"V"},{"id":"c4-02.4","t":"Na análise de padrões pontuais, a variável de interesse é a taxa média de cada município.","e":"Em padrões pontuais a variável é a localização dos eventos; busca-se aleatoriedade, agregação (clusters) ou regularidade.","refs":[{"c":4,"p":86,"p2":86,"s":"s4-2"}],"a":"F"},{"id":"c4-02.5","t":"Geoprocessamento e SIG (sistemas de informação geográfica) servem para capturar, armazenar, manipular, analisar e exibir dados georreferenciados.","e":"São muito usados em vigilância e planejamento.","refs":[{"c":4,"p":85,"p2":85,"s":"s4-2"}],"a":"V"}],"cap":4,"title":"Análise espacial"},{"id":"c4-03","src":"livro","type":"vf","items":[{"id":"c4-03.1","t":"A tendência secular descreve o comportamento da doença ao longo de décadas, sem um critério rígido de duração mínima.","e":"Exemplo: tuberculose em São Paulo, estável até 1945, em forte queda até 1985 e com discreto recrudescimento depois (HIV).","refs":[{"c":4,"p":88,"p2":88,"s":"s4-3"}],"a":"V"},{"id":"c4-03.2","t":"Na Inglaterra e no País de Gales, a mortalidade por tuberculose e por coqueluche já caía antes da identificação dos agentes e da introdução de vacinas e quimioterapia.","e":"Isso aponta o papel das melhorias sociais e das condições de vida (McKeown).","refs":[{"c":4,"p":89,"p2":90,"s":"s4-3"}],"a":"V"},{"id":"c4-03.3","t":"Variações cíclicas são flutuações com periodicidade maior que um ano, como os picos de sarampo a cada 2-3 anos em populações suscetíveis.","e":"Os ciclos dependem do acúmulo de suscetíveis e mudam com a cobertura vacinal.","refs":[{"c":4,"p":90,"p2":90,"s":"s4-3"}],"a":"V"},{"id":"c4-03.4","t":"Variações sazonais têm, por definição, periodicidade de vários anos.","e":"Variações sazonais acompanham as estações, dentro de um ano (ex.: acidentes ofídicos no verão, gripe no inverno).","refs":[{"c":4,"p":90,"p2":91,"s":"s4-3"}],"a":"F"},{"id":"c4-03.5","t":"Antes de atribuir uma tendência a mudanças sociais, deve-se descartar mudanças em critérios diagnósticos, cobertura dos sistemas, classificação e letalidade.","e":"Explicações alternativas podem produzir tendências \"artificiais\".","refs":[{"c":4,"p":89,"p2":89,"s":"s4-3"}],"a":"V"}],"cap":4,"title":"Tendência secular e variações temporais"},{"id":"c4-04","src":"livro","type":"vf","items":[{"id":"c4-04.1","t":"Endemia é a presença habitual de uma doença numa área, dentro dos limites esperados, por tempo indeterminado.","e":"Exemplos: malária, Chagas e esquistossomose em certas regiões.","refs":[{"c":4,"p":92,"p2":92,"s":"s4-4"}],"a":"V"},{"id":"c4-04.2","t":"Um único caso autóctone de uma doença ausente há muitos anos, como a poliomielite, pode configurar uma epidemia.","e":"Epidemia é o excesso em relação ao esperado, não um número mínimo de casos.","refs":[{"c":4,"p":92,"p2":92,"s":"s4-4"}],"a":"V"},{"id":"c4-04.3","t":"Pandemia é uma epidemia com ampla distribuição geográfica, atingindo várias nações ou continentes.","e":"A Aids é um exemplo.","refs":[{"c":4,"p":93,"p2":93,"s":"s4-4"}],"a":"V"},{"id":"c4-04.4","t":"Caso alóctone é aquele que se originou no mesmo local onde foi detectado.","e":"Esse é o caso autóctone. Alóctone é o caso importado de outra localidade.","refs":[{"c":4,"p":92,"p2":92,"s":"s4-4"}],"a":"F"},{"id":"c4-04.5","t":"Surto é uma ocorrência epidêmica com casos relacionados entre si, numa área pequena e delimitada ou numa população institucionalizada, como creches e quartéis.","e":"Exemplo: intoxicação por mamadeira numa creche.","refs":[{"c":4,"p":93,"p2":93,"s":"s4-4"}],"a":"V"}],"cap":4,"title":"Endemia, epidemia, surto e pandemia"},{"id":"c4-05","src":"livro","type":"vf","items":[{"id":"c4-05.1","t":"Na epidemia por fonte comum, os casos aumentam rapidamente, o pico é curto e há declínio, em geral sem transmissão pessoa a pessoa.","e":"Ela costuma ser explosiva e restrita no tempo e no espaço (água, alimento, ar).","refs":[{"c":4,"p":93,"p2":93,"s":"s4-4"}],"a":"V"},{"id":"c4-05.2","t":"Na fonte comum pontual, o pico da curva corresponde aproximadamente ao período médio (ou mediano) de incubação após a exposição.","e":"A data provável de exposição pode ser estimada a partir do primeiro e do último caso, usando os períodos mínimo e máximo de incubação.","refs":[{"c":4,"p":94,"p2":94,"s":"s4-4"}],"a":"V"},{"id":"c4-05.3","t":"A leptospirose no Rio de Janeiro em 1996, depois de chuvas e inundações, é um exemplo de epidemia maciça por fonte comum.","e":"A exposição foi simultânea, à água contaminada das enchentes.","refs":[{"c":4,"p":94,"p2":94,"s":"s4-4"}],"a":"V"},{"id":"c4-05.4","t":"Epidemias propagadas (progressivas) são sempre explosivas, com pico alto e rápido.","e":"Em geral são mais lentas e prolongadas (pessoa a pessoa, vetores). Só se tornam explosivas em comunidades totalmente suscetíveis e isoladas.","refs":[{"c":4,"p":93,"p2":94,"s":"s4-4"}],"a":"F"},{"id":"c4-05.5","t":"A epidemia de sarampo no Rio em 1997 foi do tipo propagada.","e":"A transmissão foi respiratória, pessoa a pessoa, ao longo de meses.","refs":[{"c":4,"p":94,"p2":94,"s":"s4-4"}],"a":"V"}],"cap":4,"title":"Epidemias por fonte comum e propagadas"},{"id":"c4-06","src":"livro","type":"vf","items":[{"id":"c4-06.1","t":"No diagrama de controle pela distribuição normal, calculam-se para cada mês a média e o desvio-padrão das incidências de um período anterior (geralmente 10 anos sem epidemias).","e":"Os limites esperados são média ± 1,96 DP (95%).","refs":[{"c":4,"p":95,"p2":95,"s":"s4-5"}],"a":"V"},{"id":"c4-06.2","t":"Se o limite inferior calculado for negativo, plota-se zero, pois incidência negativa não é plausível.","e":"Exemplo do livro: meningocócica em setembro, limite −0,04.","refs":[{"c":4,"p":96,"p2":96,"s":"s4-5"}],"a":"V"},{"id":"c4-06.3","t":"No método dos quartis, a faixa entre o 1º e o 3º quartil é considerada o esperado, e valores acima do 3º quartil indicam situação epidêmica.","e":"Ordenam-se os valores de cada mês nos anos anteriores e obtêm-se mediana, Q1 e Q3.","refs":[{"c":4,"p":96,"p2":96,"s":"s4-5"}],"a":"V"},{"id":"c4-06.4","t":"Anos epidêmicos devem ser incluídos no período de referência para que o limite esperado seja mais sensível.","e":"Os anos epidêmicos devem ser descartados; senão o limite sobe e o diagrama perde a capacidade de detectar epidemias.","refs":[{"c":4,"p":95,"p2":95,"s":"s4-5"}],"a":"F"},{"id":"c4-06.5","t":"O diagrama de controle é uma ferramenta de vigilância para detectar alterações na distribuição habitual de uma doença e desencadear medidas de controle.","e":"No eixo X fica o tempo (semanas epidemiológicas ou meses); no eixo Y, a incidência.","refs":[{"c":4,"p":95,"p2":95,"s":"s4-5"}],"a":"V"}],"cap":4,"title":"Diagrama de controle"},{"id":"c4-07","src":"livro","type":"vf","items":[{"id":"c4-07.1","t":"Efeito de idade é a mudança associada ao envelhecimento, como o aumento do câncer de próstata com a idade.","e":"É um dos três efeitos temporais.","refs":[{"c":4,"p":98,"p2":98,"s":"s4-6"}],"a":"V"},{"id":"c4-07.2","t":"Efeito de período está ligado a um evento restrito no tempo calendário que afeta todas as idades, como uma mudança na forma de declarar causas de óbito.","e":"Exemplo do livro: a portaria de 1990 no RJ fez disparar os óbitos por causa mal definida.","refs":[{"c":4,"p":98,"p2":99,"s":"s4-6"}],"a":"V"},{"id":"c4-07.3","t":"Efeito de coorte é uma mudança compartilhada pelos membros de uma geração, como a exposição a um lote de vacina de baixa efetividade.","e":"Outro exemplo é o suicídio nas gerações mais novas.","refs":[{"c":4,"p":99,"p2":99,"s":"s4-6"}],"a":"V"},{"id":"c4-07.4","t":"Idade, período e coorte são independentes entre si, por isso seus efeitos são fáceis de separar.","e":"São linearmente dependentes (ano do óbito − ano de nascimento = idade), o que torna difícil separar os efeitos.","refs":[{"c":4,"p":98,"p2":98,"s":"s4-6"}],"a":"F"},{"id":"c4-07.5","t":"Uma análise transversal (taxas por idade num ano) pode sugerir queda das taxas com a idade quando, na verdade, cada coorte mostra aumento com a idade e as gerações mais novas têm taxas maiores.","e":"Um forte efeito de coorte pode mascarar o efeito de idade.","refs":[{"c":4,"p":101,"p2":102,"s":"s4-6"}],"a":"V"}],"cap":4,"title":"Efeitos de idade, período e coorte"},{"id":"c5-01","src":"livro","type":"vf","items":[{"id":"c5-01.1","t":"A quarentena surgiu no século XIV, no combate à peste, quando Veneza isolava navios e contatos por 30-40 dias.","e":"É o embrião da \"vigilância de pessoas\".","refs":[{"c":5,"p":103,"p2":103,"s":"s5-1"}],"a":"V"},{"id":"c5-01.2","t":"O termo \"vigilância epidemiológica\" foi cunhado em 1964 por Karel Raska e difundido pela OMS a partir de 1965.","e":"A ênfase passou da vigilância de pessoas para a vigilância de doenças na população.","refs":[{"c":5,"p":104,"p2":104,"s":"s5-2"}],"a":"V"},{"id":"c5-01.3","t":"A vigilância deixou de ser apenas \"vigilância de pessoas\" (observar casos e contatos) e passou a acompanhar a ocorrência de eventos adversos na comunidade, como \"informação para ação\".","e":"A definição da Lei 8.080/90 inclui qualquer mudança nos determinantes de saúde.","refs":[{"c":5,"p":103,"p2":104,"s":"s5-1"}],"a":"V"},{"id":"c5-01.4","t":"Monitoração e vigilância são sinônimos.","e":"Monitoração acompanha indicadores (econômicos, ambientais, demográficos) sem vínculo essencial com saúde; vigilância foca eventos de saúde nas populações.","refs":[{"c":5,"p":104,"p2":104,"s":"s5-2"}],"a":"F"},{"id":"c5-01.5","t":"Itália (1881) e Estados Unidos (1901) estão entre os primeiros países a adotar a notificação compulsória de algumas doenças em âmbito nacional.","e":"Nos EUA, todos os estados passaram a notificar varíola, tuberculose e cólera.","refs":[{"c":5,"p":103,"p2":103,"s":"s5-1"}],"a":"V"}],"cap":5,"title":"Conceito e história da vigilância"},{"id":"c5-02","src":"livro","type":"vf","items":[{"id":"c5-02.1","t":"Identificar tendências e grupos de risco, detectar epidemias, estimar a magnitude da morbimortalidade, recomendar medidas e avaliar seu impacto são objetivos da vigilância.","e":"Também é objetivo avaliar a adequação das estratégias.","refs":[{"c":5,"p":104,"p2":104,"s":"s5-2"}],"a":"V"},{"id":"c5-02.2","t":"A retroalimentação (feedback) e a divulgação das informações aumentam a adesão dos notificadores e permitem o controle social.","e":"Profissionais que não veem utilidade nos dados tendem a não notificar.","refs":[{"c":5,"p":106,"p2":106,"s":"s5-3"},{"c":5,"p":114,"p2":114,"s":"s5-5"}],"a":"V"},{"id":"c5-02.3","t":"Para doenças de alta letalidade, dados de mortalidade podem ser mais úteis à vigilância do que os de morbidade.","e":"O óbito é um fato vital bem definido, com maior abrangência e validade.","refs":[{"c":5,"p":105,"p2":105,"s":"s5-2"}],"a":"V"},{"id":"c5-02.4","t":"A análise dos dados de vigilância deve ser centralizada no nível federal, para evitar que os municípios tomem decisões isoladas.","e":"O SUS prioriza a análise no nível local (municipal), com autonomia técnico-gerencial, para que a informação gere ação.","refs":[{"c":5,"p":104,"p2":104,"s":"s5-2"},{"c":5,"p":107,"p2":107,"s":"s5-3"}],"a":"F"},{"id":"c5-02.5","t":"Nem todo o trabalho da epidemiologia é vigilância: pesquisa e desenvolvimento de programas vão além do escopo da vigilância, que por isso às vezes é chamada de \"vigilância em saúde pública\".","e":"A vigilância pode, porém, gerar hipóteses para pesquisa.","refs":[{"c":5,"p":104,"p2":104,"s":"s5-2"}],"a":"V"}],"cap":5,"title":"Objetivos e atividades da vigilância"},{"id":"c5-03","src":"livro","type":"vf","items":[{"id":"c5-03.1","t":"Notificar é comunicar a ocorrência de doença, agravo ou surto à autoridade sanitária, e isso pode ser feito por qualquer cidadão.","e":"Para profissionais e estabelecimentos de saúde e de ensino, a notificação é obrigatória (Portaria nº 5/2006).","refs":[{"c":5,"p":106,"p2":106,"s":"s5-3"}],"a":"V"},{"id":"c5-03.2","t":"A notificação deve ser feita já na suspeita, sem esperar confirmação, o que aumenta a sensibilidade e a oportunidade do sistema.","e":"A investigação posterior confirma ou descarta o caso.","refs":[{"c":5,"p":106,"p2":107,"s":"s5-3"}],"a":"V"},{"id":"c5-03.3","t":"Estados e municípios podem incluir doenças na lista nacional de notificação compulsória, mas não podem retirá-las.","e":"A lista nacional é um mínimo comum.","refs":[{"c":5,"p":107,"p2":107,"s":"s5-3"}],"a":"V"},{"id":"c5-03.4","t":"A notificação compulsória deve ser pública e identificada, para que a comunidade saiba quem está doente.","e":"A notificação é sigilosa. A divulgação só ocorre se houver risco para a comunidade, e mesmo assim preservando o anonimato.","refs":[{"c":5,"p":107,"p2":107,"s":"s5-3"}],"a":"F"},{"id":"c5-03.5","t":"O descumprimento da notificação por profissionais pode ser comunicado aos conselhos de classe e ao Ministério Público.","e":"A Portaria nº 5/2006 prevê essa sanção.","refs":[{"c":5,"p":106,"p2":106,"s":"s5-3"}],"a":"V"}],"cap":5,"title":"Notificação compulsória"},{"id":"c5-04","src":"livro","type":"vf","items":[{"id":"c5-04.1","t":"Magnitude refere-se à frequência da doença (incidência, prevalência, mortalidade).","e":"É um dos critérios para incluir uma doença na lista.","refs":[{"c":5,"p":107,"p2":107,"s":"s5-3"}],"a":"V"},{"id":"c5-04.2","t":"Transcendência envolve a gravidade (letalidade, sequelas), a relevância social (medo, estigma) e o impacto econômico.","e":"A meningocócica (medo) e a polio (estigma das sequelas) são exemplos.","refs":[{"c":5,"p":107,"p2":107,"s":"s5-3"}],"a":"V"},{"id":"c5-04.3","t":"Vulnerabilidade é a existência de meios efetivos de prevenção e controle.","e":"Notificar faz sentido quando é possível agir.","refs":[{"c":5,"p":107,"p2":107,"s":"s5-3"}],"a":"V"},{"id":"c5-04.4","t":"Compromissos internacionais não são critério de inclusão na lista, que é decisão apenas epidemiológica.","e":"O Regulamento Sanitário Internacional (OMS) exige notificar doenças como cólera, febre amarela e peste.","refs":[{"c":5,"p":107,"p2":107,"s":"s5-3"}],"a":"F"},{"id":"c5-04.5","t":"O potencial de disseminação (transmissibilidade) e o valor da notificação para desencadear ações oportunas também são critérios.","e":"Epidemias, surtos e agravos inusitados devem ser notificados imediatamente.","refs":[{"c":5,"p":107,"p2":107,"s":"s5-3"}],"a":"V"}],"cap":5,"title":"Critérios da lista de notificação"},{"id":"c5-05","src":"livro","type":"vf","items":[{"id":"c5-05.1","t":"O SINAN registra os agravos de notificação a partir da Ficha Individual de Notificação (FIN) e da Ficha Individual de Investigação (FII).","e":"A FIN é preenchida para cada paciente suspeito e também para a notificação negativa e para surtos.","refs":[{"c":5,"p":108,"p2":111,"s":"s5-3"}],"a":"V"},{"id":"c5-05.2","t":"A notificação negativa é a notificação da não ocorrência de casos e permite diferenciar ausência de casos de falha do sistema.","e":"Ela também é um indicador de eficiência.","refs":[{"c":5,"p":107,"p2":108,"s":"s5-3"}],"a":"V"},{"id":"c5-05.3","t":"O SIA/SUS registra o diagnóstico (CID) de cada atendimento ambulatorial e é a principal fonte do perfil de morbidade ambulatorial.","e":"O SIA paga por procedimento e não registra a CID, então não serve para traçar perfis de morbidade.","refs":[{"c":5,"p":112,"p2":112,"s":"s5-4"}],"a":"F"},{"id":"c5-05.4","t":"O tétano neonatal confirmado, a raiva humana e casos suspeitos de sarampo, poliomielite e cólera estão entre os eventos de notificação imediata.","e":"Surtos e agravos inusitados também exigem notificação imediata.","refs":[{"c":5,"p":111,"p2":111,"s":"s5-3"}],"a":"V"},{"id":"c5-05.5","t":"Os dados do SIM são codificados pelo município de residência, embora o registro em cartório ocorra no local de ocorrência.","e":"A residência interessa para medir o risco; o local de ocorrência interessa, por exemplo, nas causas externas.","refs":[{"c":5,"p":111,"p2":111,"s":"s5-3"}],"a":"V"}],"cap":5,"title":"Sistemas de informação para a vigilância"},{"id":"c5-06","src":"livro","type":"vf","items":[{"id":"c5-06.1","t":"Sensibilidade é a capacidade de detectar os casos que de fato ocorrem; especificidade é a capacidade de excluir os não-casos.","e":"Os dois atributos dependem da definição de caso.","refs":[{"c":5,"p":114,"p2":114,"s":"s5-5"}],"a":"V"},{"id":"c5-06.2","t":"O valor preditivo positivo é a proporção dos casos notificados que são realmente casos, e aumenta com a especificidade da definição e com a prevalência.","e":"Um VPP baixo leva a investigar e tratar não-doentes.","refs":[{"c":5,"p":114,"p2":114,"s":"s5-5"}],"a":"V"},{"id":"c5-06.3","t":"A aceitabilidade reflete a disposição de pessoas, profissionais e instituições em participar do sistema.","e":"Pode ser avaliada pela completude e qualidade do preenchimento das fichas.","refs":[{"c":5,"p":114,"p2":114,"s":"s5-5"}],"a":"V"},{"id":"c5-06.4","t":"A subnotificação se deve principalmente ao caráter ativo dos sistemas, que buscam casos demais.","e":"A subnotificação vem do caráter passivo da maioria dos sistemas, do desconhecimento da lista, da falta de retorno e do tempo para preencher fichas.","refs":[{"c":5,"p":114,"p2":115,"s":"s5-5"}],"a":"F"},{"id":"c5-06.5","t":"A subnotificação seletiva, maior em doenças com sinais pouco evidentes (rubéola, coqueluche) do que nas graves (meningocócica), compromete a representatividade.","e":"Casos graves, hospitalizados ou de interesse da mídia são mais notificados.","refs":[{"c":5,"p":115,"p2":115,"s":"s5-6"}],"a":"V"}],"cap":5,"title":"Atributos e avaliação do sistema"},{"id":"c5-07","src":"livro","type":"vf","items":[{"id":"c5-07.1","t":"Laboratórios confirmam casos e detectam casos não notificados. A vigilância laboratorial integra Lacens, hemocentros e laboratórios públicos e privados.","e":"No exemplo do Egito, a vigilância laboratorial de meningite identificou os agentes e os fatores de óbito.","refs":[{"c":5,"p":112,"p2":113,"s":"s5-4"}],"a":"V"},{"id":"c5-07.2","t":"A imprensa e a população são frequentemente a primeira indicação de agravos inusitados, como no episódio do antraz em Sverdlovsk (1979).","e":"A investigação ligou os casos a aerossóis de uma instalação militar.","refs":[{"c":5,"p":113,"p2":113,"s":"s5-4"}],"a":"V"},{"id":"c5-07.3","t":"Em investigações de surto, o desenho analítico mais usado é o caso-controle.","e":"Estudos seccionais (inquéritos) são os mais comuns no apoio à vigilância; coortes são úteis para agravos agudos de latência curta.","refs":[{"c":5,"p":113,"p2":113,"s":"s5-4"}],"a":"V"},{"id":"c5-07.4","t":"Sistemas sentinela oferecem dados mais representativos da população do que a vigilância universal.","e":"Eles ganham detalhe e validade, mas perdem representatividade, e não permitem calcular incidência.","refs":[{"c":5,"p":113,"p2":113,"s":"s5-4"}],"a":"F"},{"id":"c5-07.5","t":"A vigilância sindrômica foca grupos de sinais e sintomas (ex.: síndromes diarreicas agudas, doenças exantemáticas) em vez de diagnósticos confirmados.","e":"É uma forma de vigilância sentinela.","refs":[{"c":5,"p":113,"p2":113,"s":"s5-4"}],"a":"V"}],"cap":5,"title":"Fontes complementares e sentinela"},{"id":"c5-08","src":"livro","type":"vf","items":[{"id":"c5-08.1","t":"As primeiras etapas de uma investigação de surto são confirmar o diagnóstico, confirmar a existência do surto e caracterizá-lo por pessoa, lugar e tempo.","e":"O livro destaca que essas três primeiras são fundamentais.","refs":[{"c":5,"p":117,"p2":117,"s":"s5-6"}],"a":"V"},{"id":"c5-08.2","t":"No início, usa-se uma definição de caso mais sensível (confirmados, prováveis e possíveis); para testar hipóteses, uma mais específica.","e":"A definição sensível dimensiona o surto; a específica evita falsos-positivos na análise.","refs":[{"c":5,"p":117,"p2":117,"s":"s5-6"}],"a":"V"},{"id":"c5-08.3","t":"A hipótese sobre a fonte é reforçada quando a taxa de ataque entre os expostos é significativamente maior que entre os não-expostos.","e":"Além disso, nenhum outro modo de transmissão deve explicar a mesma distribuição.","refs":[{"c":5,"p":117,"p2":117,"s":"s5-6"}],"a":"V"},{"id":"c5-08.4","t":"Não há regra para o fim de um surto: ele só termina com intervenção do serviço de saúde.","e":"Surtos podem acabar porque acabam os suscetíveis, cessa a exposição ou a fonte, cai a suscetibilidade (vacinação) ou o patógeno perde virulência.","refs":[{"c":5,"p":116,"p2":116,"s":"s5-6"}],"a":"F"},{"id":"c5-08.5","t":"No surto de Chagas aguda em Santa Catarina (2005), a fonte foi caldo de cana contaminado num quiosque à beira da BR-101.","e":"Era uma área não endêmica, o que dificultou o diagnóstico; o período de incubação variou de 3 a 17 dias.","refs":[{"c":5,"p":118,"p2":118,"s":"s5-6"}],"a":"V"}],"cap":5,"title":"Investigação de surtos"},{"id":"c5-09","src":"livro","type":"vf","items":[{"id":"c5-09.1","t":"Doenças emergentes são as que surgiram, foram descobertas, aumentaram ou mudaram de padrão nas últimas décadas; reemergentes são as que voltam a aparecer.","e":"No Brasil, Aids (1981), dengue (1982), cólera (1991) e hantavirose (1993) são exemplos.","refs":[{"c":5,"p":117,"p2":118,"s":"s5-6"}],"a":"V"},{"id":"c5-09.2","t":"O CIEVS, criado pela SVS/MS em 2005, recebe notificações 24 horas por dia e monitora emergências de saúde pública de relevância nacional.","e":"Ele se inspira no SHOC da OMS. Os eventos relevantes são investigados pela Unidade de Respostas Rápidas.","refs":[{"c":5,"p":119,"p2":119,"s":"s5-6"}],"a":"V"},{"id":"c5-09.3","t":"O CIEVS só aceita notificações enviadas por formulário em papel.","e":"Ele recebe notificações por telefone, fax e e-mail, além de acompanhar diariamente as notícias da imprensa.","refs":[{"c":5,"p":119,"p2":119,"s":"s5-6"}],"a":"F"},{"id":"c5-09.4","t":"Epidemias funcionam como \"experimentos naturais\" e podem trazer conhecimento novo sobre as doenças.","e":"Por isso os primeiros casos são investigados em profundidade.","refs":[{"c":5,"p":116,"p2":116,"s":"s5-6"}],"a":"V"},{"id":"c5-09.5","t":"Uma epidemia pode ocorrer quando suscetíveis viajam para áreas endêmicas ou quando novas práticas sociais levam a infecção a grupos suscetíveis.","e":"Introdução de agente novo e mudanças na suscetibilidade do hospedeiro (imunossupressão, desnutrição) também são circunstâncias.","refs":[{"c":5,"p":115,"p2":116,"s":"s5-6"}],"a":"V"}],"cap":5,"title":"Doenças emergentes e CIEVS"},{"id":"c6-01","src":"livro","type":"vf","items":[{"id":"c6-01.1","t":"Malthus afirmava que a população cresce em progressão geométrica e os recursos em progressão aritmética.","e":"Para ele, a miséria vinha da incapacidade dos pobres de limitar a prole.","refs":[{"c":6,"p":125,"p2":125,"s":"s6-1"}],"a":"V"},{"id":"c6-01.2","t":"Para a visão marxista não há uma lei populacional universal: cada fase do desenvolvimento tem sua própria lei, e a miséria decorre da distribuição desigual.","e":"Os neomalthusianos defendiam o controle da natalidade; os marxistas, o desenvolvimento econômico.","refs":[{"c":6,"p":125,"p2":125,"s":"s6-1"}],"a":"V"},{"id":"c6-01.3","t":"A teoria da transição demográfica relaciona a queda da natalidade e da mortalidade com a industrialização, tendo como referência os países europeus.","e":"Uma crítica é a generalização desse modelo a contextos muito diferentes.","refs":[{"c":6,"p":125,"p2":125,"s":"s6-1"}],"a":"V"},{"id":"c6-01.4","t":"A população mundial levou cerca de 50 anos para dobrar no início da era cristã.","e":"No início da era cristã levou mais de 1.200 anos para dobrar; o crescimento acelerou só a partir do século XVIII.","refs":[{"c":6,"p":123,"p2":124,"s":"s6-1"}],"a":"F"},{"id":"c6-01.5","t":"A transição demográfica é a passagem de altos coeficientes de natalidade e mortalidade para valores muito reduzidos.","e":"É um processo lento, como sugere a própria palavra \"transição\".","refs":[{"c":6,"p":125,"p2":125,"s":"s6-1"}],"a":"V"}],"cap":6,"title":"Teorias populacionais"},{"id":"c6-02","src":"livro","type":"vf","items":[{"id":"c6-02.1","t":"Na fase 1 (pré-industrial), natalidade e mortalidade são altas e o crescimento é lento.","e":"Isso é chamado de \"equilíbrio populacional\".","refs":[{"c":6,"p":126,"p2":126,"s":"s6-2"}],"a":"V"},{"id":"c6-02.2","t":"Na fase 2, a mortalidade cai enquanto a natalidade continua alta, gerando a \"explosão populacional\".","e":"Nos países em desenvolvimento isso ocorreu de forma mais tardia e repentina (século XX).","refs":[{"c":6,"p":126,"p2":126,"s":"s6-2"}],"a":"V"},{"id":"c6-02.3","t":"Na fase 3, a natalidade começa a cair de forma importante e o efeito mais marcante é o envelhecimento populacional.","e":"O crescimento ainda é relativamente alto.","refs":[{"c":6,"p":126,"p2":126,"s":"s6-2"}],"a":"V"},{"id":"c6-02.4","t":"Na fase 4, a natalidade volta a subir e a população rejuvenesce.","e":"Na fase 4 natalidade e mortalidade são baixas, a fecundidade fica perto da reposição e a população envelhece, sobretudo à custa das mulheres.","refs":[{"c":6,"p":126,"p2":126,"s":"s6-2"}],"a":"F"},{"id":"c6-02.5","t":"No Brasil, o rápido crescimento a partir de 1950 corresponde à fase 2; a desaceleração a partir de 1970 corresponde à fase 3.","e":"O equilíbrio deve se completar nas primeiras décadas do século XXI.","refs":[{"c":6,"p":126,"p2":126,"s":"s6-2"}],"a":"V"}],"cap":6,"title":"Fases da transição demográfica"},{"id":"c6-03","src":"livro","type":"vf","items":[{"id":"c6-03.1","t":"Fertilidade é a capacidade fisiológica de conceber; fecundidade é o desempenho reprodutivo efetivo, medido em filhos por mulher.","e":"O período reprodutivo considerado vai dos 15 aos 49 anos.","refs":[{"c":6,"p":128,"p2":129,"s":"s6-3"}],"a":"V"},{"id":"c6-03.2","t":"O coeficiente geral de natalidade usa a população total no denominador; o de fecundidade, as mulheres de 15 a 49 anos.","e":"Ambos têm os nascidos vivos no numerador (× 1.000).","refs":[{"c":6,"p":129,"p2":129,"s":"s6-3"}],"a":"V"},{"id":"c6-03.3","t":"A fecundidade brasileira caiu de mais de 6 filhos por mulher (até 1960) para cerca de 2,35 em 2000, com projeção abaixo da reposição.","e":"A queda começou nos anos 1970.","refs":[{"c":6,"p":129,"p2":130,"s":"s6-3"}],"a":"V"},{"id":"c6-03.4","t":"No Brasil, a queda da natalidade precedeu a queda da mortalidade.","e":"O declínio da mortalidade (já nos anos 1940) precedeu o da natalidade (intensificado nos anos 1970).","refs":[{"c":6,"p":129,"p2":130,"s":"s6-3"}],"a":"F"},{"id":"c6-03.5","t":"Crescimento vegetativo é a diferença entre natalidade e mortalidade.","e":"Quando os óbitos superam os nascimentos, ele fica negativo.","refs":[{"c":6,"p":128,"p2":128,"s":"s6-3"}],"a":"V"}],"cap":6,"title":"Indicadores demográficos do Brasil"},{"id":"c6-04","src":"livro","type":"vf","items":[{"id":"c6-04.1","t":"O principal fator do envelhecimento populacional é a queda da fecundidade.","e":"Ela estreita a base da pirâmide (menos crianças), sobretudo quando a mortalidade já é baixa.","refs":[{"c":6,"p":131,"p2":131,"s":"s6-3"}],"a":"V"},{"id":"c6-04.2","t":"A queda isolada da mortalidade infantil tenderia, inicialmente, a rejuvenescer a população.","e":"Mais crianças sobrevivem e engrossam a base da pirâmide.","refs":[{"c":6,"p":131,"p2":131,"s":"s6-3"}],"a":"V"},{"id":"c6-04.3","t":"A idade mediana da população brasileira era de cerca de 18 anos em 1950 e tende a dobrar, chegando a cerca de 40 anos em 2050.","e":"A idade mediana divide a população em duas metades.","refs":[{"c":6,"p":131,"p2":131,"s":"s6-3"}],"a":"V"},{"id":"c6-04.4","t":"Em 2000 a maioria da população brasileira ainda era rural.","e":"Em 1940, 68,8% eram rurais; em 2000, 81,2% eram urbanos.","refs":[{"c":6,"p":126,"p2":126,"s":"s6-2"}],"a":"F"},{"id":"c6-04.5","t":"A urbanização amplia o acesso a serviços de saúde, mas também traz riscos como poluição, violência, estresse e tabagismo.","e":"O resultado é um perfil epidemiológico mais complexo.","refs":[{"c":6,"p":127,"p2":127,"s":"s6-2"}],"a":"V"}],"cap":6,"title":"Envelhecimento e urbanização"},{"id":"c6-05","src":"livro","type":"vf","items":[{"id":"c6-05.1","t":"Abdel Omran propôs em 1971 a teoria da transição epidemiológica, com três \"eras\".","e":"A base foram os países industrializados.","refs":[{"c":6,"p":134,"p2":134,"s":"s6-4"}],"a":"V"},{"id":"c6-05.2","t":"Na \"era da pestilência e da fome\", a mortalidade era alta e flutuante e a esperança de vida ficava abaixo de 30 anos.","e":"Essa era vai até o fim da Idade Média.","refs":[{"c":6,"p":134,"p2":134,"s":"s6-4"}],"a":"V"},{"id":"c6-05.3","t":"Na \"era das doenças degenerativas e provocadas pelo homem\", predominam doenças cardiovasculares, neoplasias e causas externas.","e":"Ela começa com a Revolução Industrial.","refs":[{"c":6,"p":134,"p2":134,"s":"s6-4"}],"a":"V"},{"id":"c6-05.4","t":"Na \"era do declínio das pandemias\", as doenças crônicas já eram as principais causas de morte.","e":"Nessa era as doenças infecciosas ainda eram as principais causas, mas as pandemias diminuíam e a esperança de vida subia para 40-50 anos.","refs":[{"c":6,"p":134,"p2":134,"s":"s6-4"}],"a":"F"},{"id":"c6-05.5","t":"Uma crítica ao modelo de Omran é seu caráter determinista e linear, baseado na experiência europeia.","e":"Ele não explica a reemergência de doenças nem a superposição de padrões.","refs":[{"c":6,"p":134,"p2":135,"s":"s6-4"}],"a":"V"}],"cap":6,"title":"Transição epidemiológica: Omran"},{"id":"c6-06","src":"livro","type":"vf","items":[{"id":"c6-06.1","t":"Olshansky e Ault propuseram uma \"quarta era\", em que a mortalidade por doenças degenerativas é adiada para idades mais avançadas.","e":"É a chamada \"revolução cardiovascular\".","refs":[{"c":6,"p":135,"p2":135,"s":"s6-4"}],"a":"V"},{"id":"c6-06.2","t":"O modelo \"tardio-polarizado\" de Frenk descreve países de renda média, com superposição de doenças infecciosas e crônicas, contratransição e polarização epidemiológica.","e":"No Brasil se fala em transição \"prolongada\".","refs":[{"c":6,"p":135,"p2":136,"s":"s6-4"}],"a":"V"},{"id":"c6-06.3","t":"A Aids, surgida no início dos anos 1980, foi o fato mais importante para questionar a ideia de que as doenças infecciosas iriam desaparecer.","e":"Depois dela vieram muitas doenças emergentes e reemergentes.","refs":[{"c":6,"p":135,"p2":135,"s":"s6-4"}],"a":"V"},{"id":"c6-06.4","t":"No Brasil, as doenças infecciosas e parasitárias deixaram de ser a principal causa de morte já em 1930.","e":"Em 1930 elas eram 45,7% dos óbitos e foram a principal causa até meados dos anos 1960. As cardiovasculares lideram desde o início dos anos 1960.","refs":[{"c":6,"p":137,"p2":137,"s":"s6-5"}],"a":"F"},{"id":"c6-06.5","t":"Polarização epidemiológica é a coexistência de padrões diferentes de morbimortalidade em subgrupos de uma mesma população (regiões, classes sociais).","e":"Pode ser geográfica ou social.","refs":[{"c":6,"p":135,"p2":136,"s":"s6-4"}],"a":"V"}],"cap":6,"title":"Modelos complementares e Brasil"},{"id":"c6-07","src":"livro","type":"vf","items":[{"id":"c6-07.1","t":"Entre 1930 e 2003, a mortalidade proporcional por doenças do aparelho circulatório subiu de 11,8% para 27,3%.","e":"As neoplasias subiram de 2,7% para 12,6%, e as causas externas de 2,6% para 12,6%.","refs":[{"c":6,"p":137,"p2":137,"s":"s6-5"}],"a":"V"},{"id":"c6-07.2","t":"As doenças do aparelho respiratório são a principal causa de internação no SUS, embora fiquem em último lugar entre as principais causas de óbito.","e":"As neoplasias, ao contrário, são a 2ª causa de morte e a última entre as principais causas de internação.","refs":[{"c":6,"p":137,"p2":139,"s":"s6-5"}],"a":"V"},{"id":"c6-07.3","t":"O fato de as doenças infecciosas e parasitárias ainda estarem em 3º lugar nas internações é visto como um indicador indireto da polarização epidemiológica.","e":"Elas ficam à frente das causas externas e das neoplasias.","refs":[{"c":6,"p":138,"p2":139,"s":"s6-5"}],"a":"V"},{"id":"c6-07.4","t":"As causas externas afetam igualmente homens e mulheres de todas as idades.","e":"Elas afetam sobretudo homens jovens (armas de fogo, acidentes de trânsito).","refs":[{"c":6,"p":137,"p2":138,"s":"s6-5"}],"a":"F"},{"id":"c6-07.5","t":"A varíola foi a única doença erradicada no Brasil (1978); a poliomielite teve seu último caso em 1989.","e":"O sarampo foi eliminado após a epidemia de 1997.","refs":[{"c":6,"p":139,"p2":139,"s":"s6-5"}],"a":"V"}],"cap":6,"title":"Mortalidade e internações por causas no Brasil"},{"id":"c6-08","src":"livro","type":"vf","items":[{"id":"c6-08.1","t":"O Ministério da Saúde classifica as doenças infecciosas em três tendências: decrescente, persistente e emergente/reemergente.","e":"É uma forma de mostrar a não linearidade da transição.","refs":[{"c":6,"p":139,"p2":139,"s":"s6-5"}],"a":"V"},{"id":"c6-08.2","t":"Doença de Chagas, difteria, coqueluche e tétano estão entre as doenças com tendência decrescente; ainda assim ocorrem surtos de Chagas por transmissão oral.","e":"A transmissão vetorial e transfusional da doença de Chagas está sob controle.","refs":[{"c":6,"p":141,"p2":141,"s":"s6-5"}],"a":"V"},{"id":"c6-08.3","t":"Malária, tuberculose, leishmanioses e hanseníase estão entre as doenças com tendência de persistência.","e":"As hepatites B e C e a leptospirose também.","refs":[{"c":6,"p":141,"p2":141,"s":"s6-5"}],"a":"V"},{"id":"c6-08.4","t":"Dengue e cólera são exemplos de doenças com tendência decrescente no Brasil desde 1980.","e":"São emergentes ou reemergentes: dengue desde 1982 e cólera reintroduzida em 1991.","refs":[{"c":6,"p":141,"p2":143,"s":"s6-5"}],"a":"F"},{"id":"c6-08.5","t":"A difusão da Aids repercutiu em outras doenças infecciosas, em particular a tuberculose.","e":"A coinfecção HIV-TB explica parte do recrudescimento da TB.","refs":[{"c":6,"p":143,"p2":143,"s":"s6-6"},{"c":4,"p":88,"p2":88,"s":"s4-3"}],"a":"V"}],"cap":6,"title":"Tendências das doenças infecciosas"},{"id":"c6-09","src":"livro","type":"vf","items":[{"id":"c6-09.1","t":"A transição nutricional é a passagem de um perfil dominado pela desnutrição para outro dominado pela obesidade.","e":"Ela acompanha mudanças econômicas, sociais e demográficas.","refs":[{"c":6,"p":143,"p2":143,"s":"s6-6"},{"c":6,"p":146,"p2":146,"s":"s6-6"}],"a":"V"},{"id":"c6-09.2","t":"O livro adverte que a transição nutricional não deve ser lida como melhoria geral das condições de vida, pois fome e obesidade coexistem, sobretudo nas camadas desfavorecidas.","e":"Alimentos baratos, calóricos e pouco nutritivos, sedentarismo e má distribuição de renda estão por trás disso.","refs":[{"c":6,"p":146,"p2":146,"s":"s6-6"}],"a":"V"},{"id":"c6-09.3","t":"Em 2003, as regiões mais ricas tinham maior mortalidade proporcional por neoplasias e doenças circulatórias.","e":"Já o Norte e o Centro-Oeste tinham mais peso de DIP e causas externas: polarização geográfica.","refs":[{"c":6,"p":146,"p2":147,"s":"s6-6"}],"a":"V"},{"id":"c6-09.4","t":"As desigualdades regionais na mortalidade infantil desapareceram entre 1930 e 2001.","e":"A TMI caiu em todas as regiões, mas em 2001 o Nordeste ainda tinha 43,0 contra 16,4 no Sul.","refs":[{"c":6,"p":148,"p2":148,"s":"s6-6"}],"a":"F"},{"id":"c6-09.5","t":"Entre 1979 e 2003, o indicador de Swaroop-Uemura subiu em todas as regiões, mas o Norte continuou abaixo da média nacional.","e":"O Norte foi de 31,5% para 55%; o Sul, de 53,5% para 74,5%.","refs":[{"c":6,"p":148,"p2":148,"s":"s6-6"}],"a":"V"}],"cap":6,"title":"Transição nutricional e desigual"},{"id":"c8-01","src":"livro","type":"vf","items":[{"id":"c8-01.1","t":"A epidemiologia estuda a distribuição e os determinantes dos eventos de saúde em populações definidas e aplica esse conhecimento ao controle dos problemas de saúde.","e":"É a definição do Dicionário de Epidemiologia (Last).","refs":[{"c":8,"p":173,"p2":173,"s":"s8-1"}],"a":"V"},{"id":"c8-01.2","t":"Descrever, explicar, predizer e controlar a ocorrência das doenças são objetivos da pesquisa epidemiológica.","e":"O foco está tanto em compreender quanto em intervir.","refs":[{"c":8,"p":173,"p2":173,"s":"s8-1"}],"a":"V"},{"id":"c8-01.3","t":"Mensuração, estimação de parâmetros e testes de hipóteses são os três procedimentos do tratamento numérico na pesquisa epidemiológica.","e":"A estimativa vem da amostra; o parâmetro é da população e em geral é desconhecido.","refs":[{"c":8,"p":173,"p2":174,"s":"s8-1"}],"a":"V"},{"id":"c8-01.4","t":"Testes estatísticos de hipóteses avaliam se uma associação é causal.","e":"Eles avaliam quanto o acaso pode explicar o resultado. Causalidade exige julgar o conjunto das evidências.","refs":[{"c":8,"p":174,"p2":174,"s":"s8-2"},{"c":8,"p":179,"p2":179,"s":"s8-3"}],"a":"F"},{"id":"c8-01.5","t":"Um motivo para estudar populações é que, mesmo quando o interesse é o indivíduo, inferências sobre fatores e doença exigem grupos.","e":"O objetivo final é melhorar a saúde das populações.","refs":[{"c":8,"p":173,"p2":173,"s":"s8-1"}],"a":"V"}],"cap":8,"title":"Epidemiologia e pesquisa"},{"id":"c8-02","src":"livro","type":"vf","items":[{"id":"c8-02.1","t":"No modelo probabilístico, a epidemiologia consegue prever quantos irão adoecer numa população, mas não quem adoecerá.","e":"Estimam-se parâmetros causais para populações, não determinísticos para indivíduos.","refs":[{"c":8,"p":174,"p2":174,"s":"s8-2"}],"a":"V"},{"id":"c8-02.2","t":"Para ser fator de risco, a doença deve variar com o fator, o fator deve preceder a doença e a associação não pode ser totalmente explicada por erro aleatório, confusão ou viés.","e":"Exemplo do livro: o tabagismo precisa começar antes do enfisema.","refs":[{"c":8,"p":174,"p2":174,"s":"s8-2"}],"a":"V"},{"id":"c8-02.3","t":"Fatores prognósticos são os que influenciam o curso de uma doença já estabelecida.","e":"Fatores de risco influenciam o surgimento.","refs":[{"c":8,"p":174,"p2":174,"s":"s8-2"}],"a":"V"},{"id":"c8-02.4","t":"A hipótese operacional é mais ampla e abstrata que a hipótese conceitual.","e":"A hipótese conceitual é a ampla. A operacional a traduz em variáveis mensuráveis.","refs":[{"c":8,"p":174,"p2":174,"s":"s8-2"}],"a":"F"},{"id":"c8-02.5","t":"Na teoria de Barker, a hipótese \"baixo peso ao nascer (< 2.500 g) aumenta a probabilidade de doença coronariana na vida adulta\" é uma hipótese operacional.","e":"A conceitual seria \"a subnutrição intrauterina é fator de risco para doença cardiovascular\".","refs":[{"c":8,"p":174,"p2":174,"s":"s8-2"}],"a":"V"}],"cap":8,"title":"Causalidade e fator de risco"},{"id":"c8-03","src":"livro","type":"vf","items":[{"id":"c8-03.1","t":"A inferência indutiva parte de observações específicas para generalizações, como na conclusão de que a pelagra se devia à deficiência de nutrientes.","e":"Hume mostrou que repetições não garantem causalidade: é o \"problema de Hume\".","refs":[{"c":8,"p":175,"p2":175,"s":"s8-2"}],"a":"V"},{"id":"c8-03.2","t":"Para Popper, a ciência avança pela refutação: hipóteses são conjecturas testadas por predições dedutivas, e uma hipótese não refutada permanece aceita.","e":"Isso estimula testar múltiplas hipóteses.","refs":[{"c":8,"p":175,"p2":175,"s":"s8-2"}],"a":"V"},{"id":"c8-03.3","t":"Para Kuhn, aceitar ou refutar teorias depende do consenso da comunidade científica; quando se rejeita a infraestrutura em vez da teoria, ocorre uma revolução científica.","e":"É a inferência por consenso.","refs":[{"c":8,"p":175,"p2":175,"s":"s8-2"}],"a":"V"},{"id":"c8-03.4","t":"A inferência bayesiana atribui uma probabilidade a priori às premissas e calcula uma probabilidade a posteriori para a conclusão.","e":"Ela lida com conclusões que não são 100% certas.","refs":[{"c":8,"p":175,"p2":175,"s":"s8-2"}],"a":"V"},{"id":"c8-03.5","t":"Rothman e Greenland concluem que só os ensaios randomizados produzem prova definitiva de causalidade.","e":"Eles afirmam que \"provar é impossível\": nem experimentos produzem prova, e a ciência não experimental pode ser muito sólida (ex.: cigarro).","refs":[{"c":8,"p":176,"p2":176,"s":"s8-3"}],"a":"F"}],"cap":8,"title":"Modos de inferência causal"},{"id":"c8-04","src":"livro","type":"vf","items":[{"id":"c8-04.1","t":"População do estudo (amostra) é o grupo de indivíduos efetivamente observado.","e":"Ex.: 100 crianças nascidas em 2000 no município X.","refs":[{"c":8,"p":176,"p2":176,"s":"s8-3"}],"a":"V"},{"id":"c8-04.2","t":"População-fonte (universo amostral) é o conjunto dos elegíveis, representado pela amostra.","e":"Ex.: todas as crianças nascidas em 2000 no município X.","refs":[{"c":8,"p":176,"p2":176,"s":"s8-3"}],"a":"V"},{"id":"c8-04.3","t":"População-alvo é aquela para a qual se deseja fazer as inferências.","e":"Se a amostra não a representa, há erro sistemático (viés).","refs":[{"c":8,"p":176,"p2":176,"s":"s8-3"}],"a":"V"},{"id":"c8-04.4","t":"A base populacional é o conjunto dos casos já diagnosticados que participam do estudo.","e":"Base populacional é o conjunto de indivíduos de onde surgem os casos.","refs":[{"c":8,"p":176,"p2":176,"s":"s8-3"}],"a":"F"},{"id":"c8-04.5","t":"Se nascimentos registrados em cartório forem usados como fonte e houver sub-registro, a população do estudo pode não representar a população-alvo.","e":"É um exemplo de viés de seleção.","refs":[{"c":8,"p":176,"p2":176,"s":"s8-3"}],"a":"V"}],"cap":8,"title":"Populações do estudo"},{"id":"c8-05","src":"livro","type":"vf","items":[{"id":"c8-05.1","t":"Nos estudos experimentais o investigador controla a exposição e aloca os indivíduos aleatoriamente.","e":"Por isso, por razões éticas, eles se restringem em geral a fatores protetores.","refs":[{"c":8,"p":176,"p2":176,"s":"s8-3"}],"a":"V"},{"id":"c8-05.2","t":"Ensaios clínicos terapêuticos avaliam tratamentos em doentes; ensaios profiláticos avaliam intervenções em não-doentes, como a aspirina para prevenir infarto.","e":"Intervenções comunitárias estendem o ensaio profilático a uma comunidade (ex.: tratamento da água).","refs":[{"c":8,"p":176,"p2":177,"s":"s8-3"}],"a":"V"},{"id":"c8-05.3","t":"No estudo quase-experimental o investigador controla o fator, mas a alocação não é aleatória, como na comparação de cárie entre uma cidade com fluoretação e outra sem.","e":"Em geral são direcionados a populações.","refs":[{"c":8,"p":177,"p2":177,"s":"s8-3"}],"a":"V"},{"id":"c8-05.4","t":"Os estudos observacionais apresentam mais problemas éticos que os experimentais, pois o investigador decide quem fica exposto.","e":"No observacional o investigador não controla a exposição, que acontece independentemente dele. Por isso ele não tem esse problema ético para estudar fatores de risco.","refs":[{"c":8,"p":177,"p2":177,"s":"s8-3"}],"a":"F"},{"id":"c8-05.5","t":"Estudos preliminares, mais baratos e menos rigorosos, podem selecionar hipóteses que depois serão testadas com desenhos de maior validade.","e":"A escolha do desenho depende da doença, da exposição, do conhecimento prévio e dos recursos.","refs":[{"c":8,"p":179,"p2":179,"s":"s8-3"}],"a":"V"}],"cap":8,"title":"Experimental, quase-experimental e observacional"},{"id":"c8-06","src":"livro","type":"vf","items":[{"id":"c8-06.1","t":"Os estudos observacionais podem ser classificados por estratégia de observação (seccional ou longitudinal), esquema de seleção (completo ou incompleto) e unidade de análise (individual ou agregada).","e":"São as três dimensões da taxonomia do capítulo.","refs":[{"c":8,"p":177,"p2":177,"s":"s8-3"}],"a":"V"},{"id":"c8-06.2","t":"Na observação seccional, em geral não se pode estabelecer a relação temporal entre as características, exceto para variáveis constitucionais como sexo e grupo sanguíneo.","e":"É como uma fotografia, em que o momento fica congelado.","refs":[{"c":8,"p":177,"p2":177,"s":"s8-3"}],"a":"V"},{"id":"c8-06.3","t":"No esquema de seleção completo, todos os indivíduos da base populacional são observados; no incompleto, apenas uma fração dos não-casos.","e":"A coorte usa esquema completo; o caso-controle, incompleto.","refs":[{"c":8,"p":177,"p2":178,"s":"s8-3"}],"a":"V"},{"id":"c8-06.4","t":"Nos estudos ecológicos, sabe-se para cada indivíduo se ele é exposto e se é doente.","e":"No nível agregado só se conhecem proporções por grupo (cidade, área), não a distribuição conjunta individual.","refs":[{"c":8,"p":177,"p2":178,"s":"s8-3"}],"a":"F"},{"id":"c8-06.5","t":"Os termos prospectivo (concorrente) e retrospectivo (histórico, não concorrente) referem-se ao momento da medição da exposição e do desfecho em relação à sua ocorrência.","e":"A qualidade dos dados tende a ser melhor na medição concorrente.","refs":[{"c":8,"p":178,"p2":179,"s":"s8-3"}],"a":"V"}],"cap":8,"title":"Dimensões dos estudos observacionais"},{"id":"c8-07","src":"livro","type":"vf","items":[{"id":"c8-07.1","t":"Na coorte, indivíduos sem a doença são classificados pela exposição e acompanhados para comparar a ocorrência da doença.","e":"É longitudinal, com esquema completo e dados individuais.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":"V"},{"id":"c8-07.2","t":"No caso-controle, parte-se dos casos e de uma amostra de não-casos da mesma base populacional (controles) e compara-se a exposição.","e":"É longitudinal, porque exposição e doença se referem a momentos diferentes.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":"V"},{"id":"c8-07.3","t":"O estudo seccional é mais adequado para estimar prevalências e médias ou levantar hipóteses do que para testar causalidade.","e":"Exposição e desfecho são medidos no mesmo momento.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":"V"},{"id":"c8-07.4","t":"O estudo ecológico pode ser visto como um estudo seccional com informação no nível agregado.","e":"Exemplo: comparar proporções de fumantes e taxas de doença coronariana entre cidades.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":"V"},{"id":"c8-07.5","t":"Coorte e caso-controle sobre tabagismo e infarto em funcionários de uma universidade teriam bases populacionais diferentes.","e":"A base é a mesma (os funcionários). A diferença é que a coorte observa toda a base e o caso-controle só uma amostra para os controles.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":"F"}],"cap":8,"title":"Coorte, caso-controle, seccional e ecológico"},{"id":"c8-08","src":"livro","type":"choice","ctx":["Classifique cada descrição (exemplos criados para treino, no estilo da prova)."],"items":[{"id":"c8-08.1","t":"Mulheres com diagnóstico recente de câncer de mama atendidas em um hospital e mulheres sem câncer da mesma área foram entrevistadas sobre o uso prévio de anticoncepcionais orais. Calcularam-se odds ratios.","e":"Seleção por desfecho (casos e controles) e investigação da exposição passada: caso-controle.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":2},{"id":"c8-08.2","t":"Foram correlacionadas, para os 92 municípios de um estado, a cobertura da Estratégia Saúde da Família e a taxa de internação por condições sensíveis à atenção primária em 2019.","e":"Unidades de análise agregadas (municípios): ecológico.","refs":[{"c":8,"p":177,"p2":178,"s":"s8-3"}],"a":4},{"id":"c8-08.3","t":"Gestantes foram classificadas, no 1º trimestre, segundo o consumo de álcool e acompanhadas até o parto para comparar a incidência de baixo peso ao nascer entre os grupos.","e":"Classificação pela exposição em pessoas sem o desfecho, seguida de acompanhamento: coorte (prospectiva).","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":1},{"id":"c8-08.4","t":"Um inquérito domiciliar com amostra probabilística de adultos de uma capital estimou a prevalência de hipertensão autorreferida e sua associação com escolaridade, num único momento.","e":"Medição de exposição e desfecho no mesmo momento, em indivíduos: transversal.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":3},{"id":"c8-08.5","t":"Idosos de 20 instituições de longa permanência foram sorteados para receber suplementação de vitamina D ou placebo, e comparou-se a ocorrência de quedas em 12 meses.","e":"O investigador controla a intervenção e a alocação é aleatória: experimental (ensaio clínico).","refs":[{"c":8,"p":176,"p2":177,"s":"s8-3"}],"a":0},{"id":"c8-08.6","t":"Pesquisadores reuniram os resultados de 35 ensaios clínicos publicados sobre um antidepressivo e calcularam uma medida de efeito combinada.","e":"Revisão sistemática com metanálise: a unidade são estudos publicados, não é nenhum dos desenhos primários listados.","refs":[{"c":8,"p":179,"p2":179,"s":"s8-3"}],"a":5},{"id":"c8-08.7","t":"Registros de admissão de trabalhadores de uma fábrica desde 1970 foram usados para classificar a exposição ao amianto; os registros de óbito até 2020 permitiram comparar a mortalidade por mesotelioma entre expostos e não expostos.","e":"Coorte histórica (retrospectiva, não concorrente): exposição e desfecho já ocorreram e são obtidos de registros, mas a lógica vai da exposição ao desfecho.","refs":[{"c":8,"p":178,"p2":179,"s":"s8-3"}],"a":1},{"id":"c8-08.8","t":"Comparou-se a evolução anual das taxas de mortalidade por câncer de pulmão com o consumo per capita de cigarros nos países da América do Sul entre 1980 e 2015.","e":"Dados agregados por país, ao longo do tempo: ecológico (de séries temporais).","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"},{"c":4,"p":88,"p2":88,"s":"s4-3"}],"a":4}],"cap":8,"title":"Qual é o desenho? (exercícios)","opts":["Estudo experimental","Estudo de coorte","Estudo caso-controle","Estudo transversal","Estudo ecológico","Nenhum dos anteriores"]},{"id":"c18-01","src":"livro","type":"vf","items":[{"id":"c18-01.1","t":"Na matriz de dados, cada linha corresponde a um elemento (unidade observada) e cada coluna a uma variável.","e":"A observação é o valor de uma variável para um elemento; o caso é o conjunto de observações de um elemento.","refs":[{"c":18,"p":324,"p2":324,"s":"s18-1"},{"c":18,"p":326,"p2":326,"s":"s18-2"}],"a":"V"},{"id":"c18-01.2","t":"Coletar o valor bruto (ex.: peso em gramas) dá mais flexibilidade para criar faixas depois; perguntas fechadas por faixa ajudam quando o valor exato não é conhecido.","e":"Perguntas fechadas também reduzem o não preenchimento.","refs":[{"c":18,"p":323,"p2":323,"s":"s18-1"}],"a":"V"},{"id":"c18-01.3","t":"A análise exploratória (descritiva) é a primeira etapa da análise e busca padrões em grandes volumes de dados.","e":"Tabelas são indicadas quando os valores importam; gráficos, para distribuições, tendências e relações.","refs":[{"c":18,"p":323,"p2":323,"s":"s18-1"}],"a":"V"},{"id":"c18-01.4","t":"Na análise univariada não é necessário verificar dados faltantes (missing values).","e":"A análise de cada variável deve incluir a identificação das não respostas.","refs":[{"c":18,"p":325,"p2":325,"s":"s18-2"}],"a":"F"},{"id":"c18-01.5","t":"Depois da análise univariada, fazem-se análises bivariadas e, depois, estratificadas por uma terceira variável.","e":"É a sequência sugerida no capítulo.","refs":[{"c":18,"p":325,"p2":325,"s":"s18-2"}],"a":"V"}],"cap":18,"title":"Elementos e variáveis"},{"id":"c18-02","src":"livro","type":"vf","items":[{"id":"c18-02.1","t":"Variáveis nominais têm categorias sem ordem, e códigos numéricos não têm significado aritmético, como sexo, diagnóstico (CID) e bairro.","e":"Com elas só se pode contar.","refs":[{"c":18,"p":324,"p2":324,"s":"s18-1"}],"a":"V"},{"id":"c18-02.2","t":"Variáveis ordinais têm categorias ordenadas, mas a distância entre elas não é mensurável, como grau de hipertensão, gravidade e escolaridade.","e":"Um paciente com gravidade 4 não é \"duas vezes\" mais grave que um com gravidade 2.","refs":[{"c":18,"p":324,"p2":324,"s":"s18-1"}],"a":"V"},{"id":"c18-02.3","t":"Na escala intervalar o zero é arbitrário, como na temperatura em °C.","e":"Por isso 20 °C não é \"o dobro\" de 10 °C.","refs":[{"c":18,"p":324,"p2":324,"s":"s18-1"}],"a":"V"},{"id":"c18-02.4","t":"Na escala de razão o zero indica ausência da característica, como em peso, idade e tempo, e faz sentido dizer que 70 kg é o dobro de 35 kg.","e":"Variáveis quantitativas são medidas em escala intervalar ou de razão.","refs":[{"c":18,"p":325,"p2":325,"s":"s18-2"}],"a":"V"},{"id":"c18-02.5","t":"Número de leitos e número de casos são exemplos de variáveis quantitativas contínuas.","e":"São discretas (contagens, valores inteiros). Pressão arterial e peso são contínuas.","refs":[{"c":18,"p":325,"p2":325,"s":"s18-2"}],"a":"F"}],"cap":18,"title":"Escalas de medida"},{"id":"c18-03","src":"livro","type":"vf","items":[{"id":"c18-03.1","t":"Uma tabela deve ser autoexplicativa, com título indicando conteúdo, local e época, e com a fonte logo abaixo.","e":"Tabelas são fechadas em cima e embaixo por linhas horizontais, sem linhas verticais nas laterais.","refs":[{"c":18,"p":325,"p2":325,"s":"s18-2"},{"c":18,"p":327,"p2":327,"s":"s18-2"}],"a":"V"},{"id":"c18-03.2","t":"A frequência percentual acumulada de uma categoria é a soma do seu percentual com os das categorias anteriores, e a última chega a 100%.","e":"Ela só faz sentido em variáveis com ordem (ordinais e quantitativas).","refs":[{"c":18,"p":327,"p2":327,"s":"s18-2"}],"a":"V"},{"id":"c18-03.3","t":"Na convenção \"800 |— 1.000\", o valor 800 está incluído na classe e o valor 1.000 não.","e":"Assim cada observação cai em uma única classe.","refs":[{"c":18,"p":328,"p2":328,"s":"s18-3"}],"a":"V"},{"id":"c18-03.4","t":"Existe uma fórmula obrigatória para definir o número e a amplitude das classes de uma distribuição de frequências.","e":"Há fórmulas sugeridas, mas não há regra fixa; as classes devem expressar faixas de interesse.","refs":[{"c":18,"p":328,"p2":328,"s":"s18-3"}],"a":"F"},{"id":"c18-03.5","t":"Diferenciam-se tabelas de quadros: os quadros têm bordas laterais e apresentação mais livre; as tabelas seguem normas mais rígidas.","e":"É uma distinção de padronização.","refs":[{"c":18,"p":325,"p2":325,"s":"s18-2"}],"a":"V"}],"cap":18,"title":"Tabelas e distribuição de frequências"},{"id":"c18-04","src":"livro","type":"vf","items":[{"id":"c18-04.1","t":"Moda é o valor mais frequente. Um conjunto pode ser amodal, unimodal, bimodal ou multimodal.","e":"Ex.: 1 2 3 6 6 9 10 10 é bimodal (6 e 10).","refs":[{"c":18,"p":329,"p2":329,"s":"s18-3"}],"a":"V"},{"id":"c18-04.2","t":"A média aritmética funciona como \"centro de gravidade\" (ponto de equilíbrio) dos dados.","e":"D = {1, 1, 4, 8, 10} tem média 24/5 = 4,8.","refs":[{"c":18,"p":329,"p2":329,"s":"s18-3"}],"a":"V"},{"id":"c18-04.3","t":"A mediana divide os dados ordenados em duas metades. Com n ímpar é o valor na posição (n + 1)/2; com n par, a média dos dois valores centrais.","e":"É preciso ordenar os dados antes.","refs":[{"c":18,"p":330,"p2":330,"s":"s18-3"}],"a":"V"},{"id":"c18-04.4","t":"A mediana é mais robusta que a média a valores extremos, e é preferível em distribuições fortemente assimétricas, como a renda.","e":"Trocar 1,30 m por 1,80 m mudou a média de 1,26 para 1,31 m, mas não a mediana.","refs":[{"c":18,"p":330,"p2":330,"s":"s18-3"}],"a":"V"},{"id":"c18-04.5","t":"Em distribuições simétricas sem valores atípicos, deve-se preferir a mediana à média, porque ela usa todas as observações.","e":"Nesse caso prefere-se a média: interpretação intuitiva e uso de todas as observações. A mediana não usa todos os valores.","refs":[{"c":18,"p":330,"p2":330,"s":"s18-3"}],"a":"F"}],"cap":18,"title":"Medidas de tendência central"},{"id":"c18-05","src":"livro","type":"vf","items":[{"id":"c18-05.1","t":"Os quartis Q1, Q2 e Q3 correspondem aos percentis 25, 50 e 75, e Q2 é a mediana.","e":"Os quintis dividem os dados em cinco partes (percentis 20, 40, 60, 80).","refs":[{"c":18,"p":330,"p2":330,"s":"s18-3"}],"a":"V"},{"id":"c18-05.2","t":"Com muitos valores repetidos, a mediana pode não representar bem o conjunto. Por exemplo, a mediana de filhos é 1 mesmo que só 15% das famílias tenham menos de 1 filho.","e":"Nesses casos a média ou a moda podem sintetizar melhor.","refs":[{"c":18,"p":330,"p2":330,"s":"s18-3"}],"a":"V"},{"id":"c18-05.3","t":"Nos pesos dos 48 recém-nascidos do exemplo do livro, Q1 = 700 g, mediana = 810 g e Q3 = 910 g.","e":"Q1 é a média do 12º e 13º valores; a mediana, do 24º e 25º; Q3, do 36º e 37º.","refs":[{"c":18,"p":330,"p2":331,"s":"s18-3"}],"a":"V"},{"id":"c18-05.4","t":"A distância interquartílica é a diferença entre o valor máximo e o mínimo.","e":"Essa é a amplitude total. A distância interquartílica é Q3 − Q1 e cobre os 50% centrais.","refs":[{"c":18,"p":331,"p2":331,"s":"s18-3"}],"a":"F"},{"id":"c18-05.5","t":"A amplitude total é fácil de calcular, mas muito sensível a valores atípicos, porque usa só os dois extremos.","e":"Por isso muitos trabalhos apresentam (mínimo; máximo) junto da medida central.","refs":[{"c":18,"p":331,"p2":331,"s":"s18-3"}],"a":"V"}],"cap":18,"title":"Quartis e percentis"},{"id":"c18-06","src":"livro","type":"vf","items":[{"id":"c18-06.1","t":"A soma dos desvios em relação à média é sempre zero; por isso usa-se o módulo (desvio médio absoluto) ou o quadrado (variância).","e":"O desvio médio simples não serve como medida de dispersão.","refs":[{"c":18,"p":332,"p2":332,"s":"s18-3"}],"a":"V"},{"id":"c18-06.2","t":"O desvio-padrão é a raiz quadrada da variância e tem a mesma unidade dos dados.","e":"A variância fica em unidade ao quadrado, o que dificulta a interpretação.","refs":[{"c":18,"p":333,"p2":333,"s":"s18-3"}],"a":"V"},{"id":"c18-06.3","t":"Para a variância de uma amostra divide-se por n − 1; para a da população, por n. A diferença pesa em amostras pequenas.","e":"É a nota do capítulo sobre o denominador.","refs":[{"c":18,"p":332,"p2":332,"s":"s18-3"}],"a":"V"},{"id":"c18-06.4","t":"Numa distribuição aproximadamente normal, cerca de 68% das observações ficam entre média ± 1 DP e 95% entre média ± 2 DP.","e":"Daí o uso comum de \"média ± DP\".","refs":[{"c":18,"p":333,"p2":333,"s":"s18-3"}],"a":"V"},{"id":"c18-06.5","t":"O coeficiente de variação tem a mesma unidade da variável e não serve para comparar variáveis diferentes.","e":"O CV = DP/média é adimensional (em geral em %) e serve justamente para comparar dispersões de grupos ou variáveis com ordens de grandeza diferentes.","refs":[{"c":18,"p":333,"p2":333,"s":"s18-3"}],"a":"F"}],"cap":18,"title":"Variância, desvio-padrão e CV"},{"id":"c18-07","src":"livro","type":"choice","ctx":["Quatro alunos tiveram estas notas no ano: A = 5, 5, 5, 5; B = 4, 4, 6, 6; C = 0, 5, 5, 10; D = 0, 0, 10, 10. Todos têm média 5."],"items":[{"id":"c18-07.1","t":"Qual aluno tem desvio-padrão zero?","e":"Sem variação: todas as notas de A são iguais à média.","refs":[{"c":18,"p":331,"p2":333,"s":"s18-3"}],"a":0},{"id":"c18-07.2","t":"Qual aluno tem a maior variância (25)?","e":"D: desvios de ±5, quadrados 25, média 25 (DP = 5, CV = 100%).","refs":[{"c":18,"p":332,"p2":333,"s":"s18-3"}],"a":3},{"id":"c18-07.3","t":"Em qual(is) aluno(s) a média é igual a 5?","e":"Todos têm média 5, o que mostra que medidas de centro sozinhas não descrevem um conjunto.","refs":[{"c":18,"p":331,"p2":331,"s":"s18-3"}],"a":4}],"cap":18,"title":"Cálculo: notas dos alunos","opts":["Aluno A","Aluno B","Aluno C","Aluno D","Todos iguais"]},{"id":"c18-08","src":"livro","type":"vf","items":[{"id":"c18-08.1","t":"O gráfico de setores (pizza) é indicado para mostrar a participação percentual de poucas categorias, nominais ou ordinais.","e":"A soma das fatias é 100%.","refs":[{"c":18,"p":334,"p2":334,"s":"s18-4"}],"a":"V"},{"id":"c18-08.2","t":"Gráficos de barras e colunas servem para variáveis nominais, ordinais, discretas com poucos valores e séries temporais com poucas datas.","e":"Exceto nesses casos com ordem natural, recomenda-se ordenar as colunas de forma decrescente.","refs":[{"c":18,"p":334,"p2":334,"s":"s18-4"}],"a":"V"},{"id":"c18-08.3","t":"O gráfico de linhas é adequado para séries temporais, mostrando tendência e periodicidade.","e":"Ex.: casos de Aids por ano.","refs":[{"c":18,"p":334,"p2":334,"s":"s18-4"}],"a":"V"},{"id":"c18-08.4","t":"No histograma, os retângulos devem ser separados por espaços, como no gráfico de colunas.","e":"No histograma os retângulos são contíguos, porque as classes são encadeadas.","refs":[{"c":18,"p":335,"p2":335,"s":"s18-4"}],"a":"F"},{"id":"c18-08.5","t":"O polígono de frequências é construído ligando os pontos médios das classes e é fechado com classes fictícias nas extremidades.","e":"O histograma, por sua vez, é construído a partir dos limites das classes.","refs":[{"c":18,"p":336,"p2":337,"s":"s18-4"}],"a":"V"}],"cap":18,"title":"Gráficos"},{"id":"c18-09","src":"livro","type":"vf","items":[{"id":"c18-09.1","t":"Se as classes têm amplitudes diferentes, a área (e não a altura) de cada retângulo deve ser proporcional à frequência.","e":"Divide-se a frequência pela amplitude (densidade). Sem isso o gráfico distorce, como no exemplo da Aids por idade.","refs":[{"c":18,"p":335,"p2":336,"s":"s18-4"}],"a":"V"},{"id":"c18-09.2","t":"Um histograma multimodal sugere que os dados vêm de duas ou mais populações diferentes.","e":"Há duas ou mais classes com frequência maior que as vizinhas.","refs":[{"c":18,"p":336,"p2":336,"s":"s18-4"}],"a":"V"},{"id":"c18-09.3","t":"Um histograma truncado, com queda abrupta de um lado, sugere censura dos dados.","e":"Só entraram dados que satisfaziam algum requisito.","refs":[{"c":18,"p":336,"p2":336,"s":"s18-4"}],"a":"V"},{"id":"c18-09.4","t":"No histograma assimétrico à esquerda, os valores se concentram à esquerda, com cauda longa à direita.","e":"No assimétrico à esquerda os valores se concentram à direita e a cauda fica à esquerda. O assimétrico à direita é o oposto.","refs":[{"c":18,"p":336,"p2":336,"s":"s18-4"}],"a":"F"},{"id":"c18-09.5","t":"Num histograma simétrico, os valores se concentram numa classe central e as frequências diminuem nos dois sentidos.","e":"Nesse caso média e mediana são próximas.","refs":[{"c":18,"p":336,"p2":336,"s":"s18-4"}],"a":"V"}],"cap":18,"title":"Histograma: formatos e classes desiguais"},{"id":"c18-10","src":"livro","type":"vf","items":[{"id":"c18-10.1","t":"O box plot mostra Q1, mediana e Q3 numa caixa, e as linhas (bigodes) costumam ir até 1,5 vez a distância interquartílica.","e":"Pontos além disso são considerados outliers.","refs":[{"c":18,"p":337,"p2":338,"s":"s18-5"}],"a":"V"},{"id":"c18-10.2","t":"No exemplo do comprimento dos recém-nascidos (Q1 = 35, Md = 38, Q3 = 39 cm), o limite superior é 39 + 1,5 × 4 = 45 cm.","e":"Valores acima de 45 cm aparecem como observações extremas.","refs":[{"c":18,"p":338,"p2":338,"s":"s18-5"}],"a":"V"},{"id":"c18-10.3","t":"Para duas variáveis categóricas usa-se a tabela de dupla entrada, e os subtotais das margens são os totais marginais.","e":"Os percentuais por linha permitem comparar grupos (ex.: óbito neonatal com e sem pré-natal).","refs":[{"c":18,"p":338,"p2":338,"s":"s18-5"}],"a":"V"},{"id":"c18-10.4","t":"O gráfico de barras de erro mostra, para cada categoria, a média ± desvio-padrão de uma variável quantitativa.","e":"O box plot também permite comparar distribuições entre categorias.","refs":[{"c":18,"p":340,"p2":341,"s":"s18-5"}],"a":"V"},{"id":"c18-10.5","t":"No diagrama de dispersão, uma nuvem de pontos ascendente indica relação inversa entre as variáveis.","e":"Uma nuvem ascendente indica relação direta (as duas variáveis crescem juntas), como peso e comprimento ao nascer.","refs":[{"c":18,"p":341,"p2":341,"s":"s18-5"}],"a":"F"}],"cap":18,"title":"Box plot e análise bivariada"},{"id":"c3-15","src":"livro","type":"vf","items":[{"id":"c3-15.1","t":"A proporção de óbitos por causas mal definidas (capítulo XVIII da CID-10) é usada como indicador da qualidade das informações do SIM.","e":"Valores de 4 a 6% são considerados aceitáveis. Em 2004 o Brasil tinha 12,4%, com Norte e Nordeste acima de 20%.","refs":[{"c":3,"p":49,"p2":50,"s":"s3-6"}],"a":"V"},{"id":"c3-15.2","t":"Os óbitos sem assistência médica (código R98) correspondiam a cerca de metade dos óbitos por causas mal definidas no Brasil em 2004.","e":"Isso também reflete a cobertura e a qualidade da assistência.","refs":[{"c":3,"p":50,"p2":50,"s":"s3-7"}],"a":"V"},{"id":"c3-15.3","t":"Diagnósticos como \"septicemia\", \"insuficiência cardíaca\" ou \"hepatopatia\", por estarem fora do capítulo XVIII, são sempre causas básicas bem definidas.","e":"São \"causas residuais\" ou diagnósticos incompletos (os \"lixões\" da CID). Pouco informam sobre a causa básica, embora fiquem fora do cap. XVIII.","refs":[{"c":3,"p":50,"p2":50,"s":"s3-7"}],"a":"F"},{"id":"c3-15.4","t":"Se a subenumeração de óbitos é homogênea entre as causas, as taxas por causa ficam subestimadas, mas a mortalidade proporcional não se altera.","e":"Se é heterogênea (falta mais em umas causas que em outras), as duas medidas ficam distorcidas.","refs":[{"c":3,"p":49,"p2":49,"s":"s3-6"}],"a":"V"},{"id":"c3-15.5","t":"A RIPSA, criada em 1996, reúne instituições como o Ministério da Saúde, a OPAS, o IBGE e a ABRASCO e publica anualmente os Indicadores e Dados Básicos (IDB).","e":"A matriz tem seis grupos: demográficos, socioeconômicos, mortalidade, morbidade e fatores de risco, recursos e cobertura.","refs":[{"c":3,"p":78,"p2":79,"s":"s3-13"}],"a":"V"}],"cap":3,"title":"Causas mal definidas e RIPSA"},{"id":"c2-open","src":"livro","type":"open","ctx":["Explique a diferença entre incidência e prevalência, como cada uma é calculada e para que serve. Discuta a relação entre incidência, prevalência e duração da doença, e o que acontece com a prevalência de uma doença crônica quando surge um tratamento que prolonga a vida sem curar."],"keys":["Incidência: casos novos num período, entre os que estavam sob risco no início. Pode ser taxa (casos/pessoa-tempo, velocidade, dimensão tempo⁻¹) ou incidência acumulada (proporção, risco num intervalo).","Prevalência: casos existentes (novos e antigos) num momento / população. É uma proporção estática, medida em estudos transversais.","Usos: a incidência serve para estudar risco e etiologia (estudos longitudinais); a prevalência, para planejar serviços. A prevalência é pouco adequada para etiologia, porque mistura risco com sobrevida.","Determinantes da prevalência: incidência, duração e migração. Em população estável, P/(1 − P) = TI × D, e P ≈ TI × D quando P é pequena.","Um tratamento que prolonga a vida sem curar aumenta a duração e, portanto, a prevalência, mesmo sem mudar a incidência. Só a prevenção primária reduz a incidência.","Exemplos: dengue (alta incidência, baixa prevalência) e hipertensão (o contrário). Malformação congênita é medida como prevalência ao nascer."],"cap":2,"pts":2.0,"title":"Incidência, prevalência e duração","refs":[{"c":2,"p":14,"p2":17,"s":"s2-1"},{"c":2,"p":21,"p2":22,"s":"s2-3"},{"c":2,"p":25,"p2":30,"s":"s2-5"}]},{"id":"c3-open","src":"livro","type":"open","ctx":["Um gestor quer comparar o nível de saúde de dois estados usando o coeficiente geral de mortalidade (CGM). Discuta os cuidados necessários: problemas do numerador e do denominador, o efeito da estrutura etária e as alternativas (padronização, indicadores específicos e outros indicadores do nível de saúde)."],"keys":["CGM = óbitos / população do meio do período × 1.000. É simples e só precisa do total de óbitos.","Numerador: sub-registro (subestima), evasão e invasão de óbitos (por isso usar a residência), causas mal definidas como sinal de qualidade.","Denominador: estimativas intercensitárias imprecisas. População subestimada superestima o CGM. Valores abaixo de 6 por 1.000 sugerem sub-registro.","O CGM é média ponderada das taxas por idade. Uma população mais jovem tem CGM menor sem ser necessariamente mais saudável (Brasil × Inglaterra).","Alternativas: padronização direta (população-padrão) ou indireta (RMP = O/E); comparar taxas específicas por idade; usar e0 (que não depende da estrutura etária), TMI, Swaroop-Uemura, APVP, mortalidade proporcional.","O coeficiente padronizado é hipotético e só serve para comparar."],"cap":3,"pts":2.0,"title":"Comparar mortalidade entre populações","refs":[{"c":3,"p":36,"p2":41,"s":"s3-2"},{"c":3,"p":57,"p2":57,"s":"s3-8"},{"c":3,"p":61,"p2":62,"s":"s3-9"}]},{"id":"c5-open","src":"livro","type":"open","ctx":["Uma escola municipal comunica dezenas de casos de diarreia e vômitos entre alunos, dois dias após uma festa. Descreva as etapas da investigação epidemiológica desse possível surto e como você testaria a hipótese sobre a fonte."],"keys":["Confirmar o diagnóstico (clínica, coleta de fezes e alimentos) e confirmar o surto (comparar com o esperado, a frequência habitual).","Definir caso: primeiro uma definição sensível, para dimensionar o surto; depois uma específica, para a análise.","Caracterizar por pessoa, lugar e tempo: curva epidêmica (fonte comum pontual; o pico corresponde à incubação média) para estimar a hora de exposição.","Formular hipóteses (alimento, água), fazer busca ativa de casos e coletar dados adicionais (alimentos consumidos).","Testar com taxas de ataque específicas por alimento (expostos × não expostos) ou com um estudo caso-controle.","Medidas de controle oportunas, notificação (surto é de notificação imediata), relatório final e divulgação (retroalimentação)."],"cap":5,"pts":2.0,"title":"Investigação de um surto","refs":[{"c":5,"p":112,"p2":117,"s":"s5-4"},{"c":4,"p":93,"p2":94,"s":"s4-4"},{"c":2,"p":22,"p2":22,"s":"s2-3"}]},{"id":"c8-open","src":"livro","type":"open","ctx":["Você quer investigar se o uso de agrotóxicos está associado à doença de Parkinson. Compare como seriam um estudo de coorte e um estudo caso-controle para essa pergunta (seleção, medidas, vantagens e limitações) e diga qual escolheria."],"keys":["Coorte: pessoas sem Parkinson classificadas pela exposição a agrotóxicos e acompanhadas para medir a incidência. Esquema completo, nível individual, longitudinal.","Caso-controle: casos de Parkinson e controles sem a doença, da mesma base populacional, comparados quanto à exposição passada (odds ratio). Esquema incompleto.","A coorte estabelece melhor a sequência temporal e permite medir incidência, mas para doença rara e de latência longa é cara e demorada (perdas de seguimento).","O caso-controle é eficiente para doenças raras e de latência longa, mas está sujeito a viés de memória e de seleção dos controles.","Um estudo ecológico (áreas agrícolas × taxas) só geraria hipóteses; um ensaio experimental seria antiético para um fator de risco.","Escolha justificada: em geral, caso-controle como primeiro passo, ou coorte histórica se houver registros de exposição."],"cap":8,"pts":2.0,"title":"Coorte × caso-controle","refs":[{"c":8,"p":174,"p2":174,"s":"s8-2"},{"c":8,"p":176,"p2":179,"s":"s8-3"}]},{"id":"x2-1","src":"caderno","type":"vf","ctx":["Em 1996, um estudo-piloto do projeto PAISQUA (NESC/UFRJ) estimou, ao longo de três meses, a proporção de pessoas de 1 a 59 anos com anticorpos para o vírus da hepatite A (VHA) em três áreas com diferentes condições de saneamento (Duque de Caxias e Ilha do Governador). Uma amostra aleatória teve uma alíquota de sangue colhida uma única vez."],"table":[["Área","Com anticorpos anti-VHA","Tamanho da amostra"],["RJ Colônia Z-10","79","386"],["DC Setor 111","92","362"],["DC Setor 112","138","349"]],"items":[{"id":"x2-1.1","t":"A medida de frequência adequada é a prevalência pontual (soroprevalência), pois cada pessoa foi examinada uma única vez.","e":"Os três meses de coleta são curtos o bastante para a prevalência não mudar. Ninguém foi acompanhado, então não há como medir casos novos (incidência).","refs":[{"c":2,"p":26,"p2":26,"s":"s2-5"},{"c":2,"p":29,"p2":29,"s":"s2-5"}],"a":"V"},{"id":"x2-1.2","t":"A soroprevalência no Setor 112 de Duque de Caxias foi de cerca de 39,5%, quase o dobro da observada na Colônia Z-10.","e":"138/349 = 39,5%; Z-10: 79/386 = 20,5%; Setor 111: 92/362 = 25,4%.","refs":[{"c":2,"p":26,"p2":26,"s":"s2-5"}],"a":"V"},{"id":"x2-1.3","t":"Como a soroprevalência mede infecção passada ou atual, ela tende a diminuir com a idade.","e":"É o contrário: a soropositividade dura a vida toda e se acumula. No Setor 112 foi de 12,9% (1-4 anos) a 95,5% (20 anos ou mais).","refs":[{"c":2,"p":28,"p2":29,"s":"s2-5"}],"a":"F"},{"id":"x2-1.4","t":"O salto da soroprevalência da faixa de 1-4 anos (12,9%) para a de 5-9 anos (44,4%) no Setor 112 sugere alta incidência de infecção pelo VHA nos primeiros anos de vida.","e":"Como P ≈ I × D e a duração (soropositividade) é permanente, a subida rápida nas idades jovens indica muitas infecções precoces, ligadas ao saneamento precário.","refs":[{"c":2,"p":28,"p2":28,"s":"s2-5"}],"a":"V"},{"id":"x2-1.5","t":"Esse desenho permite calcular a taxa de incidência de hepatite A em cada área.","e":"Sem seguimento não se conhecem os casos novos nem a pessoa-tempo. Só a prevalência pode ser estimada.","refs":[{"c":2,"p":15,"p2":15,"s":"s2-1"},{"c":2,"p":29,"p2":29,"s":"s2-5"}],"a":"F"}],"cap":2,"ex":"Cap. 2, ex. 1","cad":{"p":4,"p2":4},"title":"Soroprevalência de hepatite A (PAISQUA)"},{"id":"x2-2","src":"caderno","type":"vf","ctx":["Em 01/01/2006 havia 1.800 casos de tuberculose em tratamento num município da região metropolitana do Rio. Ao longo do ano, 300 casos novos foram notificados e 450 pacientes tiveram alta por cura. Todos foram tratados com o esquema I (6 meses). População estimada para 2006: 960.000 habitantes (suponha população estável)."],"items":[{"id":"x2-2.1","t":"A prevalência no início de 2006 era de cerca de 19 casos por 10.000 habitantes.","e":"1.800/960.000 = 0,19%.","refs":[{"c":2,"p":26,"p2":26,"s":"s2-5"}],"a":"V"},{"id":"x2-2.2","t":"A prevalência no fim de 2006 era de cerca de 17 casos por 10.000 habitantes.","e":"(1.800 + 300 − 450)/960.000 = 1.650/960.000 ≈ 0,17%.","refs":[{"c":2,"p":26,"p2":26,"s":"s2-5"}],"a":"V"},{"id":"x2-2.3","t":"A taxa de incidência de 2006 foi de cerca de 31 casos por 100.000 pessoas-ano.","e":"300/960.000 × 10⁵ = 31,25. A população estável do meio do ano aproxima as pessoas-ano. Excluir os 1.800 prevalentes do denominador quase não muda o valor (31,31).","refs":[{"c":2,"p":17,"p2":17,"s":"s2-2"},{"c":2,"p":20,"p2":21,"s":"s2-2"}],"a":"V"},{"id":"x2-2.4","t":"A prevalência caiu porque a duração da doença diminuiu ao longo de 2006.","e":"O tratamento e a duração não mudaram. A prevalência caiu porque saíram mais pessoas (450 curas) do que entraram (300 casos novos).","refs":[{"c":2,"p":27,"p2":28,"s":"s2-5"}],"a":"F"},{"id":"x2-2.5","t":"A prevalência de período de 2006 seria (1.800 − 450)/960.000.","e":"Prevalência de período = (casos no início + casos novos)/população = (1.800 + 300)/960.000.","refs":[{"c":2,"p":28,"p2":29,"s":"s2-5"}],"a":"F"}],"cap":2,"ex":"Cap. 2, ex. 2","cad":{"p":4,"p2":5},"title":"Tuberculose em um município"},{"id":"x2-3","src":"caderno","type":"vf","ctx":["Após um jantar comemorativo, 75 participantes foram entrevistados: 46 tiveram gastroenterite aguda (GEA) horas depois. Ingestão de alimentos (dados fictícios):"],"table":[["Alimento","Comeram: GEA/total","Não comeram: GEA/total"],["Presunto","29/46","17/29"],["Sorvete de baunilha","43/54","3/21"],["Bolo de chocolate","26/48","20/27"]],"items":[{"id":"x2-3.1","t":"A medida apropriada é a incidência acumulada (taxa de ataque), pois é uma coorte fixa, sem perdas e com período de incubação curto.","e":"Todos os 75 estavam sob risco desde o jantar e foram acompanhados até adoecer ou não.","refs":[{"c":2,"p":21,"p2":22,"s":"s2-3"},{"c":4,"p":93,"p2":93,"s":"s4-4"}],"a":"V"},{"id":"x2-3.2","t":"A incidência acumulada entre todos os participantes foi de cerca de 61%.","e":"46/75 = 61,3%.","refs":[{"c":2,"p":21,"p2":21,"s":"s2-3"}],"a":"V"},{"id":"x2-3.3","t":"O sorvete de baunilha é a fonte mais provável: a incidência entre quem comeu foi cerca de 5,6 vezes a de quem não comeu.","e":"43/54 = 79,6% contra 3/21 = 14,3%; razão ≈ 5,6. Presunto: 63,0% contra 58,6% (≈ 1,1).","refs":[{"c":2,"p":22,"p2":22,"s":"s2-3"},{"c":5,"p":117,"p2":117,"s":"s5-6"}],"a":"V"},{"id":"x2-3.4","t":"O bolo de chocolate também é suspeito, pois 26 dos que o comeram adoeceram.","e":"Quem não comeu o bolo adoeceu mais (74,1%) do que quem comeu (54,2%); razão ≈ 0,7. Olhar só o número absoluto engana.","refs":[{"c":2,"p":22,"p2":22,"s":"s2-3"},{"c":5,"p":117,"p2":117,"s":"s5-6"}],"a":"F"},{"id":"x2-3.5","t":"Num surto como este, por fonte comum pontual, a taxa de incidência por pessoa-tempo é a melhor medida.","e":"Com seguimento curto e completo de todos, a incidência acumulada (taxa de ataque) é a medida natural.","refs":[{"c":2,"p":22,"p2":22,"s":"s2-3"}],"a":"F"}],"cap":2,"ex":"Cap. 2, ex. 3","cad":{"p":5,"p2":5},"title":"Surto de gastroenterite após um jantar"},{"id":"x2-4","src":"caderno","type":"vf","ctx":["Um estudo de 5 anos acompanhou 20 pessoas para estimar a incidência da doença X. Elas entraram em anos diferentes (sempre no 1º dia do ano), algumas saíram por perda de seguimento e outras adoeceram (perdas e adoecimentos no meio do ano). No total, as 20 pessoas somaram 53 pessoas-ano sob risco e houve 5 casos novos. Os casos existentes no meio de cada ano foram: ano 1, 0 de 7 acompanhados; ano 2, 0 de 11; ano 3, 2 de 14; ano 4, 1 de 13; ano 5, 2 de 13."],"items":[{"id":"x2-4.1","t":"A taxa de incidência foi de cerca de 9,4 casos por 100 pessoas-ano.","e":"TI = 5/53 ≈ 0,094 caso por pessoa-ano.","refs":[{"c":2,"p":17,"p2":19,"s":"s2-2"}],"a":"V"},{"id":"x2-4.2","t":"A prevalência no 5º ano foi de cerca de 15%.","e":"2/13 ≈ 15,4%. Nos anos 1 e 2 foi zero, pois os casos só surgiram a partir do 3º ano.","refs":[{"c":2,"p":26,"p2":26,"s":"s2-5"}],"a":"V"},{"id":"x2-4.3","t":"Supondo que todos tivessem começado juntos (coorte fixa) e ignorando as perdas, a incidência acumulada em 5 anos seria 5/20 = 25%.","e":"É uma aproximação: as perdas não foram levadas em conta (o método atuarial as consideraria como meio período).","refs":[{"c":2,"p":21,"p2":22,"s":"s2-3"}],"a":"V"},{"id":"x2-4.4","t":"A taxa de incidência é uma estimativa direta do risco de adoecer em 5 anos.","e":"A TI mede a velocidade de surgimento de casos. Quem estima diretamente o risco é a incidência acumulada. Ainda assim, quanto maior a TI, maior o risco.","refs":[{"c":2,"p":21,"p2":21,"s":"s2-3"}],"a":"F"},{"id":"x2-4.5","t":"As prevalências anuais são medidas estáticas, que incluem casos novos e antigos existentes em cada momento.","e":"Diferem da TI (velocidade) e da IA (risco no período).","refs":[{"c":2,"p":26,"p2":26,"s":"s2-5"}],"a":"V"}],"cap":2,"ex":"Cap. 2, ex. 4","cad":{"p":5,"p2":6},"title":"Coorte dinâmica de 20 pessoas (5 anos)"},{"id":"x2-5","src":"caderno","type":"vf","ctx":["Num ano, a fábrica A teve 40 acidentes de trabalho e a B teve 60. Cada uma tinha 1.000 empregados. Na B, todos trabalharam 12 meses. Na A, 100 trabalharam 12 meses, 200 trabalharam 9 meses, 500 trabalharam 6 meses e 200 trabalharam 3 meses (dados fictícios)."],"items":[{"id":"x2-5.1","t":"A medida mais adequada é a taxa de incidência, porque o tempo de exposição dos trabalhadores da fábrica A foi variável.","e":"É preciso considerar a pessoa-tempo, não só o número de empregados.","refs":[{"c":2,"p":17,"p2":17,"s":"s2-2"}],"a":"V"},{"id":"x2-5.2","t":"A fábrica A acumulou 550 pessoas-ano de exposição.","e":"100 × 1 + 200 × 0,75 + 500 × 0,5 + 200 × 0,25 = 100 + 150 + 250 + 50 = 550.","refs":[{"c":2,"p":17,"p2":18,"s":"s2-2"}],"a":"V"},{"id":"x2-5.3","t":"A taxa de incidência na fábrica A (cerca de 72,7 por 1.000 pessoas-ano) é maior que na B (60 por 1.000 pessoas-ano).","e":"40/550 × 1.000 ≈ 72,7 e 60/1.000 × 1.000 = 60. O risco é maior em A, apesar de ela ter menos acidentes.","refs":[{"c":2,"p":17,"p2":17,"s":"s2-2"}],"a":"V"},{"id":"x2-5.4","t":"Como teve mais acidentes, a fábrica B oferece maior risco a seus trabalhadores.","e":"Números absolutos não comparam risco: falta o denominador (tempo de exposição).","refs":[{"c":2,"p":16,"p2":16,"s":"s2-2"}],"a":"F"},{"id":"x2-5.5","t":"A incidência acumulada (40/1.000 e 60/1.000) seria a medida correta aqui, porque o número de empregados é igual nas duas fábricas.","e":"Com tempos de exposição diferentes, a IA não compara bem. Por isso se usa a pessoa-tempo.","refs":[{"c":2,"p":17,"p2":17,"s":"s2-2"},{"c":2,"p":21,"p2":21,"s":"s2-3"}],"a":"F"}],"cap":2,"ex":"Cap. 2, ex. 5","cad":{"p":6,"p2":6},"title":"Acidentes de trabalho em duas fábricas"},{"id":"x2-6","src":"caderno","type":"vf","ctx":["Em 1995 noticiou-se: \"Cólera: o Brasil é o segundo no mundo\". O Zaire teve cerca de 58 mil casos (4.181 óbitos) e o Brasil cerca de 50 mil casos (544 óbitos)."],"items":[{"id":"x2-6.1","t":"Com esses dados podemos afirmar que a taxa de incidência de cólera no Zaire foi maior que no Brasil.","e":"Faltam as populações. É preciso calcular casos/população × 100.000 em cada país para comparar.","refs":[{"c":2,"p":16,"p2":16,"s":"s2-2"},{"c":2,"p":17,"p2":17,"s":"s2-2"}],"a":"F"},{"id":"x2-6.2","t":"A gravidade da cólera, medida pela letalidade, foi maior no Zaire.","e":"Zaire: 4.181/58.000 ≈ 7,2%; Brasil: 544/50.000 ≈ 1,1%.","refs":[{"c":2,"p":25,"p2":25,"s":"s2-5"}],"a":"V"},{"id":"x2-6.3","t":"Se a letalidade do sarampo numa comunidade foi de 10% em 1994 e houve 50 óbitos, ocorreram 500 casos.","e":"Letalidade = óbitos/casos; logo, casos = 50/0,10 = 500.","refs":[{"c":2,"p":25,"p2":25,"s":"s2-5"}],"a":"V"},{"id":"x2-6.4","t":"A letalidade da cólera no Brasil (cerca de 1%) indica que o risco de adoecer de cólera era baixo no país.","e":"Letalidade mede a gravidade entre os doentes, não o risco de adoecer (incidência).","refs":[{"c":2,"p":25,"p2":25,"s":"s2-5"}],"a":"F"},{"id":"x2-6.5","t":"Letalidade e mortalidade são sinônimos.","e":"O denominador da mortalidade é a população toda; o da letalidade, apenas os doentes.","refs":[{"c":2,"p":24,"p2":25,"s":"s2-4"}],"a":"F"}],"cap":2,"ex":"Cap. 2, ex. 6 e 7","cad":{"p":6,"p2":6},"title":"Cólera no Zaire e no Brasil; letalidade do sarampo"},{"id":"x2-7","src":"caderno","type":"vf","ctx":["Considere uma coorte fixa de pessoas infectadas pelo HIV no mesmo ano. Sem tratamento, elas passam por: infecção (T0) → Aids (T1) → óbito (T2). Avalie o efeito, a curto prazo, de medicamentos que alterem esses intervalos (P = I × D)."],"items":[{"id":"x2-7.1","t":"Se a droga aumentar o período de incubação (T0 a T1) sem mudar a sobrevida com Aids, aumenta o número de infectados assintomáticos e diminuem os casos novos de Aids.","e":"Menos pessoas progridem para Aids no período; com menos casos novos, a curto prazo também caem os casos prevalentes e os óbitos por Aids.","refs":[{"c":2,"p":27,"p2":28,"s":"s2-5"}],"a":"V"},{"id":"x2-7.2","t":"Se a droga aumentar a sobrevida com Aids (T1 a T2) sem mudar a incubação, a incidência de Aids não muda, mas a prevalência de Aids aumenta.","e":"A duração aumenta e os óbitos diminuem. Os infectados assintomáticos não mudam.","refs":[{"c":2,"p":27,"p2":28,"s":"s2-5"}],"a":"V"},{"id":"x2-7.3","t":"Se a droga aumentar a incubação e a sobrevida, o efeito sobre a prevalência de Aids é indeterminado.","e":"Há menos casos novos (pressiona a prevalência para baixo) e maior duração (pressiona para cima). O resultado depende do balanço entre os dois.","refs":[{"c":2,"p":27,"p2":28,"s":"s2-5"}],"a":"V"},{"id":"x2-7.4","t":"Um tratamento que evita a morte mas não cura não altera a incidência, mas aumenta a prevalência.","e":"Aumenta a duração, e P ≈ I × D.","refs":[{"c":2,"p":27,"p2":28,"s":"s2-5"}],"a":"V"},{"id":"x2-7.5","t":"Se a doença for transmissível e o tratamento não reduzir a infectividade, o aumento da duração pode também aumentar a incidência.","e":"Doentes vivendo mais tempo e ainda infectantes geram mais casos novos.","refs":[{"c":2,"p":27,"p2":28,"s":"s2-5"}],"a":"V"}],"cap":2,"ex":"Cap. 2, ex. 8 e 9","cad":{"p":6,"p2":7},"title":"Antirretrovirais, incidência e prevalência"},{"id":"x3-1","src":"caderno","type":"vf","ctx":["População e óbitos por faixa etária, Brasil e EUA, 1994 (SIM/DATASUS, CDC). Coeficientes de mortalidade (CM) por 1.000 habitantes."],"table":[["Faixa etária","Brasil %pop","Brasil CM","EUA %pop","EUA CM"],["0 a 4","11,3","6,0","7,6","2,0"],["5 a 19","33,7","0,6","21,2","0,4"],["20 a 44","37,2","2,6","38,9","1,8"],["45 a 64","13,0","10,3","19,5","7,4"],["65 e mais","4,8","52,7","12,7","50,1"],["Total (CGM)","100","5,7","100","8,8"]],"items":[{"id":"x3-1.1","t":"O CGM bruto dos EUA (8,8 por 1.000) foi maior que o do Brasil (5,7 por 1.000), mesmo considerando um sub-registro de 10-20% no Brasil.","e":"878.430/153.219.855 × 1.000 = 5,7; 2.278.580/260.340.990 × 1.000 = 8,8.","refs":[{"c":3,"p":36,"p2":37,"s":"s3-2"}],"a":"V"},{"id":"x3-1.2","t":"Todos os coeficientes específicos por idade do Brasil foram maiores que os dos EUA.","e":"Isso indica condições de saúde piores no Brasil, ao contrário do que os CGM brutos sugerem.","refs":[{"c":3,"p":38,"p2":39,"s":"s3-3"}],"a":"V"},{"id":"x3-1.3","t":"A população brasileira era mais jovem: menores de 19 anos eram 45% (EUA: 28,8%) e idosos de 65+ eram 4,8% (EUA: 12,7%).","e":"A estrutura etária confunde a comparação dos CGM brutos.","refs":[{"c":3,"p":38,"p2":38,"s":"s3-3"}],"a":"V"},{"id":"x3-1.4","t":"Padronizando pelo método direto, com a população brasileira de 1994 como padrão, o CGM dos EUA cai para cerca de 4,4 por 1.000, abaixo do CGM do Brasil (5,7).","e":"Aplicando as taxas dos EUA à população brasileira, os óbitos esperados somam 674.626, e 674.626/153.219.855 × 1.000 ≈ 4,4.","refs":[{"c":3,"p":38,"p2":40,"s":"s3-3"}],"a":"V"},{"id":"x3-1.5","t":"Na padronização direta usando o Brasil como padrão, também é preciso padronizar o CGM do Brasil.","e":"O Brasil é a própria população-padrão: seu CGM bruto já é o padronizado.","refs":[{"c":3,"p":40,"p2":40,"s":"s3-3"}],"a":"F"},{"id":"x3-1.6","t":"Em ambos os países a menor taxa específica está na faixa de 0 a 4 anos.","e":"Os menores coeficientes estão na faixa de 5 a 19 anos. A de 0 a 4 é mais alta por causa da mortalidade no 1º ano.","refs":[{"c":3,"p":39,"p2":39,"s":"s3-3"}],"a":"F"}],"cap":3,"ex":"Cap. 3, ex. 1","cad":{"p":12,"p2":13},"title":"Brasil × EUA (1994): CGM e padronização"},{"id":"x3-2","src":"caderno","type":"vf","ctx":["As curvas de mortalidade proporcional (Nelson de Moraes) do estado do Rio de Janeiro nos triênios 1979-81, 1990-92 e 1999-2001 têm formato próximo de um \"J\": a proporção de óbitos em menores de 1 ano caiu, de cerca de 17% para cerca de 5%, e a de 50 anos ou mais subiu."],"items":[{"id":"x3-2.1","t":"Ao longo dos três triênios, as curvas se aproximaram do tipo de nível de saúde mais elevado (formato em J).","e":"Em 1979-81 a curva sugeria transição entre o nível \"regular\" (U) e o \"elevado\" (J); em 1999-2001 estava mais próxima de J.","refs":[{"c":3,"p":59,"p2":60,"s":"s3-8"}],"a":"V"},{"id":"x3-2.2","t":"A queda da mortalidade proporcional em menores de 1 ano e de 1 a 4 anos, com aumento na faixa de 50+, indica melhora das condições de saúde.","e":"Os óbitos passam a ocorrer em idades mais avançadas, em parte pela queda da mortalidade infantil.","refs":[{"c":3,"p":59,"p2":60,"s":"s3-8"}],"a":"V"},{"id":"x3-2.3","t":"Os valores aproximados do indicador de Swaroop-Uemura no ERJ foram 55%, 64% e 70% nos três triênios, o que é compatível com aumento da esperança de vida.","e":"O indicador é a proporção de óbitos de pessoas com 50 anos ou mais.","refs":[{"c":3,"p":57,"p2":58,"s":"s3-8"}],"a":"V"},{"id":"x3-2.4","t":"O indicador de Swaroop-Uemura exige estimativas populacionais por faixa etária.","e":"Ele só usa óbitos (proporção com 50+). Por isso é fácil de calcular e de comparar.","refs":[{"c":3,"p":57,"p2":57,"s":"s3-8"},{"c":3,"p":59,"p2":59,"s":"s3-8"}],"a":"F"},{"id":"x3-2.5","t":"Uma curva de Nelson de Moraes em \"J invertido\" (predomínio de óbitos infantis e pré-escolares) indica bom nível de saúde.","e":"Indica nível de saúde baixo. O \"J\" (óbitos concentrados em idades avançadas) é o melhor nível.","refs":[{"c":3,"p":60,"p2":60,"s":"s3-9"}],"a":"F"}],"cap":3,"ex":"Cap. 3, ex. 2","cad":{"p":13,"p2":14},"title":"Nelson de Moraes e Swaroop-Uemura no estado do RJ"},{"id":"x3-3","src":"caderno","type":"vf","ctx":["(1) No município do Rio de Janeiro, de 1980 a 1994, a mortalidade infantil (MI) caiu de cerca de 45 para cerca de 30 por 1.000 NV, com ligeira alta no início dos anos 1990. Já a mortalidade infantil por causas redutíveis pela melhor assistência à gravidez e ao parto (MIR) ficou praticamente constante, em torno de 8 por 1.000. (2) Em Niterói, de 1981 a 1993, a MI caiu de 43,4 para 25,9 por 1.000 NV. A razão de mortalidade materna oscilou muito (de 1,0 a 8,0 por 10.000 NV, sem nenhum óbito materno registrado em 1987). Após investigação hospitalar e domiciliar de óbitos de mulheres em idade reprodutiva, as razões de 1992 e 1993 passaram de 5,3 para 9,3 e de 9,8 para 15,5 por 10.000 NV."],"items":[{"id":"x3-3.1","t":"No Rio, a queda da MI não pode ser creditada principalmente às causas evitáveis pela assistência à gravidez e ao parto.","e":"A MIR ficou quase constante. A queda veio sobretudo das causas pós-neonatais: diarreia, desnutrição e imunopreveníveis.","refs":[{"c":3,"p":51,"p2":52,"s":"s3-7"},{"c":3,"p":55,"p2":55,"s":"s3-7"}],"a":"V"},{"id":"x3-3.2","t":"A queda da mortalidade infantil em Niterói foi provavelmente maior no componente pós-neonatal.","e":"Políticas sociais, saneamento, atenção primária e queda da fecundidade reduzem rápido as causas evitáveis ligadas ao ambiente.","refs":[{"c":3,"p":52,"p2":52,"s":"s3-7"}],"a":"V"},{"id":"x3-3.3","t":"A grande oscilação das razões de mortalidade materna em Niterói indica pouca fidedignidade da informação.","e":"A investigação aumentou as razões porque recuperou óbitos maternos não declarados.","refs":[{"c":3,"p":47,"p2":48,"s":"s3-5"}],"a":"V"},{"id":"x3-3.4","t":"O sub-registro de óbitos maternos pode decorrer do desconhecimento do declarante sobre a causa básica e do receio de implicações para o estabelecimento (descredenciamento, imagem, processos).","e":"São causas apontadas no gabarito do caderno.","refs":[{"c":3,"p":47,"p2":48,"s":"s3-5"}],"a":"V"},{"id":"x3-3.5","t":"O aumento da razão de mortalidade materna após a investigação prova que as mortes maternas aumentaram em 1992-1993.","e":"Ele reflete sobretudo a melhora do registro (óbitos recuperados), não necessariamente mais mortes.","refs":[{"c":3,"p":47,"p2":48,"s":"s3-5"}],"a":"F"}],"cap":3,"ex":"Cap. 3, ex. 3 e 4","cad":{"p":14,"p2":14},"title":"Mortalidade infantil e materna (Rio de Janeiro e Niterói)"},{"id":"x4-1","src":"caderno","type":"vf","ctx":["(1) Um mapa da OMS de 2004 mostrava os países com poliovírus selvagem nativo, os com transmissão restabelecida, os com casos importados e os livres do vírus. (2) Entre pessoas de 25 a 44 anos nos EUA, a taxa de mortalidade por infecção pelo HIV subiu de quase zero em 1982 para cerca de 38 por 100 mil em 1994, ultrapassando acidentes, câncer e doenças cardíacas."],"items":[{"id":"x4-1.1","t":"Segundo o gabarito do caderno, sem dados de incidência de anos anteriores não é possível afirmar que um único caso de pólio selvagem na China em 2004 configure epidemia.","e":"É preciso saber o esperado (a incidência habitual) para julgar um excesso. (Na prática, em área livre há muitos anos, um caso autóctone já seria tratado como epidemia.)","refs":[{"c":4,"p":92,"p2":92,"s":"s4-4"},{"c":4,"p":95,"p2":95,"s":"s4-5"}],"a":"V"},{"id":"x4-1.2","t":"Para julgar se a incidência de 2004 foi epidêmica, pode-se construir um diagrama de controle com os 10 anos anteriores, descartando os anos epidêmicos.","e":"Pela distribuição normal (média ± 1,96 DP) ou pelos quartis (acima do 3º quartil = epidêmico).","refs":[{"c":4,"p":95,"p2":97,"s":"s4-5"}],"a":"V"},{"id":"x4-1.3","t":"O aumento da mortalidade por HIV em adultos jovens nos EUA de 1982 a 1994 se explica pela alta incidência da infecção e pela alta letalidade na época.","e":"Mortalidade = incidência × letalidade, antes da terapia antirretroviral eficaz.","refs":[{"c":2,"p":25,"p2":25,"s":"s2-5"},{"c":6,"p":135,"p2":135,"s":"s6-4"}],"a":"V"},{"id":"x4-1.4","t":"No diagrama de controle por quartis, valores entre o 1º e o 3º quartil indicam situação epidêmica.","e":"A faixa entre Q1 e Q3 é o esperado. Só valores acima do 3º quartil são considerados epidêmicos.","refs":[{"c":4,"p":96,"p2":96,"s":"s4-5"}],"a":"F"}],"cap":4,"ex":"Cap. 4, ex. 1 e 2","cad":{"p":18,"p2":18},"title":"Poliomielite na China e Aids nos EUA"},{"id":"x4-2","src":"caderno","type":"vf","ctx":["Incidência mensal de dengue no município do Rio de Janeiro (por 100 mil hab.). Os anos não epidêmicos 1988, 1989, 1993 e 1994 foram usados como base. Novembro nesses anos: 0,04; 0,08; 0,16; 0,24. Dezembro: 0,12; 0,08; 0,20; 0,69. Médias (DP) de janeiro e fevereiro: 0,51 (0,33) e 0,24 (0,23). Em 1998 as incidências de janeiro a abril foram 2,12; 2,41; 44,74 e 128,88; no fim de 1997 (outubro a dezembro) ficaram acima do limite máximo."],"items":[{"id":"x4-2.1","t":"A média de novembro nos anos não epidêmicos é cerca de 0,13 por 100 mil, com desvio-padrão de cerca de 0,09.","e":"(0,04 + 0,08 + 0,16 + 0,24)/4 = 0,13.","refs":[{"c":4,"p":95,"p2":95,"s":"s4-5"},{"c":18,"p":329,"p2":333,"s":"s18-3"}],"a":"V"},{"id":"x4-2.2","t":"O limite máximo esperado para janeiro é cerca de 1,16 por 100 mil (média + 1,96 DP), e a incidência de janeiro de 1998 (2,12) o ultrapassou.","e":"0,51 + 1,96 × 0,33 ≈ 1,16.","refs":[{"c":4,"p":95,"p2":96,"s":"s4-5"}],"a":"V"},{"id":"x4-2.3","t":"Como a incidência ficou acima do limite máximo por vários meses seguidos (janeiro de 1998 foi o 4º), a epidemia de 1998 começou, na verdade, no último trimestre de 1997.","e":"O diagrama de controle detecta a elevação antes do pico (março e abril de 1998).","refs":[{"c":4,"p":95,"p2":97,"s":"s4-5"}],"a":"V"},{"id":"x4-2.4","t":"Para construir o diagrama de controle, deveriam ser usados todos os anos de 1986 a 1996, inclusive os epidêmicos (1986, 1987, 1991).","e":"Anos epidêmicos devem ser excluídos. Senão os limites sobem e o diagrama deixa de detectar epidemias.","refs":[{"c":4,"p":95,"p2":95,"s":"s4-5"}],"a":"F"},{"id":"x4-2.5","t":"Epidemia é uma elevação inesperada e acima do limiar esperado dos coeficientes de incidência, delimitada no tempo e no espaço e provocada por mudanças na estrutura epidemiológica (agente, hospedeiro, ambiente).","e":"É a definição dada no gabarito do caderno.","refs":[{"c":4,"p":92,"p2":92,"s":"s4-4"}],"a":"V"}],"cap":4,"ex":"Cap. 4, ex. 3","cad":{"p":18,"p2":19},"title":"Diagrama de controle da dengue no Rio (1997-1998)"},{"id":"x4-3","src":"caderno","type":"vf","ctx":["(1) Razões de mortalidade padronizadas (japoneses não-migrantes = 100), 1959-62: câncer de estômago em homens: migrantes nascidos fora dos EUA 72, nascidos nos EUA 38, norte-americanos brancos 17; câncer de cólon em homens: 374, 288, 489; câncer de mama: 166, 136, 591. (2) No município do Rio, a diarreia infantil tem dois picos por ano (verão chuvoso e meses secos); em 15 anos a mortalidade caiu, mantendo o perfil mensal."],"items":[{"id":"x4-3.1","t":"Para os cânceres de estômago e de cólon, os migrantes japoneses ficaram em posição intermediária entre os japoneses não-migrantes e os norte-americanos brancos.","e":"Isso aponta para fatores ambientais (incluindo hábitos alimentares e culturais) com longos períodos de indução.","refs":[{"c":4,"p":87,"p2":87,"s":"s4-3"}],"a":"V"},{"id":"x4-3.2","t":"No câncer de mama, as migrantes ficaram mais próximas das japonesas não-migrantes, o que sugere maior peso de fatores genéticos.","e":"O caderno ressalva que se trata de uma só geração: pode não ter havido tempo para mudar os hábitos ligados ao câncer de mama.","refs":[{"c":4,"p":87,"p2":87,"s":"s4-3"}],"a":"V"},{"id":"x4-3.3","t":"Como as taxas dos migrantes não se igualaram às dos norte-americanos brancos, os estudos de migrantes descartam qualquer papel do ambiente.","e":"O deslocamento das taxas na direção do novo país indica efeito ambiental. Não chegar ao mesmo nível só mostra que a genética não está descartada.","refs":[{"c":4,"p":87,"p2":87,"s":"s4-3"}],"a":"F"},{"id":"x4-3.4","t":"Os dois picos anuais de diarreia infantil (verão e meses secos) correspondem a uma variação sazonal.","e":"São oscilações periódicas dentro de um ano.","refs":[{"c":4,"p":90,"p2":91,"s":"s4-3"}],"a":"V"},{"id":"x4-3.5","t":"A queda da mortalidade por diarreia em 15 anos foi identificada pela análise da série histórica (tendência).","e":"É a observação de longo prazo, em geral mais de 10 anos.","refs":[{"c":4,"p":88,"p2":88,"s":"s4-3"}],"a":"V"}],"cap":4,"ex":"Cap. 4, ex. 4 e 5","cad":{"p":19,"p2":19},"title":"Migrantes japoneses e diarreia infantil"},{"id":"x5-1","src":"caderno","type":"vf","ctx":["Em janeiro de 1993, um gastroenterologista pediátrico avisou o Departamento de Saúde de Washington (EUA) sobre mais casos de diarreia sanguinolenta e 3 crianças com síndrome hemolítico-urêmica (SHU) em Seattle. Suspeitou-se de E. coli O157:H7 (incubação de 3 a 8 dias; carne mal cozida, leite não pasteurizado). Definição de caso: diarreia com cultura de fezes positiva para O157:H7, ou SHU após diarreia, de 1/12/1992 a 28/2/1993, em residentes do estado. Em 15/1 começou a busca ativa e em 18/1 o surto foi divulgado ao público. (Bell et al., JAMA 1994)"],"items":[{"id":"x5-1.1","t":"Exigir cultura de fezes positiva aumenta a especificidade da definição de caso e reduz erros de classificação.","e":"Isso facilita identificar a fonte, porque exclui diarreias não relacionadas ao surto.","refs":[{"c":5,"p":117,"p2":117,"s":"s5-6"}],"a":"V"},{"id":"x5-1.2","t":"A exigência de cultura reduz a sensibilidade: exclui quem não procurou atendimento ou não fez exame, e os casos incluídos podem ser diferentes do conjunto dos casos do surto.","e":"É o preço da especificidade.","refs":[{"c":5,"p":114,"p2":114,"s":"s5-5"},{"c":5,"p":117,"p2":117,"s":"s5-6"}],"a":"V"},{"id":"x5-1.3","t":"Um período longo (três meses) na definição de caso pode incluir casos secundários (pessoa a pessoa) e dificultar a identificação da fonte inicial.","e":"Restringir a residentes do estado também pode excluir visitantes infectados e surtos em outros estados.","refs":[{"c":5,"p":117,"p2":117,"s":"s5-6"}],"a":"V"},{"id":"x5-1.4","t":"A ampla divulgação aumenta a sensibilidade do sistema, mas pode gerar alarme, aumentar sem necessidade a procura por atendimento e levar à notificação indevida de casos.","e":"São as vantagens e desvantagens apontadas no gabarito.","refs":[{"c":5,"p":113,"p2":114,"s":"s5-4"}],"a":"V"},{"id":"x5-1.5","t":"No início de uma investigação de surto, deve-se usar sempre a definição de caso mais específica possível.","e":"Em geral começa-se com uma definição mais sensível, para dimensionar o surto, e ganha-se especificidade à medida que a investigação avança.","refs":[{"c":5,"p":117,"p2":117,"s":"s5-6"}],"a":"F"}],"cap":5,"ex":"Cap. 5 (surto de E. coli O157:H7)","cad":{"p":23,"p2":23},"title":"Surto de E. coli O157:H7: definição de caso e divulgação"},{"id":"x5-2","src":"caderno","type":"vf","ctx":["De 37 pacientes entrevistados, 27 (73%) tinham comido hambúrgueres em lojas da rede A nos 10 dias anteriores. Fez-se então um caso-controle com os 16 primeiros pacientes e 16 controles saudáveis indicados pelos próprios pacientes (amigos ou parentes sem diarreia)."],"table":[["Exposição","Casos (%)","Controles (%)","p"],["Rede A","12/16 (75)","0/16 (0)","< 0,05"],["Rede B","3/15 (20)","3/15 (20)","NS"],["Carne de porco","1/9 (11)","7/9 (79)","< 0,05"],["Frango","11/14 (79)","11/14 (79)","NS"]],"items":[{"id":"x5-2.1","t":"Saber que 73% dos pacientes comeram na rede A já basta para incriminá-la como fonte.","e":"Essa frequência pode ser parecida com a da população em geral que não adoeceu. É preciso um grupo de comparação, como num estudo caso-controle.","refs":[{"c":5,"p":117,"p2":117,"s":"s5-6"},{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":"F"},{"id":"x5-2.2","t":"Usar amigos ou parentes como controles facilita o recrutamento, mas pode causar \"superpareamento\", em que casos e controles têm hábitos tão parecidos que a diferença de exposição some.","e":"Também aumenta o risco de quebra de confidencialidade.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"},{"c":5,"p":117,"p2":117,"s":"s5-6"}],"a":"V"},{"id":"x5-2.3","t":"Controles escolhidos entre outros pacientes do mesmo médico evitam o superpareamento, mas perdem representatividade, porque pessoas doentes podem ter hábitos diferentes dos da população.","e":"Outra opção são os vizinhos, mais comparáveis, porém com custo e logística maiores.","refs":[{"c":8,"p":176,"p2":176,"s":"s8-3"},{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":"V"},{"id":"x5-2.4","t":"Possíveis explicações para 4 dos 16 casos não referirem a rede A: esquecimento, consumo em casa ou no trabalho de comida comprada lá, ou serem casos secundários.","e":"O viés de memória é uma limitação típica do caso-controle.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":"V"},{"id":"x5-2.5","t":"Visitar as lanchonetes para verificar o preparo (os hambúrgueres ficavam abaixo dos 68,3 °C recomendados) e comparar as cepas por técnicas moleculares (PFGE) ajudaram a confirmar a fonte.","e":"Isso mostra a combinação de epidemiologia, ambiente e laboratório na investigação.","refs":[{"c":5,"p":112,"p2":113,"s":"s5-4"},{"c":5,"p":117,"p2":117,"s":"s5-6"}],"a":"V"}],"cap":5,"ex":"Cap. 5 (surto de E. coli O157:H7)","cad":{"p":23,"p2":24},"title":"Surto de E. coli O157:H7: estudo caso-controle"},{"id":"x6-1","src":"caderno","type":"vf","ctx":["(1) Pirâmides do Brasil em 1970 (base larga) e 2000 (base estreitada: as faixas de 0-4 e 5-9 anos menores que as de 10-19). (2) Em 2000, a pirâmide da população com rendimento domiciliar per capita de até 0,5 salário mínimo tinha base larga; a de 1 SM ou mais tinha forma de \"barril\". (3) O índice de envelhecimento (pessoas com 65+ / pessoas de 0-14 × 100) em 2000 foi 47,75 em Niterói e 13,86 em Teresina."],"items":[{"id":"x6-1.1","t":"A pirâmide de 2000 reflete a queda da mortalidade somada a uma queda importante e relativamente recente da fecundidade, que estreitou a base.","e":"Há menos menores de 15 anos e mais adultos e idosos, numa \"forma de barril\".","refs":[{"c":6,"p":129,"p2":132,"s":"s6-3"}],"a":"V"},{"id":"x6-1.2","t":"A dinâmica populacional resulta de duas variáveis biológicas (mortalidade e fecundidade) e de uma não biológica (migração).","e":"Entre 1870 e 1930 a migração internacional pesou no Brasil; depois de 1930, a queda da mortalidade passou a ditar o crescimento.","refs":[{"c":6,"p":126,"p2":130,"s":"s6-2"}],"a":"V"},{"id":"x6-1.3","t":"A população mais pobre (até 0,5 SM per capita) ainda não mostrava envelhecimento: sua pirâmide de base larga é a de uma população em crescimento.","e":"Já a pirâmide de quem tem 1 SM ou mais, em barril, é a de uma população estabilizada, parecida com a do Brasil de 2000.","refs":[{"c":6,"p":146,"p2":146,"s":"s6-6"},{"c":6,"p":132,"p2":132,"s":"s6-4"}],"a":"V"},{"id":"x6-1.4","t":"O índice de envelhecimento bem maior de Niterói indica uma transição demográfica em estágio mais avançado que a de Teresina.","e":"Ele é a razão entre os grupos etários extremos (idosos e jovens).","refs":[{"c":6,"p":131,"p2":131,"s":"s6-3"}],"a":"V"},{"id":"x6-1.5","t":"O envelhecimento observado em 2000 se deve principalmente ao aumento da natalidade a partir dos anos 1970.","e":"A natalidade caiu a partir dos anos 1970. O envelhecimento se deve sobretudo à queda da fecundidade.","refs":[{"c":6,"p":129,"p2":131,"s":"s6-3"}],"a":"F"}],"cap":6,"ex":"Cap. 6, ex. 1 a 3","cad":{"p":28,"p2":28},"title":"Pirâmides, renda e índice de envelhecimento"},{"id":"x6-2","src":"caderno","type":"vf","ctx":["Esperança de vida ao nascer (EVN), em anos, por sexo (Censos de 1970, 1980 e 1991)."],"table":[["Cidade","1970 H","1970 M","1980 H","1980 M","1991 H","1991 M"],["Niterói","58,29","67,11","60,63","70,38","61,57","73,09"],["Curitiba","52,79","62,52","61,90","70,70","63,83","72,61"],["Maceió","47,55","53,32","57,10","64,19","61,92","68,40"]],"items":[{"id":"x6-2.1","t":"O aumento da EVN se deve fundamentalmente à redução da mortalidade infantil.","e":"Das variáveis da dinâmica populacional, só a mortalidade interfere diretamente na EVN; fecundidade e migração não.","refs":[{"c":3,"p":62,"p2":63,"s":"s3-9"},{"c":6,"p":131,"p2":131,"s":"s6-3"}],"a":"V"},{"id":"x6-2.2","t":"A EVN é uma medida-resumo, calculada pela tábua de vida, que sintetiza o efeito da mortalidade em todas as idades.","e":"Ela aplica as taxas por idade a uma coorte fictícia.","refs":[{"c":3,"p":61,"p2":61,"s":"s3-9"}],"a":"V"},{"id":"x6-2.3","t":"A EVN maior das mulheres reflete a sobremortalidade masculina: maior mortalidade infantil masculina e mortes violentas entre homens jovens.","e":"É um padrão semelhante ao de países desenvolvidos.","refs":[{"c":3,"p":62,"p2":62,"s":"s3-9"},{"c":6,"p":132,"p2":132,"s":"s6-4"}],"a":"V"},{"id":"x6-2.4","t":"Curitiba teve o maior ganho e passou Niterói na EVN masculina, embora Niterói tivesse a maior EVN em 1970.","e":"Maceió em 1991 tinha valores pouco acima dos de Niterói em 1970: um sinal da desigualdade regional.","refs":[{"c":6,"p":148,"p2":148,"s":"s6-6"}],"a":"V"},{"id":"x6-2.5","t":"A EVN deve ser padronizada por idade antes de comparar as cidades.","e":"A EVN não depende da estrutura etária e pode ser comparada diretamente.","refs":[{"c":3,"p":62,"p2":62,"s":"s3-9"}],"a":"F"}],"cap":6,"ex":"Cap. 6, ex. 4 a 6","cad":{"p":28,"p2":29},"title":"Esperança de vida em Niterói, Curitiba e Maceió"},{"id":"x6-3","src":"caderno","type":"vf","ctx":["Óbitos de residentes em Niterói em 2005 (total 3.874), por capítulo da CID-10: circulatório (IX) 1.045; neoplasias (II) 706; respiratório (X) 454; causas externas (XX) 446; infecciosas e parasitárias (I) 225; sintomas e sinais mal definidos (XVIII) 296; demais capítulos somando o restante."],"items":[{"id":"x6-3.1","t":"Para calcular a mortalidade proporcional por causas definidas, convém retirar do total os óbitos por causas mal definidas: o denominador fica 3.578.","e":"3.874 − 296 = 3.578. Calcular à parte a proporção de mal definidas indica a qualidade do sistema.","refs":[{"c":3,"p":43,"p2":43,"s":"s3-4"},{"c":3,"p":49,"p2":49,"s":"s3-6"}],"a":"V"},{"id":"x6-3.2","t":"Com esse denominador, as doenças do aparelho circulatório respondem por cerca de 29% dos óbitos e as neoplasias por cerca de 20%.","e":"1.045/3.578 ≈ 29,2% e 706/3.578 ≈ 19,7%. Respiratório ≈ 12,7%, externas ≈ 12,5%, infecciosas ≈ 6,3%.","refs":[{"c":3,"p":43,"p2":43,"s":"s3-4"}],"a":"V"},{"id":"x6-3.3","t":"A proporção de óbitos por causas mal definidas em Niterói (cerca de 7,6%) foi relativamente baixa, ao contrário de Fortaleza no mesmo ano (cerca de 19,3%).","e":"296/3.874 ≈ 7,64%.","refs":[{"c":3,"p":49,"p2":50,"s":"s3-6"}],"a":"V"},{"id":"x6-3.4","t":"O padrão de Niterói, com circulatório e neoplasias somando cerca de 50% dos óbitos e mais de 60% com a terceira causa, se parece com o de países que completaram a transição.","e":"Por exemplo os EUA e os países europeus.","refs":[{"c":6,"p":134,"p2":134,"s":"s6-4"},{"c":6,"p":137,"p2":137,"s":"s6-5"}],"a":"V"},{"id":"x6-3.5","t":"Para caracterizar melhor o momento da transição epidemiológica, recomenda-se analisar causas específicas dentro dos grandes grupos, como Aids e hepatite B.","e":"Grandes capítulos podem esconder a persistência ou reemergência de doenças infecciosas.","refs":[{"c":6,"p":135,"p2":136,"s":"s6-4"}],"a":"V"}],"cap":6,"ex":"Cap. 6, ex. 7 a 9","cad":{"p":29,"p2":29},"title":"Mortalidade proporcional em Niterói (2005)"},{"id":"x8-1","src":"caderno","type":"choice","ctx":["Classifique cada estudo segundo o tipo de desenho. O caderno pede ainda a classificação pelos eixos: estratégia de observação, unidade de observação e momento de mensuração da exposição e do desfecho."],"items":[{"id":"x8-1.1","t":"Em 1982 identificou-se cada criança nascida em Pelotas e revisaram-se os registros de nascimento para conhecer o peso ao nascer. As crianças foram classificadas em peso normal (≥ 2.500 g) ou baixo peso e seguidas por um ano, comparando-se a mortalidade infantil nos dois grupos.","e":"Coorte: longitudinal, unidade individual, exposição e desfecho concorrentes (incidência). Apesar de vir de registros, a exposição é colhida no início, antes de se conhecer o desfecho.","refs":[{"c":8,"p":177,"p2":179,"s":"s8-3"}],"a":1},{"id":"x8-1.2","t":"Para avaliar a associação entre reserpina e câncer de mama, 100 pacientes internadas com câncer de mama (casos novos) num hospital geral, ao longo de dois anos, foram entrevistadas sobre o uso prévio de reserpina. Para cada caso, quatro controles foram sorteados entre mulheres internadas por outros diagnósticos no mesmo período.","e":"Caso-controle: longitudinal, individual, exposição não concorrente (uso passado) e desfecho concorrente (casos incidentes).","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":2},{"id":"x8-1.3","t":"Num inquérito domiciliar com amostra representativa de menores de 5 anos da Rocinha, as crianças foram pesadas e medidas (desnutrição) e colheram-se dados sobre nível socioeconômico, peso ao nascer, internação no último ano e aleitamento.","e":"Seccional (inquérito de prevalência): uma única medição, unidade individual, desfecho medido como prevalência. Pode haver viés de sobrevivência seletiva e ambiguidade temporal.","refs":[{"c":8,"p":177,"p2":178,"s":"s8-3"}],"a":3},{"id":"x8-1.4","t":"Trezentos diabéticos foram alocados aleatoriamente em dois grupos de 150: um recebeu um novo hipoglicemiante e o outro continuou com clorpropamida. O controle metabólico foi comparado após seis meses (glicemia e hemoglobina glicosilada).","e":"Ensaio clínico randomizado. Sem randomização seria um quase-experimento.","refs":[{"c":8,"p":176,"p2":177,"s":"s8-3"}],"a":0},{"id":"x8-1.5","t":"Áreas de uma localidade da Califórnia foram classificadas pelos níveis de partículas emitidas por indústrias químicas e de petróleo, e a incidência média anual de diversos cânceres foi calculada para cada área.","e":"Ecológico: seccional, unidade agregada (áreas).","refs":[{"c":8,"p":177,"p2":178,"s":"s8-3"}],"a":4},{"id":"x8-1.6","t":"Algumas pessoas tiveram intoxicação alimentar após uma festa de casamento. Suspeitando da maionese, entrevistaram-se todos os 200 convidados sobre o que comeram e se adoeceram.","e":"Coorte histórica: todos chegaram sadios e a exposição ocorreu na festa. A primeira impressão seria seccional (coleta simultânea), mas a sequência exposição → desfecho é clara e mede-se incidência.","refs":[{"c":8,"p":178,"p2":179,"s":"s8-3"}],"a":1},{"id":"x8-1.7","t":"Na mesma festa, entrevistaram-se todos os casos de intoxicação e apenas uma amostra dos convidados que não adoeceram.","e":"Seleção incompleta: caso-controle.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":2}],"cap":8,"ex":"Cap. 8, ex. 1","cad":{"p":35,"p2":36},"title":"Classifique os desenhos (caderno)","opts":["Estudo experimental","Estudo de coorte","Estudo caso-controle","Estudo transversal","Estudo ecológico","Nenhum dos anteriores"]},{"id":"x8-2","src":"caderno","type":"vf","ctx":["Todos os 17.368 nascimentos de 12 hospitais de uma cidade dos EUA em 1988 foram estudados. Uma equipe revisava diariamente os prontuários (parto, peso, pré-natal, uso de cocaína). Em alguns casos o uso de cocaína só foi identificado por testes pedidos para crianças nascidas com graves problemas de saúde. Baixo peso: 110 de 399 filhos de usuárias; 1.073 de 16.969 filhos de não usuárias."],"items":[{"id":"x8-2.1","t":"Segundo o caderno, trata-se de um estudo de coorte histórico com amostragem completa (todos os nascimentos da base).","e":"O desfecho é colhido junto com o nascimento; a exposição, retrospectivamente, nos registros de pré-natal.","refs":[{"c":8,"p":178,"p2":179,"s":"s8-3"}],"a":"V"},{"id":"x8-2.2","t":"Embora os autores falem em incidência acumulada, a interpretação mais correta é prevalência ao nascer e razão de prevalências.","e":"Os nascidos vivos representam as gestações que sobreviveram até o parto. Abortos precoces em usuárias podem gerar viés de sobrevivência seletiva.","refs":[{"c":2,"p":29,"p2":30,"s":"s2-5"}],"a":"V"},{"id":"x8-2.3","t":"Houve possível viés de informação (classificação) diferencial: crianças nascidas em más condições, inclusive com baixo peso, eram mais testadas para cocaína.","e":"A exposição foi mais bem detectada justamente no grupo com o desfecho, o que tende a superestimar a associação.","refs":[{"c":8,"p":174,"p2":174,"s":"s8-2"},{"c":8,"p":176,"p2":176,"s":"s8-3"}],"a":"V"},{"id":"x8-2.4","t":"A proporção de baixo peso foi semelhante entre filhos de usuárias e de não usuárias.","e":"110/399 ≈ 27,6% contra 1.073/16.969 ≈ 6,3%: mais de quatro vezes maior.","refs":[{"c":2,"p":26,"p2":26,"s":"s2-5"}],"a":"F"},{"id":"x8-2.5","t":"Como a equipe revisava os prontuários diariamente, não há risco de viés de informação nesse estudo.","e":"A revisão diária ajuda, mas o teste de cocaína pedido seletivamente introduz viés diferencial.","refs":[{"c":8,"p":174,"p2":174,"s":"s8-2"}],"a":"F"}],"cap":8,"ex":"Cap. 8, ex. 2","cad":{"p":36,"p2":36},"title":"Cocaína na gestação e baixo peso ao nascer"},{"id":"x8-3","src":"caderno","type":"vf","ctx":["(1) Vários estudos mostram associação em \"J\" entre consumo de álcool e mortalidade cardiovascular. Discute-se se algum tipo de bebida protege mais que outros, com evidências de estudos ecológicos, caso-controle e de coorte. (2) Estudos observacionais associaram a terapia de reposição hormonal (TRH) em mulheres na pós-menopausa a menor risco de doença coronariana."],"items":[{"id":"x8-3.1","t":"Estudos ecológicos que comparam o consumo per capita de cada bebida com a mortalidade cardiovascular entre países estão sujeitos à falácia ecológica e não controlam confundidores (ex.: quem bebe vinho pode ter nível socioeconômico maior).","e":"Por outro lado, são rápidos, baratos e bons para gerar hipóteses.","refs":[{"c":8,"p":177,"p2":178,"s":"s8-3"}],"a":"V"},{"id":"x8-3.2","t":"No caso-controle sobre álcool, a lembrança diferencial do consumo por casos e controles pode causar viés de informação, e escolher controles comparáveis é difícil.","e":"Por outro lado, ele usa dados individuais e é mais rápido e barato que a coorte.","refs":[{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":"V"},{"id":"x8-3.3","t":"A coorte reduz os vieses de informação e seleção e estabelece a sequência temporal, mas é longa e cara e pode ter perdas seletivas.","e":"Ela permite medir diretamente a incidência.","refs":[{"c":8,"p":178,"p2":179,"s":"s8-3"}],"a":"V"},{"id":"x8-3.4","t":"Se mulheres que fazem TRH têm hábitos mais saudáveis (não fumar, exercício, boa dieta), a menor incidência de doença coronariana entre elas pode não ser efeito da TRH.","e":"O gabarito chama isso de viés de seleção; também se descreve como confundimento.","refs":[{"c":8,"p":174,"p2":174,"s":"s8-2"}],"a":"V"},{"id":"x8-3.5","t":"Um ensaio clínico randomizado evitaria esse problema, ao custo de exigir muitas participantes e longo acompanhamento.","e":"Uma alternativa observacional seria comparar doses de hormônio e buscar um gradiente dose-resposta.","refs":[{"c":8,"p":176,"p2":177,"s":"s8-3"}],"a":"V"}],"cap":8,"ex":"Cap. 8, ex. 3 e 4","cad":{"p":36,"p2":37},"title":"Álcool, TRH e escolha do desenho"},{"id":"x18-1","src":"caderno","type":"vf","ctx":["Dados simulados de 7 pacientes com infarto. Sexo: f, m, m, m, f, f, f. PA sistólica (mmHg): 140, 130, 150, 120, 140, 130, 120. IMC (kg/m²): 27, 25, 20, 32, 30, 36, 28. Cigarros por dia: 0, 10, 15, 25, 25, 20, 0. Escolaridade: 1º grau, 1º grau, 2º grau, superior, 2º grau, 1º grau, 1º grau."],"items":[{"id":"x18-1.1","t":"A pressão sistólica tem média de cerca de 132,9 mmHg, mediana de 130 mmHg e amplitude de 30 mmHg.","e":"Soma 930/7 ≈ 132,9; ordenando, o 4º valor é 130; 150 − 120 = 30. O desvio-padrão é cerca de 11,1 mmHg.","refs":[{"c":18,"p":329,"p2":333,"s":"s18-3"}],"a":"V"},{"id":"x18-1.2","t":"A distribuição da pressão sistólica é trimodal (120, 130 e 140 mmHg).","e":"Os três valores aparecem duas vezes cada.","refs":[{"c":18,"p":329,"p2":329,"s":"s18-3"}],"a":"V"},{"id":"x18-1.3","t":"Número de cigarros e frequência cardíaca são variáveis quantitativas discretas; idade, pressão, IMC e colesterol são contínuas; escolaridade é qualitativa ordinal.","e":"Sexo é qualitativa nominal.","refs":[{"c":18,"p":324,"p2":325,"s":"s18-1"}],"a":"V"},{"id":"x18-1.4","t":"Categorizar o fumo em não-fumante, leve, moderado e fumante cria uma variável ordinal, para a qual faz sentido calcular a frequência acumulada.","e":"Não-fumante 2 (28,6%), leve 0, moderado 2 (acumulado 57,2%), fumante 3 (acumulado 100%).","refs":[{"c":18,"p":324,"p2":324,"s":"s18-1"},{"c":18,"p":327,"p2":327,"s":"s18-2"}],"a":"V"},{"id":"x18-1.5","t":"Como as mulheres tiveram IMC médio maior (30,25 contra 25,67 kg/m² nos homens), está demonstrado que o sexo feminino causa obesidade nesses pacientes.","e":"Os dados sugerem diferença, mas com 7 pacientes ela pode ser casual. Além disso, descrição não prova causalidade.","refs":[{"c":18,"p":337,"p2":337,"s":"s18-5"},{"c":8,"p":174,"p2":174,"s":"s8-2"}],"a":"F"}],"cap":18,"ex":"Cap. 18, ex. 1","cad":{"p":80,"p2":80},"title":"Pacientes internados com infarto (7 casos)"},{"id":"x18-2","src":"caderno","type":"vf","ctx":["Numa amostra de 50 adultos de um inquérito sobre hipertensão na Ilha do Governador (RJ), o IMC médio foi 27,2 kg/m² nos hipertensos e 23,9 nos normotensos. Classificando como obesos os com IMC ≥ 27 kg/m²:"],"table":[["Obesidade","Hipertensos","Normotensos","Total"],["Não obeso","8","31","39"],["Obeso","5","6","11"],["Total","13","37","50"]],"items":[{"id":"x18-2.1","t":"A média de IMC maior entre os hipertensos sugere associação entre obesidade e hipertensão.","e":"Comparar medidas-resumo de uma variável quantitativa entre categorias é uma análise bivariada.","refs":[{"c":18,"p":340,"p2":340,"s":"s18-5"}],"a":"V"},{"id":"x18-2.2","t":"Entre os obesos, 45,5% eram hipertensos, contra 20,5% entre os não obesos.","e":"5/11 ≈ 45,45% e 8/39 ≈ 20,51%: percentuais na linha, mais que o dobro.","refs":[{"c":18,"p":338,"p2":338,"s":"s18-5"}],"a":"V"},{"id":"x18-2.3","t":"Tanto a análise com a variável contínua (IMC) quanto a com a categorizada (corte em 27 kg/m²) sugerem a mesma associação.","e":"São duas formas de explorar a relação.","refs":[{"c":18,"p":338,"p2":340,"s":"s18-5"}],"a":"V"},{"id":"x18-2.4","t":"Numa tabela de dupla entrada, os totais marginais indicam se as duas variáveis estão associadas.","e":"Os totais marginais correspondem às análises univariadas. A associação aparece comparando os percentuais condicionais (por linha ou coluna).","refs":[{"c":18,"p":338,"p2":338,"s":"s18-5"}],"a":"F"},{"id":"x18-2.5","t":"Esse resultado comprova que a obesidade causa hipertensão.","e":"É uma análise exploratória de dados seccionais: sugere uma hipótese, a ser testada estatisticamente e com desenhos adequados.","refs":[{"c":18,"p":337,"p2":337,"s":"s18-5"},{"c":8,"p":178,"p2":178,"s":"s8-3"}],"a":"F"}],"cap":18,"ex":"Cap. 18, ex. 2","cad":{"p":80,"p2":80},"title":"Obesidade e hipertensão (Ilha do Governador)"},{"id":"x18-3","src":"caderno","type":"choice","ctx":["Área de superfície corporal (m²) de 13 pacientes: 2,10; 1,74; 1,68; 1,83; 1,57; 1,71; 1,73; 1,65; 1,74; 1,57; 2,76; 1,90; 1,77."],"items":[{"id":"x18-3.1","t":"Qual é a média?","e":"Soma 23,75 / 13 ≈ 1,83 m².","refs":[{"c":18,"p":329,"p2":329,"s":"s18-3"}],"a":0},{"id":"x18-3.2","t":"Qual é a mediana?","e":"Ordenados, o 7º valor ((13 + 1)/2) é 1,74 m².","refs":[{"c":18,"p":330,"p2":330,"s":"s18-3"}],"a":1},{"id":"x18-3.3","t":"Qual é a moda?","e":"Distribuição bimodal: 1,57 e 1,74 aparecem duas vezes cada.","refs":[{"c":18,"p":329,"p2":329,"s":"s18-3"}],"a":2},{"id":"x18-3.4","t":"Qual é a amplitude total?","e":"2,76 − 1,57 = 1,19 m².","refs":[{"c":18,"p":331,"p2":331,"s":"s18-3"}],"a":3},{"id":"x18-3.5","t":"Qual é o desvio-padrão amostral (dividindo por n − 1)?","e":"Variância = 1,18/12 ≈ 0,10 m⁴; DP = √0,10 ≈ 0,31 m². Divide-se por n − 1 (graus de liberdade) por ser amostra.","refs":[{"c":18,"p":332,"p2":333,"s":"s18-3"}],"a":4}],"cap":18,"ex":"Cap. 18, ex. 3","cad":{"p":80,"p2":81},"title":"Cálculo: área de superfície corporal","opts":["1,83 m²","1,74 m²","1,57 e 1,74 m²","1,19 m²","0,31 m²"]},{"id":"x18-4","src":"caderno","type":"vf","ctx":["(1) Permanência hospitalar em 1993 (dias): HUCFF: mediana 8, Q1 3, Q3 17, máximo 405, média 12,7 (DP 15,1). HSE: mediana 4, máximo 374, média 8,9. HMSA: mediana 7, máximo 1.101, média 13,9 (DP 24,3). (2) Pacientes com um problema de saúde X: hospital A, 50 altas e 30 óbitos; B, 90 altas e 30 óbitos; C, 25 altas e 25 óbitos."],"items":[{"id":"x18-4.1","t":"Para caracterizar a permanência hospitalar, a mediana é mais indicada que a média.","e":"As distribuições são assimétricas à direita (média > mediana), e poucos valores extremos (até 1.101 dias) distorcem a média.","refs":[{"c":18,"p":330,"p2":330,"s":"s18-3"}],"a":"V"},{"id":"x18-4.2","t":"O número de óbitos foi igual nos hospitais A e B.","e":"Foram 30 em cada um.","refs":[{"c":18,"p":334,"p2":334,"s":"s18-4"}],"a":"V"},{"id":"x18-4.3","t":"A frequência percentual de óbitos foi a mesma nos hospitais A e B.","e":"A: 30/80 = 37,5%; B: 30/120 = 25%. É preciso considerar o total de internados.","refs":[{"c":18,"p":327,"p2":327,"s":"s18-2"}],"a":"F"},{"id":"x18-4.4","t":"Proporcionalmente, a mortalidade foi maior no hospital C (50%).","e":"Um gráfico com frequências percentuais mostra isso melhor que o de números absolutos: C, seguido de A.","refs":[{"c":18,"p":327,"p2":327,"s":"s18-2"},{"c":18,"p":334,"p2":334,"s":"s18-4"}],"a":"V"},{"id":"x18-4.5","t":"O hospital B foi o que mais internou pacientes com o problema X (120).","e":"A internou 80 e C internou 50.","refs":[{"c":18,"p":334,"p2":334,"s":"s18-4"}],"a":"V"}],"cap":18,"ex":"Cap. 18, ex. 4 a 6","cad":{"p":81,"p2":82},"title":"Permanência hospitalar e óbitos por hospital"}],"pdfs":[{"key":"Cap1","from":1,"to":12,"offset":0},{"key":"Cap2","from":13,"to":30,"offset":12},{"key":"Cap3_Pt1","from":31,"to":55,"offset":30},{"key":"Cap3_Pt2","from":56,"to":82,"offset":55},{"key":"Cap4","from":83,"to":102,"offset":82},{"key":"Cap5","from":103,"to":122,"offset":102},{"key":"Cap6","from":123,"to":151,"offset":122},{"key":"Cap8e18","from":173,"to":179,"offset":172},{"key":"Cap8e18","from":323,"to":341,"offset":315}],"caderno":[{"from":1,"to":29,"offset":0},{"from":33,"to":37,"offset":3},{"from":77,"to":82,"offset":42}]};
